def major_repetition_phase_sequence(values: list[float]) -> list[str]:
    """Collapse a motion track into robust low/high phase visits.

    The hysteresis band ignores mid-range samples and small tracking jitter.
    A clean return-to-start repetition is low-high-low or high-low-high;
    additional visits indicate multiple repetitions or mixed partial cycles.
    """
    if len(values) < FULL_REPETITION_PHASE_COMPLETENESS_MIN_FRAMES:
        return []
    minimum = min(values)
    value_range = max(values) - minimum
    if value_range <= 1e-8:
        return []
    normalized = [(float(value) - minimum) / value_range for value in values]
    sequence: list[str] = []
    for value in normalized:
        phase = "low" if value <= 0.30 else "high" if value >= 0.70 else None
        if phase is not None and (not sequence or sequence[-1] != phase):
            sequence.append(phase)
    return sequence


def robust_phase_track_values(values: list[float]) -> list[float]:
    """Suppress isolated pose jitter without shifting the repetition timeline."""
    numeric = [float(value) for value in values]
    # Very short tracks are already sparse evidence; a median filter can erase
    # their sole interior extreme.  Exact-video validation normally has many
    # more samples, where isolated detector jitter can be removed safely.
    if len(numeric) < 7:
        return numeric
    smoothed: list[float] = []
    for index in range(len(numeric)):
        if index == 0:
            # Preserve the actual clip boundary. Replacing it with a local
            # median can hide a completed return that finishes with small
            # tracker drift beyond the initial coordinate.
            smoothed.append(numeric[index])
            continue
        elif index == len(numeric) - 1:
            smoothed.append(numeric[index])
            continue
        else:
            neighborhood = numeric[index - 1 : index + 2]
        smoothed.append(float(statistics.median(neighborhood)))
    raw_phase_sequence = major_repetition_phase_sequence(numeric)
    smoothed_phase_sequence = major_repetition_phase_sequence(smoothed)
    if len(raw_phase_sequence) >= 5 and len(smoothed_phase_sequence) < len(raw_phase_sequence):
        # Repeated alternating excursions are evidence of multiple cycles, not
        # an isolated detector spike. Keep them visible so an overlong cut is
        # rejected instead of being flattened into an apparently clean clip.
        return numeric
    return smoothed


def trim_isolated_endpoint_phase_outliers(values: list[float]) -> list[float]:
    if len(values) < 3:
        return [float(value) for value in values]
    trimmed = [float(value) for value in values]
    if abs(trimmed[0] - trimmed[1]) > max(abs(trimmed[1] - trimmed[2]), 1e-8) * 1.5:
        trimmed[0] = trimmed[1]
    if abs(trimmed[-1] - trimmed[-2]) > max(abs(trimmed[-2] - trimmed[-3]), 1e-8) * 1.5:
        trimmed[-1] = trimmed[-2]
    return trimmed


def phase_track_signal_evidence(values: list[float]) -> dict[str, Any]:
    """Resolve motion against noise measured from the same pose track.

    This deliberately avoids a fixed body-size or exercise-specific amplitude
    floor.  A phase excursion is usable when it separates from the track's
    endpoint variability and from the high-frequency residual removed by the
    deterministic median smoother.
    """
    raw_values = trim_isolated_endpoint_phase_outliers(values)
    smoothed_values = robust_phase_track_values(raw_values)
    if not smoothed_values:
        return {
            "resolved": False,
            "reason": "empty_phase_track",
            "smoothedValues": smoothed_values,
        }

    endpoint_sample_count = max(1, int(round(math.sqrt(len(smoothed_values)) / 2.0)))
    endpoint_values = (
        smoothed_values[:endpoint_sample_count]
        + smoothed_values[-endpoint_sample_count:]
    )
    baseline = float(statistics.median(endpoint_values))
    baseline_deviations = [abs(value - baseline) for value in endpoint_values]
    endpoint_noise = float(statistics.median(baseline_deviations)) if baseline_deviations else 0.0

    residuals = [abs(raw - smooth) for raw, smooth in zip(raw_values, smoothed_values)]
    residual_noise = float(statistics.median(residuals)) if residuals else 0.0
    noise_envelope = endpoint_noise + residual_noise
    turning_excursion = max(abs(value - baseline) for value in smoothed_values)
    resolved = turning_excursion > noise_envelope and turning_excursion > 0.0
    return {
        "resolved": resolved,
        "reason": "phase_excursion_separates_from_clip_noise" if resolved else "phase_excursion_not_resolved_from_clip_noise",
        "smoothedValues": smoothed_values,
        "endpointSampleCount": endpoint_sample_count,
        "baselineValue": baseline,
        "endpointNoise": endpoint_noise,
        "residualNoise": residual_noise,
        "noiseEnvelope": noise_envelope,
        "turningExcursion": turning_excursion,
        "excursionToNoiseRatio": (
            turning_excursion / noise_envelope
            if noise_envelope > 1e-12
            else None
        ),
    }


def has_exactly_one_major_repetition_cycle(values: list[float]) -> tuple[bool, list[str]]:
    sequence = major_repetition_phase_sequence(values)
    return (
        len(sequence) == 3
        and sequence[0] == sequence[2]
        and sequence[0] != sequence[1],
        sequence,
    )


def has_one_or_more_major_repetition_cycles(values: list[float]) -> tuple[bool, list[str]]:
    sequence = major_repetition_phase_sequence(values)
    alternating = all(sequence[index] != sequence[index - 1] for index in range(1, len(sequence)))
    return (
        len(sequence) >= 3
        and len(sequence) % 2 == 1
        and sequence[0] == sequence[-1]
        and alternating,
        sequence,
    )


def launch_chromium_browser(
    playwright: Any,
    *,
    fallback_executables: Iterable[Path] | None = None,
) -> Any:
    launch_options = {
        "headless": True,
        # Generated previews import the adjacent Three.js module from a file:// URL.
        # Chromium otherwise blocks that module for an opaque local-file origin.
        "args": ["--allow-file-access-from-files"],
    }
    try:
        return playwright.chromium.launch(**launch_options)
    except Exception as primary_exc:
        fallback_errors: list[str] = []
        for executable_path in fallback_executables or default_chromium_executable_candidates():
            if not executable_path.exists():
                continue
            try:
                return playwright.chromium.launch(
                    **launch_options,
                    executable_path=str(executable_path),
                )
            except Exception as fallback_exc:
                fallback_errors.append(f"{executable_path}: {fallback_exc}")
        detail = f" Fallback launch failures: {'; '.join(fallback_errors)}" if fallback_errors else ""
        raise RuntimeError(
            "Playwright could not launch Chromium. Install the bundled browser with "
            "`python -m playwright install chromium`, or install Chrome/Edge so the "
            f"pipeline can use a system browser.{detail}"
        ) from primary_exc


def default_chromium_executable_candidates() -> list[Path]:
    candidates: list[Path] = []
    env_path = os.environ.get("PLAYWRIGHT_CHROMIUM_EXECUTABLE") or os.environ.get("CHROME_EXECUTABLE")
    if env_path:
        candidates.append(Path(env_path))
    for command in ("chrome", "chrome.exe", "msedge", "msedge.exe", "chromium", "chromium.exe"):
        resolved = shutil.which(command)
        if resolved:
            candidates.append(Path(resolved))
    candidates.extend(
        [
            Path("C:/Program Files/Google/Chrome/Application/chrome.exe"),
            Path("C:/Program Files (x86)/Google/Chrome/Application/chrome.exe"),
            Path("C:/Program Files/Microsoft/Edge/Application/msedge.exe"),
            Path("C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe"),
        ]
    )
    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).lower()
        if key in seen:
            continue
        seen.add(key)
        unique.append(candidate)
    return unique


@dataclass(frozen=True)
class SourceChunkHint:
    start_seconds: float
    end_seconds: float
    score: float | None = None

    @property
    def duration_seconds(self) -> float:
        return max(0.0, self.end_seconds - self.start_seconds)


@dataclass(frozen=True)
class RankedCandidate:
    exercise_index: int
    candidate_rank: int
    exercise_id: str
    exercise_name: str
    exercise_slug: str
    candidate: dict[str, Any]

    @property
    def url(self) -> str | None:
        value = self.candidate.get("url") or self.candidate.get("videoUrl") or self.candidate.get("webpageUrl")
        return str(value).strip() if value else None

    @property
    def video_path(self) -> Path | None:
        value = self.candidate.get("videoPath") or self.candidate.get("sourceVideoPath")
        return Path(str(value)) if value else None

    @property
    def video_id(self) -> str | None:
        value = self.candidate.get("videoId") or self.candidate.get("id")
        return str(value).strip() if value else None

    @property
    def title(self) -> str:
        value = self.candidate.get("title")
        return str(value).strip() if value else f"candidate-{self.candidate_rank + 1}"

    @property
    def workspace_slug(self) -> str:
        identity = self.video_id or self.title or str(self.candidate_rank + 1)
        base_slug = f"{self.exercise_slug}-{self.candidate_rank + 1:03d}-{identity}"
        source_window_attempt = parse_optional_int(self.candidate.get("sourceWindowAttemptIndex"))
        if source_window_attempt is not None:
            hint = self.source_chunk_hint
            if hint is not None:
                base_slug = (
                    f"{base_slug}-window-{source_window_attempt + 1:02d}-"
                    f"{int(round(hint.start_seconds * 1000.0))}-"
                    f"{int(round(hint.end_seconds * 1000.0))}"
                )
            else:
                base_slug = f"{base_slug}-window-{source_window_attempt + 1:02d}"
        return slugify(base_slug)[:120]

    @property
    def source_chunk_hint(self) -> SourceChunkHint | None:
        explicit_hint = self.candidate.get("sourceWindowHint")
        if isinstance(explicit_hint, dict):
            start_seconds = parse_optional_float(explicit_hint.get("startSeconds"))
            end_seconds = parse_optional_float(explicit_hint.get("endSeconds"))
            if start_seconds is not None and end_seconds is not None and end_seconds > start_seconds:
                return SourceChunkHint(
                    start_seconds=max(0.0, start_seconds),
                    end_seconds=end_seconds,
                    score=parse_optional_float(explicit_hint.get("score")),
                )
        payload = self.candidate.get("visionPayload")
        if not isinstance(payload, dict):
            return None
        start_seconds = parse_optional_float(payload.get("bestChunkStartSeconds"))
        end_seconds = parse_optional_float(payload.get("bestChunkEndSeconds"))
        score = parse_optional_float(payload.get("bestChunkScore"))
        valid_chunk_count = parse_optional_int(payload.get("validChunkCount"))
        pose_payload = payload.get("posePrefilter")
        deterministic_source_fallback = isinstance(payload.get("deterministicSourceFallback"), dict)
        best_chunk_source = str(payload.get("bestChunkSource") or "").strip().lower()
        pose_score = None
        pose_start_seconds = None
        pose_end_seconds = None
        pose_hint_duration = None
        if isinstance(pose_payload, dict):
            pose_score = parse_optional_float(pose_payload.get("score"))
            pose_start_seconds = parse_optional_float(pose_payload.get("bestChunkStartSeconds"))
            pose_end_seconds = parse_optional_float(pose_payload.get("bestChunkEndSeconds"))
            if pose_start_seconds is not None and pose_end_seconds is not None:
                pose_hint_duration = max(0.0, pose_end_seconds - pose_start_seconds)
        pose_hint_valid = (
            isinstance(pose_payload, dict)
            and pose_start_seconds is not None
            and pose_end_seconds is not None
            and pose_end_seconds > pose_start_seconds
        )
        pose_hint_strong = (
            pose_hint_valid
            and pose_score is not None
            and pose_score >= SOURCE_GATE_STRONG_BEST_CHUNK_SCORE
            and pose_hint_duration is not None
            and pose_hint_duration <= SOURCE_GATE_MAX_DIRECT_CHUNK_SECONDS
        )
        use_pose_hint = (
            pose_hint_valid
            and (
                start_seconds is None
                or end_seconds is None
                or best_chunk_source == "pose_prefilter"
                or (
                    bool(pose_payload.get("passed"))
                    and pose_score is not None
                    and pose_hint_strong
                    and not deterministic_source_fallback
                    and (
                        score is None
                        or score < SOURCE_GATE_STRONG_BEST_CHUNK_SCORE
                        or valid_chunk_count == 0
                    )
                )
            )
        )
        if use_pose_hint:
            start_seconds = pose_start_seconds
            end_seconds = pose_end_seconds
            score = pose_score
        if start_seconds is None or end_seconds is None or end_seconds <= start_seconds:
            return None
        return SourceChunkHint(
            start_seconds=max(0.0, start_seconds),
            end_seconds=end_seconds,
            score=score,
        )


TERMINAL_FINAL_SELECTION_STATUSES = {
    "not_reviewable",
    "rejected_after_materialized_review",
}

TERMINAL_CANDIDATE_STATUSES = {
    "skipped_source_gate",
    "skipped_pre_wham_source_validation",
}


def ranked_candidate_attempt_key(ranked_candidate: RankedCandidate) -> str:
    explicit_key = ranked_candidate.candidate.get("sourceWindowAttemptKey")
    if isinstance(explicit_key, str) and explicit_key.strip():
        return explicit_key.strip()
    identity = (
        ranked_candidate.video_id
        or ranked_candidate.url
        or str(ranked_candidate.video_path or "")
        or ranked_candidate.title
        or str(ranked_candidate.candidate_rank)
    )
    hint = ranked_candidate.source_chunk_hint
    if hint is None:
        chunk_key = "full"
    else:
        chunk_key = f"{hint.start_seconds:.3f}-{hint.end_seconds:.3f}"
    attempt_mode = str(ranked_candidate.candidate.get("sourceWindowAttemptMode") or "").strip()
    return "|".join(
        [part for part in [
            slugify(ranked_candidate.exercise_id or ranked_candidate.exercise_name),
            str(identity).strip().lower(),
            chunk_key,
            slugify(attempt_mode) if attempt_mode else "",
        ] if part]
    )


def ranked_candidate_source_family_key(ranked_candidate: RankedCandidate) -> str | None:
    identity = (
        ranked_candidate.video_id
        or ranked_candidate.url
        or str(ranked_candidate.video_path or "")
        or ranked_candidate.title
        or str(ranked_candidate.candidate_rank)
    )
    identity = str(identity).strip().lower()
    if not identity:
        return None
    return "|".join(
        [
            slugify(ranked_candidate.exercise_id or ranked_candidate.exercise_name),
            slugify(identity) or hashlib.sha1(identity.encode("utf-8")).hexdigest()[:16],
        ]
    )


def candidate_result_attempt_key(result: dict[str, Any]) -> str | None:
    explicit_key = result.get("sourceWindowAttemptKey")
    if isinstance(explicit_key, str) and explicit_key.strip():
        return explicit_key.strip()
    candidate = result.get("candidate")
    if not isinstance(candidate, dict):
        return None
    ranked_candidate = RankedCandidate(
        exercise_index=parse_optional_int(result.get("exerciseIndex")) or 0,
        candidate_rank=parse_optional_int(result.get("candidateRank")) or 0,
        exercise_id=str(result.get("exerciseId") or result.get("exerciseName") or "exercise"),
        exercise_name=str(result.get("exerciseName") or result.get("exerciseId") or "exercise"),
        exercise_slug=slugify(str(result.get("exerciseId") or result.get("exerciseName") or "exercise")),
        candidate=candidate,
    )
    return ranked_candidate_attempt_key(ranked_candidate)


def candidate_result_has_terminal_quality_decision(result: dict[str, Any]) -> bool:
    status = str(result.get("status") or "").strip()
    if status == "failed":
        for failure in result.get("failures") or []:
            if not isinstance(failure, dict):
                continue
            reason = str(failure.get("reason") or "").strip()
            message = str(failure.get("message") or "").strip()
            if reason == "pre_wham_source_validation_rejected":
                return True
            if message.startswith("Source segment detection did not find a usable "):
                return True
        return False
    final_status = str(result.get("finalSelectionStatus") or "").strip()
    if final_status in TERMINAL_FINAL_SELECTION_STATUSES:
        return True
    if status in TERMINAL_CANDIDATE_STATUSES:
        return True
    return False


def load_previous_terminal_candidate_results(workspace: Path) -> dict[str, dict[str, Any]]:
    previous: dict[str, dict[str, Any]] = {}

    try:
        active_policy_mtime = Path(__file__).stat().st_mtime
    except OSError:
        active_policy_mtime = 0.0

    def manifest_uses_current_policy(path: Path) -> bool:
        if active_policy_mtime <= 0.0:
            return True
        try:
            return path.stat().st_mtime + 1e-6 >= active_policy_mtime
        except OSError:
            return False

    def add_result(result: dict[str, Any]) -> None:
        previous_terminal_result = result.get("previousTerminalResult")
        if str(result.get("status") or "").strip() == "skipped_previous_terminal_result":
            if isinstance(previous_terminal_result, dict):
                result = previous_terminal_result
            else:
                previous_status = str(result.get("previousStatus") or "").strip()
                previous_final_status = str(result.get("previousFinalSelectionStatus") or "").strip()
                if (
                    previous_status not in TERMINAL_CANDIDATE_STATUSES
                    and previous_final_status not in TERMINAL_FINAL_SELECTION_STATUSES
                ):
                    return
                key = candidate_result_attempt_key(result)
                if key:
                    previous.setdefault(key, result)
                return
        if not candidate_result_has_terminal_quality_decision(result):
            return
        key = candidate_result_attempt_key(result)
        if key:
            previous.setdefault(key, result)

    selection_path = workspace / "selection_manifest.json"
    if selection_path.exists() and manifest_uses_current_policy(selection_path):
        try:
            manifest = json.loads(selection_path.read_text(encoding="utf-8"))
        except Exception:
            manifest = {}
        results = manifest.get("candidateResults") if isinstance(manifest, dict) else None
        if isinstance(results, list):
            for result in results:
                if isinstance(result, dict):
                    add_result(result)

    try:
        bake_manifest_paths = list(workspace.rglob("bake_manifest.json"))
    except OSError:
        bake_manifest_paths = []
    for manifest_path in bake_manifest_paths:
        if not manifest_uses_current_policy(manifest_path):
            continue
        try:
            result = json.loads(manifest_path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if isinstance(result, dict):
            add_result(result)
    return previous


def build_skipped_previous_terminal_result(
    ranked_candidate: RankedCandidate,
    previous_result: dict[str, Any],
) -> dict[str, Any]:
    candidate_workspace = Path(str(previous_result.get("candidateWorkspace") or "")) if previous_result.get("candidateWorkspace") else None
    if candidate_workspace is None:
        candidate_workspace = Path()
    result = {
        "exerciseIndex": ranked_candidate.exercise_index,
        "candidateRank": ranked_candidate.candidate_rank,
        "exerciseId": ranked_candidate.exercise_id,
        "exerciseName": ranked_candidate.exercise_name,
        "candidate": ranked_candidate.candidate,
        "candidateWorkspace": str(candidate_workspace),
        "status": "skipped_previous_terminal_result",
        "finalSelectionStatus": "skipped_previous_terminal_result",
        "previousStatus": previous_result.get("status"),
        "previousFinalSelectionStatus": previous_result.get("finalSelectionStatus"),
        "previousTerminalResult": copy.deepcopy(previous_result),
        "previousAttemptKey": ranked_candidate_attempt_key(ranked_candidate),
        "reviewSourceClips": [],
        "rejectedSourceClips": [],
        "failures": [
            {
                "reason": "previous_terminal_quality_decision",
                "message": "Skipped because this exact source candidate/window already ended in a terminal quality decision.",
            }
        ],
        "timings": {"totalSeconds": 0.0},
    }
    result.update(source_window_attempt_manifest(ranked_candidate))
    return result


def build_skipped_blocked_source_family_result(
    ranked_candidate: RankedCandidate,
    source_family_block: dict[str, Any],
) -> dict[str, Any]:
    result = {
        "exerciseIndex": ranked_candidate.exercise_index,
        "candidateRank": ranked_candidate.candidate_rank,
        "exerciseId": ranked_candidate.exercise_id,
        "exerciseName": ranked_candidate.exercise_name,
        "candidate": ranked_candidate.candidate,
        "status": "skipped_blocked_source_family",
        "finalSelectionStatus": "skipped_blocked_source_family",
        "sourceFamilyBlock": copy.deepcopy(source_family_block),
        "sourceFamilyBlockKey": source_family_block.get("sourceFamilyKey"),
        "sourceFamilyBlockReason": source_family_block.get("reason"),
        "reviewSourceClips": [],
        "rejectedSourceClips": [],
        "failures": [
            {
                "reason": "source_family_blocked_after_terminal_rejection",
                "message": "Skipped because another window from the same source video already produced a deterministic source-level failure.",
                "sourceFamilyBlockReason": source_family_block.get("reason"),
                "sourceFamilyBlockAttemptKey": source_family_block.get("sourceWindowAttemptKey"),
            }
        ],
        "timings": {"totalSeconds": 0.0},
    }
    result.update(source_window_attempt_manifest(ranked_candidate))
    return result


def ranked_candidates_to_process_with_previous_terminal_skips(
    candidates: list[RankedCandidate],
    *,
    request: BakeAndRankRequest,
    fallback_ready_target: int,
) -> tuple[list[tuple[int, RankedCandidate]], dict[int, dict[str, Any]]]:
    previous_terminal_results = (
        load_previous_terminal_candidate_results(request.workspace)
        if request.reuse_previous_terminal_results
        else {}
    )
    candidates_to_process: list[tuple[int, RankedCandidate]] = []
    skipped_by_original_index: dict[int, dict[str, Any]] = {}
    new_candidate_count = 0
    for original_index, ranked_candidate in enumerate(candidates):
        attempt_key = ranked_candidate_attempt_key(ranked_candidate)
        previous_terminal_result = previous_terminal_results.get(attempt_key)
        if previous_terminal_result is not None:
            skipped_by_original_index[original_index] = build_skipped_previous_terminal_result(
                ranked_candidate,
                previous_terminal_result,
            )
            continue
        if request.pre_wham_source_validation and new_candidate_count >= fallback_ready_target:
            break
        candidates_to_process.append((original_index, ranked_candidate))
        new_candidate_count += 1
    return candidates_to_process, skipped_by_original_index


@dataclass(frozen=True)
class SourceWindowVariant:
    hint: SourceChunkHint
    source: str
    original_index: int | None = None


def source_chunk_hint_manifest(hint: SourceChunkHint | None) -> dict[str, Any] | None:
    if hint is None:
        return None
    return {
        "startSeconds": hint.start_seconds,
        "endSeconds": hint.end_seconds,
        "durationSeconds": hint.duration_seconds,
        "score": hint.score,
    }


def source_window_attempt_manifest(ranked_candidate: RankedCandidate) -> dict[str, Any]:
    hint = ranked_candidate.source_chunk_hint
    return {
        "sourceWindowAttemptKey": ranked_candidate_attempt_key(ranked_candidate),
        "sourceWindowAttemptIndex": parse_optional_int(ranked_candidate.candidate.get("sourceWindowAttemptIndex")),
        "sourceWindowAttemptSource": ranked_candidate.candidate.get("sourceWindowAttemptSource"),
        "sourceWindowAttemptMode": ranked_candidate.candidate.get("sourceWindowAttemptMode"),
        "sourceWindowParentFallback": parse_optional_bool(
            ranked_candidate.candidate.get("sourceWindowParentFallback")
        ),
        "sourceWindowParentFallbackReason": ranked_candidate.candidate.get("sourceWindowParentFallbackReason"),
        "sourceWindowParentFallbackChildWindow": ranked_candidate.candidate.get(
            "sourceWindowParentFallbackChildWindow"
        ),
        "sourceWindow": source_chunk_hint_manifest(hint),
    }


def source_window_key(hint: SourceChunkHint) -> tuple[int, int]:
    return (
        int(round(hint.start_seconds * 1000.0)),
        int(round(hint.end_seconds * 1000.0)),
    )


def source_window_usable_for_attempt(
    hint: SourceChunkHint,
    request: BakeAndRankRequest,
    *,
    ranked_candidate: RankedCandidate | None = None,
    min_seconds_override: float | None = None,
) -> bool:
    if hint.end_seconds <= hint.start_seconds:
        return False
    base_min_seconds = max(0.5, float(request.segment_min_seconds))
    min_seconds = base_min_seconds
    if min_seconds_override is not None:
        min_seconds = max(min_seconds, float(min_seconds_override))
    max_seconds = max(
        resolved_segment_max_seconds(request, ranked_candidate=ranked_candidate, source_hint=hint),
        min_seconds,
    )
    estimated_full_cycle_tolerance = 0.25 if min_seconds > base_min_seconds + 1e-6 else 0.0
    return hint.duration_seconds + estimated_full_cycle_tolerance >= min_seconds and hint.duration_seconds <= max_seconds


def source_window_materially_wider(parent: SourceChunkHint, child: SourceChunkHint) -> bool:
    if parent.duration_seconds <= child.duration_seconds + 0.50:
        return False
    starts_before = parent.start_seconds <= child.start_seconds - 0.25
    ends_after = parent.end_seconds >= child.end_seconds + 0.25
    return starts_before or ends_after


def source_window_video_duration_seconds(ranked_candidate: RankedCandidate) -> float | None:
    candidate = ranked_candidate.candidate
    for key in ("durationSeconds", "durationSec", "duration"):
        value = parse_optional_float(candidate.get(key))
        if value is not None and value > 0.0:
            return value
    vision_payload = candidate.get("visionPayload")
    if isinstance(vision_payload, dict):
        semantic_gate = vision_payload.get("semanticGate")
        if isinstance(semantic_gate, dict):
            value = parse_optional_float(semantic_gate.get("durationSeconds"))
            if value is not None and value > 0.0:
                return value
        pose_payload = vision_payload.get("posePrefilter")
        if isinstance(pose_payload, dict):
            sampled_windows = pose_payload.get("sampledWindows")
            if isinstance(sampled_windows, list):
                ends = [
                    parse_optional_float(window.get("endSeconds"))
                    for window in sampled_windows
                    if isinstance(window, dict)
                ]
                valid_ends = [value for value in ends if value is not None and value > 0.0]
                if valid_ends:
                    return max(valid_ends)
    return None


def resolved_segment_max_seconds(
    request: BakeAndRankRequest,
    *,
    ranked_candidate: RankedCandidate | None = None,
    source_hint: SourceChunkHint | None = None,
) -> float:
    """Resolve an automatic, evidence-based segment limit when the configured value is zero."""
    configured = float(request.segment_max_seconds)
    minimum = max(0.5, float(request.segment_min_seconds))
    if configured > 0.0:
        return max(minimum, configured)
    estimated_seconds = minimum
    if ranked_candidate is not None:
        estimate = estimate_chunking(exercise_name=ranked_candidate.exercise_name, use_llm=False)
        estimated_seconds = max(
            estimated_seconds,
            parse_optional_float(getattr(estimate, "chunk_seconds", None)) or 0.0,
            parse_optional_float(getattr(estimate, "rep_duration_max_sec", None)) or 0.0,
        )
    if source_hint is not None:
        estimated_seconds = max(estimated_seconds, source_hint.duration_seconds)
    if ranked_candidate is not None:
        source_duration = source_window_video_duration_seconds(ranked_candidate)
        if source_duration is not None:
            estimated_seconds = min(source_duration, estimated_seconds)
    return max(minimum, estimated_seconds)


def source_window_parent_hint_candidates(ranked_candidate: RankedCandidate) -> list[SourceChunkHint]:
    candidate = ranked_candidate.candidate
    candidates: list[SourceChunkHint] = []
    explicit_parent = candidate.get("sourceWindowParentHint")
    if isinstance(explicit_parent, dict):
        variant = parse_source_window_variant(explicit_parent, source="source_window_parent_hint")
        if variant is not None:
            candidates.append(variant.hint)
    vision_payload = candidate.get("visionPayload")
    if isinstance(vision_payload, dict):
        pose_payload = vision_payload.get("posePrefilter")
        if isinstance(pose_payload, dict):
            sampled_windows = pose_payload.get("sampledWindows")
            if isinstance(sampled_windows, list):
                for window in sampled_windows:
                    if not isinstance(window, dict):
                        continue
                    variant = parse_source_window_variant(window, source="pose_prefilter_sampled_window")
                    if variant is not None:
                        candidates.append(variant.hint)
    duration_seconds = source_window_video_duration_seconds(ranked_candidate)
    if duration_seconds is not None and duration_seconds > 0.0:
        candidates.append(SourceChunkHint(0.0, duration_seconds, None))
    deduped: list[SourceChunkHint] = []
    seen: set[tuple[int, int]] = set()
    for hint in candidates:
        key = source_window_key(hint)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(hint)
    return deduped


def clamp_parent_source_window_to_request(
    parent: SourceChunkHint,
    child: SourceChunkHint,
    request: BakeAndRankRequest,
    *,
    ranked_candidate: RankedCandidate,
) -> SourceChunkHint | None:
    if parent.end_seconds <= parent.start_seconds:
        return None
    max_seconds = resolved_segment_max_seconds(
        request,
        ranked_candidate=ranked_candidate,
        source_hint=child,
    )
    if parent.duration_seconds <= max_seconds + 1e-6:
        return parent
    if child.duration_seconds >= max_seconds:
        return None
    extra = max_seconds - child.duration_seconds
    start = child.start_seconds - extra * 0.50
    start = max(parent.start_seconds, min(parent.end_seconds - max_seconds, start))
    end = start + max_seconds
    if end < child.end_seconds:
        end = child.end_seconds
        start = max(parent.start_seconds, end - max_seconds)
    if start > child.start_seconds:
        start = child.start_seconds
        end = min(parent.end_seconds, start + max_seconds)
    if end - start <= child.duration_seconds + 1e-6:
        return None
    return SourceChunkHint(
        start_seconds=max(0.0, start),
        end_seconds=end,
        score=parent.score,
    )


def broader_parent_source_window_hint(
    ranked_candidate: RankedCandidate,
    *,
    request: BakeAndRankRequest,
) -> SourceChunkHint | None:
    child = ranked_candidate.source_chunk_hint
    if child is None:
        return None
    usable_candidates: list[SourceChunkHint] = []
    for parent in source_window_parent_hint_candidates(ranked_candidate):
        if not (
            parent.start_seconds <= child.start_seconds + 1e-6
            and parent.end_seconds + 1e-6 >= child.end_seconds
        ):
            continue
        clamped = clamp_parent_source_window_to_request(
            parent,
            child,
            request,
            ranked_candidate=ranked_candidate,
        )
        if clamped is None or not source_window_materially_wider(clamped, child):
            continue
        usable_candidates.append(clamped)
    if not usable_candidates:
        return None
    usable_candidates.sort(
        key=lambda hint: (
            hint.duration_seconds,
            abs(((hint.start_seconds + hint.end_seconds) * 0.5) - ((child.start_seconds + child.end_seconds) * 0.5)),
        )
    )
    return usable_candidates[0]


def source_window_motion_contract_from_candidate(candidate: dict[str, Any]) -> dict[str, Any] | None:
    prompt_contract = exercise_motion_contract_from_candidate(candidate)
    if prompt_contract is not None:
        return prompt_contract
    raw_contract = candidate.get("exerciseMotionContract")
    if isinstance(raw_contract, dict):
        return raw_contract
    payload = candidate.get("visionPayload")
    if isinstance(payload, dict):
        raw_contract = payload.get("exerciseMotionContract")
        if isinstance(raw_contract, dict):
            return raw_contract
    return None


def source_window_min_seconds_for_candidate(
    ranked_candidate: RankedCandidate,
    request: BakeAndRankRequest,
) -> float:
    min_seconds = max(0.5, float(request.segment_min_seconds))
    contract = source_window_motion_contract_from_candidate(ranked_candidate.candidate)
    if not observable_motion_spec_requires_return(contract):
        return min_seconds
    chunk_estimate = estimate_chunking(exercise_name=ranked_candidate.exercise_name, use_llm=False)
    estimated_min = parse_optional_float(getattr(chunk_estimate, "rep_duration_min_sec", None))
    full_cycle_min = max(
        min_seconds,
        SOURCE_WINDOW_FULL_CYCLE_MIN_SECONDS,
        (
            (estimated_min or min_seconds) * SOURCE_WINDOW_FULL_CYCLE_MIN_ESTIMATED_DURATION_RATIO
            + max(0.0, float(request.segment_padding_seconds))
            + max(0.0, float(request.segment_end_padding_seconds))
        ),
    )
    max_seconds = resolved_segment_max_seconds(
        request,
        ranked_candidate=ranked_candidate,
        source_hint=ranked_candidate.source_chunk_hint,
    )
    return min(full_cycle_min, max_seconds)


def parse_source_window_variant(
    payload: dict[str, Any],
    *,
    source: str,
    original_index: int | None = None,
) -> SourceWindowVariant | None:
    start_seconds = parse_optional_float(payload.get("startSeconds"))
    end_seconds = parse_optional_float(payload.get("endSeconds"))
    if start_seconds is None or end_seconds is None or end_seconds <= start_seconds:
        return None
    return SourceWindowVariant(
        hint=SourceChunkHint(
            start_seconds=max(0.0, start_seconds),
            end_seconds=end_seconds,
            score=parse_optional_float(payload.get("score")),
        ),
        source=source,
        original_index=original_index,
    )


def collect_source_window_variants(
    ranked_candidate: RankedCandidate,
    *,
    request: BakeAndRankRequest,
) -> list[SourceWindowVariant]:
    variants: list[SourceWindowVariant] = []
    seen: set[tuple[int, int]] = set()
    min_seconds = source_window_min_seconds_for_candidate(ranked_candidate, request)

    def add_variant(variant: SourceWindowVariant, *, allow_short_fallback: bool = False) -> bool:
        if not allow_short_fallback and not source_window_usable_for_attempt(
            variant.hint,
            request,
            ranked_candidate=ranked_candidate,
            min_seconds_override=min_seconds,
        ):
            return False
        key = source_window_key(variant.hint)
        if key in seen:
            return False
        seen.add(key)
        variants.append(variant)
        return True

    current_hint = ranked_candidate.source_chunk_hint
    current_variant = (
        SourceWindowVariant(current_hint, "ranked_best_chunk")
        if current_hint is not None
        else None
    )
    if current_variant is not None:
        add_variant(current_variant)

    vision_payload = ranked_candidate.candidate.get("visionPayload")
    if isinstance(vision_payload, dict):
        reviewed_chunks = vision_payload.get("reviewedChunks")
        reviewed_variant_count = 0
        if isinstance(reviewed_chunks, list):
            for index, chunk in enumerate(reviewed_chunks):
                if not isinstance(chunk, dict) or parse_optional_bool(chunk.get("valid")) is False:
                    continue
                variant = parse_source_window_variant(
                    chunk,
                    source=str(chunk.get("windowSource") or "chunked_source_video_review"),
                    original_index=index,
                )
                if variant is not None and (
                    variant.hint.score is None
                    or variant.hint.score >= SOURCE_GATE_MIN_BEST_CHUNK_SCORE
                ):
                    if add_variant(variant):
                        reviewed_variant_count += 1

        # If source-video semantic review produced usable windows, treat that
        # reviewed list as authoritative. Pose-only windows are just a fast
        # deterministic prefilter and can include good-looking sub-drills from
        # tutorial videos that are not the requested full movement.
        pose_payload = vision_payload.get("posePrefilter") if reviewed_variant_count == 0 else None
        if isinstance(pose_payload, dict):
            valid_chunks = pose_payload.get("validChunks")
            if isinstance(valid_chunks, list):
                for index, chunk in enumerate(valid_chunks):
                    if not isinstance(chunk, dict):
                        continue
                    variant = parse_source_window_variant(
                        chunk,
                        source="pose_prefilter",
                        original_index=index,
                    )
                    if variant is not None and (
                        variant.hint.score is None
                        or variant.hint.score >= SOURCE_GATE_STRONG_BEST_CHUNK_SCORE
                    ):
                        add_variant(variant)

    if variants:
        motion_contract = source_window_motion_contract_from_candidate(ranked_candidate.candidate)
        pose_payload = (
            vision_payload.get("posePrefilter")
            if isinstance(vision_payload, dict)
            else None
        )
        if contract_accepts_ongoing_action_interval(motion_contract) and isinstance(pose_payload, dict):
            ranked_active_travel_variants: list[tuple[SourceWindowVariant, dict[str, Any], int]] = []
            for order, variant in enumerate(variants):
                source_pose_payload = source_pose_skeleton_payload_for_window(
                    pose_payload,
                    candidate_window=DetectionWindow(
                        index=order,
                        start_seconds=variant.hint.start_seconds,
                        end_seconds=variant.hint.end_seconds,
                    ),
                )
                locomotion_metrics = (
                    active_travel_locomotion_metrics_from_source_pose_payload(
                        source_pose_payload,
                        required=True,
                    )
                    if source_pose_payload is not None
                    else {"required": True, "passed": False}
                )
                ranked_active_travel_variants.append((variant, locomotion_metrics, order))

            def active_travel_variant_sort_key(
                item: tuple[SourceWindowVariant, dict[str, Any], int],
            ) -> tuple[int, float, int]:
                _variant, metrics, original_order = item
                evidence_strength = max(
                    parse_optional_float(metrics.get("supportCenterRangeRatio")) or 0.0,
                    parse_optional_float(metrics.get("footSeparationRangeRatio")) or 0.0,
                    min(
                        parse_optional_float(metrics.get("leftLegRootRelativeRangeRatio")) or 0.0,
                        parse_optional_float(metrics.get("rightLegRootRelativeRangeRatio")) or 0.0,
                    ),
                )
                return (
                    0 if bool(metrics.get("passed")) else 1,
                    -evidence_strength,
                    original_order,
                )

            ranked_active_travel_variants.sort(key=active_travel_variant_sort_key)
            variants = [variant for variant, _metrics, _order in ranked_active_travel_variants]
        return variants
    if current_variant is not None:
        if current_variant.hint.duration_seconds + 1e-6 < min_seconds:
            parent_hint = broader_parent_source_window_hint(ranked_candidate, request=request)
            if parent_hint is not None:
                add_variant(
                    SourceWindowVariant(parent_hint, "source_window_parent_hint"),
                    allow_short_fallback=False,
                )
        if variants:
            return variants
        allow_short_fallback = not observable_motion_spec_requires_return(
            source_window_motion_contract_from_candidate(ranked_candidate.candidate)
        )
        add_variant(current_variant, allow_short_fallback=allow_short_fallback)
        if variants:
            return variants
    return []


def ranked_candidate_with_source_window_variant(
    ranked_candidate: RankedCandidate,
    variant: SourceWindowVariant,
    *,
    attempt_index: int,
    preserve_original: bool,
) -> RankedCandidate:
    if preserve_original:
        return ranked_candidate
    candidate = copy.deepcopy(ranked_candidate.candidate)
    candidate["sourceWindowAttemptIndex"] = attempt_index
    candidate["sourceWindowAttemptSource"] = variant.source
    candidate["sourceWindowAttemptOriginalIndex"] = variant.original_index
    candidate["sourceWindowHint"] = source_chunk_hint_manifest(variant.hint)
    vision_payload = candidate.get("visionPayload")
    if not isinstance(vision_payload, dict):
        vision_payload = {}
        candidate["visionPayload"] = vision_payload
    vision_payload["bestChunkStartSeconds"] = variant.hint.start_seconds
    vision_payload["bestChunkEndSeconds"] = variant.hint.end_seconds
    vision_payload["bestChunkScore"] = variant.hint.score
    vision_payload["bestChunkSource"] = variant.source
    updated = replace(ranked_candidate, candidate=candidate)
    candidate["sourceWindowAttemptKey"] = ranked_candidate_attempt_key(updated)
    return updated


def ranked_candidate_with_parent_source_window_fallback(
    ranked_candidate: RankedCandidate,
    *,
    reason: str,
    request: BakeAndRankRequest | None = None,
    prefer_broader_parent: bool = False,
) -> RankedCandidate | None:
    hint = ranked_candidate.source_chunk_hint
    if hint is None:
        return None
    if parse_optional_bool(ranked_candidate.candidate.get("sourceWindowParentFallback")) is True:
        return None
    fallback_hint = hint
    if prefer_broader_parent:
        if request is None:
            return None
        broader_hint = broader_parent_source_window_hint(ranked_candidate, request=request)
        if broader_hint is None:
            return None
        fallback_hint = broader_hint
    if prefer_broader_parent and not source_window_materially_wider(fallback_hint, hint):
        return None
    candidate = copy.deepcopy(ranked_candidate.candidate)
    current_attempt_index = parse_optional_int(candidate.get("sourceWindowAttemptIndex"))
    candidate["sourceWindowAttemptIndex"] = 1 if current_attempt_index is None else current_attempt_index + 1
    candidate["sourceWindowAttemptSource"] = PARENT_SOURCE_WINDOW_FALLBACK_ATTEMPT_MODE
    candidate["sourceWindowAttemptMode"] = PARENT_SOURCE_WINDOW_FALLBACK_ATTEMPT_MODE
    candidate["sourceWindowParentFallback"] = True
    candidate["sourceWindowParentFallbackReason"] = reason
    candidate["sourceWindowParentFallbackChildWindow"] = source_chunk_hint_manifest(hint)
    candidate["sourceWindowHint"] = source_chunk_hint_manifest(fallback_hint)
    updated = replace(ranked_candidate, candidate=candidate)
    candidate["sourceWindowAttemptKey"] = ranked_candidate_attempt_key(updated)
    return updated


def expand_ranked_candidates_for_source_windows(
    candidates: list[RankedCandidate],
    *,
    request: BakeAndRankRequest,
) -> list[RankedCandidate]:
    variant_groups: list[list[RankedCandidate]] = []
    max_source_window_attempts = max(0, int(request.max_source_window_attempts or 0))
    for ranked_candidate in candidates:
        variants = collect_source_window_variants(ranked_candidate, request=request)
        if max_source_window_attempts > 0:
            variants = variants[:max_source_window_attempts]
        if not variants:
            if ranked_candidate.source_chunk_hint is not None and observable_motion_spec_requires_return(
                source_window_motion_contract_from_candidate(ranked_candidate.candidate)
            ):
                variant_groups.append([])
                continue
            variant_groups.append([ranked_candidate])
            continue
        current_hint = ranked_candidate.source_chunk_hint
        group: list[RankedCandidate] = []
        for attempt_index, variant in enumerate(variants):
            preserve_original = (
                attempt_index == 0
                and current_hint is not None
                and source_window_key(current_hint) == source_window_key(variant.hint)
            )
            group.append(
                ranked_candidate_with_source_window_variant(
                    ranked_candidate,
                    variant,
                    attempt_index=attempt_index,
                    preserve_original=preserve_original,
                )
            )
        variant_groups.append(group)

    expanded: list[RankedCandidate] = []
    max_group_size = max((len(group) for group in variant_groups), default=0)
    for variant_index in range(max_group_size):
        for group in variant_groups:
            if variant_index < len(group):
                expanded.append(group[variant_index])
    return expanded


def reconstruction_priority_score(ranked_candidate: RankedCandidate) -> float | None:
    """Estimate WHAM input quality from pose evidence already computed at discovery."""
    return _weighted_pose_prefilter_score(
        ranked_candidate,
        (
            ("reconstructionViewQuality", 0.35),
            ("bilateralActiveChainBalance", 0.20),
            ("cropSafety", 0.15),
            ("cameraStability", 0.15),
            ("bodyScaleRatio", 0.15),
        ),
    )


def yolo_trackability_score(ranked_candidate: RankedCandidate) -> float | None:
    """How cleanly YOLO can track the person, independent of side-vs-front view.

    Cut proposal, confirmation, and WHAM all read this 2-D track. Semantic
    discovery may still prefer a worse track; bake order should not.
    """
    return _weighted_pose_prefilter_score(
        ranked_candidate,
        (
            ("singlePersonRatio", 0.22),
            ("keypointCoverage", 0.18),
            ("wholeMovementJointVisibility", 0.18),
            ("cropSafety", 0.14),
            ("cameraStability", 0.14),
            ("bodyScaleRatio", 0.08),
            ("activeJointVisibility", 0.06),
        ),
    )


def _weighted_pose_prefilter_score(
    ranked_candidate: RankedCandidate,
    weighted_metrics: tuple[tuple[str, float], ...],
) -> float | None:
    vision_payload = ranked_candidate.candidate.get("visionPayload")
    if not isinstance(vision_payload, dict):
        return None
    pose_payload = vision_payload.get("posePrefilter")
    if not isinstance(pose_payload, dict):
        return None
    weighted_total = 0.0
    available_weight = 0.0
    for metric_name, weight in weighted_metrics:
        value = parse_optional_float(pose_payload.get(metric_name))
        if value is None:
            continue
        weighted_total += max(0.0, min(1.0, value)) * weight
        available_weight += weight
    if available_weight <= 0.0:
        return None
    return weighted_total / available_weight


def prioritize_ranked_candidates_for_reconstruction(
    candidates: list[RankedCandidate],
) -> list[RankedCandidate]:
    """Prefer YOLO-trackable sources among recommended clips; keep fallbacks last.

    ``reconstructionViewQuality`` (side vs front) is not a validity gate: some
    movements are best observed frontally. It is only a tie-breaker after the
    detector-derived trackability score, so equally trackable sources prefer the
    less depth-ambiguous reconstruction without displacing a cleaner track.
    """
    decorated: list[tuple[bool, int, float, float, int, RankedCandidate]] = []
    for original_index, ranked_candidate in enumerate(candidates):
        reconstruction_score = reconstruction_priority_score(ranked_candidate)
        trackability_score = yolo_trackability_score(ranked_candidate)
        readiness = first_attempt_readiness_assessment(ranked_candidate)
        candidate = copy.deepcopy(ranked_candidate.candidate)
        candidate["preWhamOriginalOrder"] = original_index
        candidate["preWhamReconstructionPriorityScore"] = reconstruction_score
        candidate["preWhamYoloTrackabilityScore"] = trackability_score
        candidate["firstAttemptReadiness"] = readiness
        prioritized_candidate = replace(ranked_candidate, candidate=candidate)
        is_fallback = parse_optional_bool(candidate.get("bakeFallbackCandidate")) is True
        sort_trackability = (
            -(trackability_score)
            if trackability_score is not None
            else 1.0
        )
        sort_reconstruction = (
            -reconstruction_score
            if reconstruction_score is not None
            else 1.0
        )
        decorated.append(
            (
                is_fallback,
                first_attempt_readiness_sort_rank(readiness),
                sort_trackability,
                sort_reconstruction,
                original_index,
                prioritized_candidate,
            )
        )

    decorated.sort(key=lambda entry: (entry[0], entry[1], entry[2], entry[3], entry[4]))
    return [entry[5] for entry in decorated]


def review_item_attempt_key(item: ReviewItem) -> str:
    explicit_key = item.candidate.get("sourceWindowAttemptKey")
    if isinstance(explicit_key, str) and explicit_key.strip():
        return explicit_key.strip()
    ranked_candidate = RankedCandidate(
        exercise_index=item.exercise_index,
        candidate_rank=item.candidate_rank,
        exercise_id=item.exercise_name,
        exercise_name=item.exercise_name,
        exercise_slug=slugify(item.exercise_name),
        candidate=item.candidate,
    )
    return ranked_candidate_attempt_key(ranked_candidate)


