def preview_settings_variants(*, motion_tuning_enabled: bool = True) -> list[dict[str, Any]]:
    if not motion_tuning_enabled:
        return [
            {
                "id": "raw-wham",
                "label": "Raw WHAM camera-space",
                "options": {
                    "fixedRoot": False,
                    "lockPlantedFeet": False,
                    "lockPlantedHands": False,
                    "autoWorldAlignment": True,
                    "sceneInverted": False,
                    "cleanupInterpretation": "support_lock",
                },
                "cleanupInterpretation": "support_lock",
            },
        ]
    support_presets = [
        (
            "lock-feet-hands",
            "Lock feet and hands",
            {
                "lockPlantedFeet": True,
                "lockPlantedHands": True,
                "cleanupInterpretation": "support_lock",
            },
        ),
        (
            "no-foot-lock",
            "No foot lock",
            {
                "lockPlantedFeet": False,
                "lockPlantedHands": True,
                "cleanupInterpretation": "support_lock",
            },
        ),
        (
            "no-hand-lock",
            "No hand lock",
            {
                "lockPlantedFeet": True,
                "lockPlantedHands": False,
                "cleanupInterpretation": "support_lock",
            },
        ),
        (
            "paired-hands",
            "Paired moving hands",
            {
                "lockPlantedFeet": True,
                "lockPlantedHands": False,
                "cleanupInterpretation": "paired_hands",
            },
        ),
        (
            "no-support-lock",
            "No support lock",
            {
                "lockPlantedFeet": False,
                "lockPlantedHands": False,
                "cleanupInterpretation": "support_lock",
            },
        ),
    ]
    transform_profiles = [
        (
            "",
            "",
            {
                "fixedRoot": True,
                "autoWorldAlignment": True,
                "sceneInverted": False,
            },
        ),
        (
            "no-auto-alignment",
            "No auto alignment",
            {
                "fixedRoot": True,
                "autoWorldAlignment": False,
                "sceneInverted": False,
            },
        ),
        (
            "free-root",
            "Free global root drift",
            {
                "fixedRoot": False,
                "autoWorldAlignment": True,
                "sceneInverted": False,
            },
        ),
    ]
    variants: list[dict[str, Any]] = []
    for support_id, support_label, support_options in support_presets:
        for profile_id, profile_label, profile_options in transform_profiles:
            variant_id = support_id if not profile_id else f"{support_id}-{profile_id}"
            variant_label = support_label if not profile_label else f"{support_label}, {profile_label}"
            variants.append(
                {
                    "id": variant_id,
                    "label": variant_label,
                    "options": {
                        **support_options,
                        **profile_options,
                    },
                    "cleanupInterpretation": support_options.get("cleanupInterpretation", "support_lock"),
                }
            )
    return variants


def sample_review_frame_indices(export_payload: dict[str, Any], count: int) -> list[int]:
    frame_count = int(export_payload.get("frameCount") or 0)
    if frame_count <= 0:
        return [0]
    sample_count = max(1, min(int(count), frame_count))
    if sample_count == frame_count:
        return list(range(frame_count))
    if sample_count == 1:
        return [frame_count // 2]
    return sorted(
        {
            round(index * (frame_count - 1) / (sample_count - 1))
            for index in range(sample_count)
        }
    )


def adaptive_preview_settings_contact_sheet_frame_count(review_frames: int) -> int:
    try:
        requested = int(review_frames)
    except (TypeError, ValueError):
        requested = DEFAULT_REVIEW_FRAMES
    requested = max(1, requested)
    return max(
        ADAPTIVE_PREVIEW_SETTINGS_MIN_CONTACT_SHEET_FRAMES,
        min(ADAPTIVE_PREVIEW_SETTINGS_MAX_CONTACT_SHEET_FRAMES, requested),
    )


def dense_loop_review_video_frame_indices(export_payload: dict[str, Any]) -> list[int]:
    frame_count = int(export_payload.get("frameCount") or 0)
    if frame_count <= 0:
        return [0]
    source_fps = parse_export_fps(export_payload)
    duration = parse_optional_float(export_payload.get("durationSec"))
    if duration is None or duration <= 0.0:
        duration = max(0.0, (frame_count - 1) / source_fps)
    target_frame_count = min(
        MAX_DENSE_REVIEW_VIDEO_FRAMES,
        max(2, int(math.ceil(duration * DEFAULT_DENSE_REVIEW_VIDEO_FPS)) + 1),
    )
    if source_fps <= DEFAULT_DENSE_REVIEW_VIDEO_FPS or frame_count <= target_frame_count:
        return list(range(frame_count))
    return sample_review_frame_indices(export_payload, target_frame_count)


def render_baked_wear_frames_with_playwright(
    page: Any,
    *,
    export_payload: dict[str, Any],
    frame_indices: list[int],
    options: dict[str, Any],
) -> list[str]:
    """Render a frame batch with one Playwright transfer of the motion payload.

    The payload contains every skeleton frame and can be several megabytes. Passing
    it to ``page.evaluate`` once per review frame made preview rendering scale with
    payload_size * output_frame_count. Keep the actual browser renderer and sampled
    frames unchanged while serializing the payload only once.
    """
    if not frame_indices:
        return []
    rendered = page.evaluate(
        """async ({ exportPayload, frameIndices, options }) => {
            async function renderedPixelRatio(dataUrl) {
                const image = new Image();
                await new Promise((resolve, reject) => {
                    image.onload = resolve;
                    image.onerror = reject;
                    image.src = dataUrl;
                });
                const canvas = document.createElement("canvas");
                canvas.width = image.naturalWidth;
                canvas.height = image.naturalHeight;
                const context = canvas.getContext("2d", { willReadFrequently: true });
                context.drawImage(image, 0, 0);
                const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
                let renderedPixels = 0;
                let sampledPixels = 0;
                for (let offset = 0; offset < pixels.length; offset += 16) {
                    sampledPixels += 1;
                    if (Math.max(pixels[offset], pixels[offset + 1], pixels[offset + 2]) > 16) {
                        renderedPixels += 1;
                    }
                }
                return sampledPixels > 0 ? renderedPixels / sampledPixels : 0.0;
            }

            const warmupFrameIndex = frameIndices[Math.floor(frameIndices.length / 2)];
            let previewReady = false;
            for (let attempt = 0; attempt < 40; attempt += 1) {
                const warmupFrame = await window.exerciseMotionAutomation.renderBakedWearFrame(
                    structuredClone(exportPayload),
                    warmupFrameIndex,
                    structuredClone(options),
                );
                if (await renderedPixelRatio(warmupFrame) >= 0.05) {
                    previewReady = true;
                    break;
                }
                await new Promise((resolve) => setTimeout(resolve, 50));
            }
            if (!previewReady) {
                throw new Error("Preview renderer did not produce a nonblank warm-up frame.");
            }

            const renderedFrames = [];
            for (const frameIndex of frameIndices) {
                renderedFrames.push(
                    await window.exerciseMotionAutomation.renderBakedWearFrame(
                        structuredClone(exportPayload),
                        frameIndex,
                        structuredClone(options),
                    )
                );
            }
            return renderedFrames;
        }""",
        {
            "exportPayload": export_payload,
            "frameIndices": frame_indices,
            "options": options,
        },
    )
    if not isinstance(rendered, list) or len(rendered) != len(frame_indices):
        raise RuntimeError(
            "Playwright review-frame batch returned an unexpected number of frames: "
            f"expected {len(frame_indices)}, received "
            f"{len(rendered) if isinstance(rendered, list) else 'non-list payload'}."
        )
    if any(not isinstance(frame, str) or not frame.startswith("data:image/") for frame in rendered):
        raise RuntimeError("Playwright review-frame batch returned an invalid image data URL.")
    return rendered


def repeated_review_frame_data_urls(data_urls: list[str], *, repeats: int) -> list[str]:
    if repeats <= 1 or len(data_urls) < 2:
        return list(data_urls)
    repeated: list[str] = []
    for repeat_index in range(repeats):
        if repeat_index == 0:
            repeated.extend(data_urls)
        else:
            repeated.extend(data_urls[1:])
    return repeated


def parse_export_fps(export_payload: dict[str, Any]) -> float:
    value = export_payload.get("fps")
    if isinstance(value, (int, float)) and math.isfinite(float(value)) and float(value) > 0:
        return float(value)
    return 30.0


def frame_timestamps_for_indices(export_payload: dict[str, Any], frame_indices: list[int]) -> list[float]:
    export_frames = export_payload.get("frames") if isinstance(export_payload, dict) else None
    if not isinstance(export_frames, list):
        return []
    fps = parse_export_fps(export_payload)
    timestamps: list[float] = []
    for frame_index in frame_indices:
        frame = (
            export_frames[frame_index]
            if 0 <= frame_index < len(export_frames) and isinstance(export_frames[frame_index], dict)
            else {}
        )
        timestamps.append(
            frame_time_seconds(
                frame,
                fallback_index=frame_index,
                fps=fps,
            )
        )
    return timestamps


def parse_review_video_fps(export_payload: dict[str, Any], *, frame_count: int) -> float:
    duration = export_payload.get("durationSec")
    if (
        frame_count > 1
        and isinstance(duration, (int, float))
        and math.isfinite(float(duration))
        and float(duration) > 0.0
    ):
        return max(0.1, (frame_count - 1) / float(duration))
    return parse_export_fps(export_payload)


def llm_review_frame_count_for_chunk(chunk_seconds: float, request: BakeAndRankRequest) -> int:
    duration_scaled_frames = int(math.ceil(max(0.1, chunk_seconds) * DEFAULT_LLM_REVIEW_FRAMES_PER_SECOND))
    return max(
        DEFAULT_LLM_REVIEW_FRAMES,
        max(1, int(request.review_frames)),
        min(DEFAULT_MAX_LLM_REVIEW_FRAMES, duration_scaled_frames),
    )


def loop_time_bounds_from_export(
    export_payload: dict[str, Any],
    *,
    fallback: EligibleLoop,
) -> tuple[float, float]:
    loop_payload = export_payload.get("loop")
    if isinstance(loop_payload, dict):
        start = parse_optional_float(loop_payload.get("sourceStartTimeSec"))
        end = parse_optional_float(loop_payload.get("sourceEndTimeSec"))
        if start is not None and end is not None:
            return start, max(start, end)
    frames = export_payload.get("frames")
    if isinstance(frames, list) and frames:
        timeline_frames = [
            frame
            for frame in frames
            if isinstance(frame, dict) and not bool(frame.get("syntheticLoopBridge"))
        ]
        if not timeline_frames:
            timeline_frames = [frame for frame in frames if isinstance(frame, dict)]
        start = parse_optional_float(timeline_frames[0].get("sourceTimeSec") if timeline_frames else None)
        end = parse_optional_float(timeline_frames[-1].get("sourceTimeSec") if timeline_frames else None)
        if start is not None and end is not None:
            return start, max(start, end)
    if isinstance(loop_payload, dict):
        start_frame = parse_optional_float(loop_payload.get("sourceStartFrame"))
        end_frame = parse_optional_float(loop_payload.get("sourceEndFrame"))
        fps = parse_export_fps(export_payload)
        if start_frame is not None and end_frame is not None and fps > 0:
            return start_frame / fps, max(start_frame, end_frame) / fps
    return fallback.start_seconds, fallback.end_seconds


def decode_review_frame_data_url(data_url: str, *, cv2: Any, np: Any) -> Any:
    _, separator, encoded = str(data_url).partition(",")
    encoded_payload = encoded if separator else str(data_url)
    image_bytes = base64.b64decode(encoded_payload)
    image = cv2.imdecode(np.frombuffer(image_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
    if image is None:
        raise RuntimeError("Failed to decode rendered preview frame.")
    return image


def write_review_video_from_data_urls(data_urls: list[str], output_path: Path, *, fps: float) -> None:
    if not data_urls:
        raise ValueError("At least one rendered frame is required to write a review video.")
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except ImportError as exc:
        raise RuntimeError("opencv-python and numpy are required to write review videos.") from exc

    frames = []
    for data_url in data_urls:
        image = decode_review_frame_data_url(data_url, cv2=cv2, np=np)
        frames.append(image)
    height, width = frames[0].shape[:2]
    for frame in frames[1:]:
        if frame.shape[:2] != (height, width):
            raise RuntimeError("Rendered preview frames must all have the same dimensions.")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    ffmpeg = resolve_ffmpeg_path()
    if ffmpeg is not None:
        write_review_frames_with_ffmpeg(
            frames,
            output_path,
            fps=fps,
            width=width,
            height=height,
            ffmpeg=ffmpeg,
        )
        return
    if output_path.suffix.lower() == ".webm":
        raise RuntimeError("FFmpeg is required for reliable VP9/WebM review-video encoding.")
    writer = cv2.VideoWriter(str(output_path), cv2.VideoWriter_fourcc(*"mp4v"), fps, (width, height))
    if not writer.isOpened():
        raise RuntimeError(f"Could not open video writer for {output_path}.")
    try:
        for frame in frames:
            writer.write(frame)
    finally:
        writer.release()


def write_review_frames_with_ffmpeg(
    frames: list[Any],
    output_path: Path,
    *,
    fps: float,
    width: int,
    height: int,
    ffmpeg: str,
) -> None:
    suffix = output_path.suffix.casefold()
    if suffix == ".webm":
        codec_args = [
            "-an",
            "-c:v",
            "libvpx-vp9",
            "-pix_fmt",
            "yuv420p",
            "-deadline",
            "good",
            "-cpu-used",
            "4",
            "-crf",
            "32",
            "-b:v",
            "0",
        ]
    elif suffix == ".mp4":
        codec_args = [
            "-an",
            "-c:v",
            "libx264",
            "-pix_fmt",
            "yuv420p",
            "-preset",
            "fast",
            "-crf",
            "20",
            "-movflags",
            "+faststart",
        ]
    else:
        raise ValueError(f"Unsupported review-video container: {output_path.suffix}")
    command = [
        ffmpeg,
        "-hide_banner",
        "-loglevel",
        "warning",
        "-y",
        "-f",
        "rawvideo",
        "-pix_fmt",
        "bgr24",
        "-video_size",
        f"{width}x{height}",
        "-framerate",
        f"{float(fps):g}",
        "-i",
        "pipe:0",
        *codec_args,
        str(output_path),
    ]
    process = subprocess.Popen(
        command,
        stdin=subprocess.PIPE,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
    )
    try:
        if process.stdin is None:
            raise RuntimeError("FFmpeg review-video encoder did not expose stdin.")
        for frame in frames:
            process.stdin.write(frame.tobytes())
        process.stdin.close()
        stderr_bytes = process.stderr.read() if process.stderr is not None else b""
        return_code = process.wait()
    except Exception:
        if process.poll() is None:
            process.kill()
        process.wait()
        raise
    if return_code != 0:
        stderr = stderr_bytes.decode("utf-8", errors="replace").strip()
        raise RuntimeError(f"FFmpeg review-video encode failed with exit code {return_code}: {stderr}")
    if not output_path.exists() or output_path.stat().st_size <= 0:
        raise RuntimeError(f"FFmpeg review-video encode produced no output: {output_path}")


def write_validated_review_video_from_data_urls(
    data_urls: list[str],
    output_path: Path,
    *,
    fps: float,
) -> tuple[Path, dict[str, Any]]:
    candidate_paths = [output_path]
    if output_path.suffix.casefold() == ".webm" and resolve_ffmpeg_path() is not None:
        candidate_paths.append(output_path.with_suffix(".mp4"))
    attempts: list[dict[str, Any]] = []
    final_path = output_path
    final_quality: dict[str, Any] = {
        "passed": False,
        "rejectionReasons": ["review_video_encode_failed"],
    }
    for candidate_path in candidate_paths:
        try:
            write_review_video_from_data_urls(data_urls, candidate_path, fps=fps)
        except Exception as exc:
            attempts.append(
                {
                    "path": str(candidate_path),
                    "passed": False,
                    "rejectionReasons": ["review_video_encode_exception"],
                    "error": f"{type(exc).__name__}: {exc}",
                }
            )
            continue
        quality = review_video_render_quality_metrics(candidate_path)
        encode_fidelity = review_video_encode_fidelity_metrics(candidate_path, data_urls)
        quality["encodeFidelity"] = encode_fidelity
        if not bool(encode_fidelity.get("passed", False)):
            quality["passed"] = False
            quality["rejectionReasons"] = dedupe_text(
                [
                    *[str(reason) for reason in quality.get("rejectionReasons", []) if str(reason)],
                    "review_video_encode_fidelity_failed",
                ]
            )
        attempts.append(
            {
                "path": str(candidate_path),
                "passed": bool(quality.get("passed", False)),
                "rejectionReasons": quality.get("rejectionReasons", []),
            }
        )
        final_path = candidate_path
        final_quality = quality
        if bool(quality.get("passed", False)):
            final_quality["encodeAttempts"] = attempts
            final_quality["codecFallbackUsed"] = candidate_path != output_path
            return candidate_path, final_quality
    final_quality["encodeAttempts"] = attempts
    final_quality["codecFallbackUsed"] = len(candidate_paths) > 1
    return final_path, final_quality


def sampled_frame_indices_for_fidelity(frame_count: int, max_samples: int) -> list[int]:
    sample_count = max(1, min(int(max_samples), int(frame_count)))
    if frame_count <= 0:
        return []
    if sample_count == frame_count:
        return list(range(frame_count))
    if sample_count == 1:
        return [frame_count // 2]
    return sorted(
        {
            round(index * (frame_count - 1) / (sample_count - 1))
            for index in range(sample_count)
        }
    )


def review_video_encode_fidelity_metrics(
    video_path: Path,
    source_data_urls: list[str],
) -> dict[str, Any]:
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except ImportError as exc:
        return {
            "passed": False,
            "rejectionReasons": ["review_video_encode_fidelity_dependencies_missing"],
            "error": str(exc),
        }

    expected_frame_count = len(source_data_urls)
    if expected_frame_count <= 0:
        return {
            "passed": False,
            "rejectionReasons": ["review_video_encode_fidelity_no_source_frames"],
            "expectedFrameCount": expected_frame_count,
        }
    if not video_path.exists():
        return {
            "passed": False,
            "rejectionReasons": ["review_video_encode_fidelity_missing_video"],
            "expectedFrameCount": expected_frame_count,
            "path": str(video_path),
        }

    capture = cv2.VideoCapture(str(video_path))
    if not capture.isOpened():
        return {
            "passed": False,
            "rejectionReasons": ["review_video_encode_fidelity_unreadable_video"],
            "expectedFrameCount": expected_frame_count,
            "path": str(video_path),
        }

    sample_indices = sampled_frame_indices_for_fidelity(
        expected_frame_count,
        REVIEW_VIDEO_ENCODE_FIDELITY_SAMPLE_FRAMES,
    )
    sample_index_set = set(sample_indices)
    decoded_samples: dict[int, Any] = {}
    decoded_frame_count = 0
    frame_count_hint = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
    try:
        while True:
            ok, frame = capture.read()
            if not ok:
                break
            if decoded_frame_count in sample_index_set:
                decoded_samples[decoded_frame_count] = frame
            decoded_frame_count += 1
    finally:
        capture.release()

    rejection_reasons: list[str] = []
    if decoded_frame_count == 0:
        rejection_reasons.append("review_video_encode_fidelity_no_decoded_frames")
    if decoded_frame_count != expected_frame_count:
        rejection_reasons.append("review_video_encode_fidelity_frame_count_mismatch")

    sample_errors: list[float] = []
    missing_samples: list[int] = []
    size_mismatches: list[int] = []
    for frame_index in sample_indices:
        decoded = decoded_samples.get(frame_index)
        if decoded is None:
            missing_samples.append(frame_index)
            continue
        try:
            expected = decode_review_frame_data_url(
                source_data_urls[frame_index],
                cv2=cv2,
                np=np,
            )
        except Exception:
            rejection_reasons.append("review_video_encode_fidelity_source_decode_failed")
            continue
        if expected.shape[:2] != decoded.shape[:2]:
            size_mismatches.append(frame_index)
            continue
        sample_errors.append(float(np.mean(cv2.absdiff(expected, decoded))))

    if missing_samples:
        rejection_reasons.append("review_video_encode_fidelity_missing_sample_frames")
    if size_mismatches:
        rejection_reasons.append("review_video_encode_fidelity_frame_size_mismatch")

    mean_abs_error = statistics.mean(sample_errors) if sample_errors else None
    max_frame_mean_abs_error = max(sample_errors) if sample_errors else None
    if (
        mean_abs_error is not None
        and mean_abs_error > REVIEW_VIDEO_ENCODE_FIDELITY_MAX_MEAN_ABS_ERROR
    ):
        rejection_reasons.append("review_video_encode_fidelity_mean_error_high")
    if (
        max_frame_mean_abs_error is not None
        and max_frame_mean_abs_error > REVIEW_VIDEO_ENCODE_FIDELITY_MAX_FRAME_MEAN_ABS_ERROR
    ):
        rejection_reasons.append("review_video_encode_fidelity_frame_error_high")

    return {
        "schemaVersion": 1,
        "path": str(video_path),
        "passed": not rejection_reasons,
        "rejectionReasons": dedupe_text(rejection_reasons),
        "expectedFrameCount": expected_frame_count,
        "decodedFrameCount": decoded_frame_count,
        "frameCountHint": frame_count_hint,
        "sampledFrameIndices": sample_indices,
        "sampleCount": len(sample_errors),
        "missingSampleFrames": missing_samples,
        "frameSizeMismatchSamples": size_mismatches,
        "meanAbsolutePixelError": mean_abs_error,
        "maxFrameMeanAbsolutePixelError": max_frame_mean_abs_error,
        "maxMeanAbsolutePixelError": REVIEW_VIDEO_ENCODE_FIDELITY_MAX_MEAN_ABS_ERROR,
        "maxFrameMeanAbsolutePixelErrorThreshold": REVIEW_VIDEO_ENCODE_FIDELITY_MAX_FRAME_MEAN_ABS_ERROR,
    }


def review_video_render_quality_metrics(video_path: Path) -> dict[str, Any]:
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except ImportError as exc:
        return {
            "passed": False,
            "rejectionReasons": ["review_video_quality_dependencies_missing"],
            "error": str(exc),
        }

    if not video_path.exists():
        return {
            "passed": False,
            "rejectionReasons": ["review_video_missing"],
            "path": str(video_path),
        }
    capture = cv2.VideoCapture(str(video_path))
    if not capture.isOpened():
        return {
            "passed": False,
            "rejectionReasons": ["review_video_unreadable"],
            "path": str(video_path),
        }
    fps = float(capture.get(cv2.CAP_PROP_FPS) or 0.0)
    frame_count_hint = int(capture.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
    frame_count = 0
    visible_count = 0
    leading_blank_frames = 0
    first_visible_frame: int | None = None
    min_rendered_ratio = 1.0
    max_rendered_ratio = 0.0
    mean_luma_values: list[float] = []
    try:
        while True:
            ok, frame = capture.read()
            if not ok:
                break
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            rendered_ratio = float(np.mean(gray > REVIEW_VIDEO_BLANK_PIXEL_THRESHOLD))
            mean_luma = float(np.mean(gray))
            min_rendered_ratio = min(min_rendered_ratio, rendered_ratio)
            max_rendered_ratio = max(max_rendered_ratio, rendered_ratio)
            mean_luma_values.append(mean_luma)
            blank = rendered_ratio < REVIEW_VIDEO_MIN_RENDERED_PIXEL_RATIO
            if not blank:
                visible_count += 1
                if first_visible_frame is None:
                    first_visible_frame = frame_count
            elif first_visible_frame is None:
                leading_blank_frames += 1
            frame_count += 1
    finally:
        capture.release()

    rejection_reasons: list[str] = []
    if frame_count == 0:
        rejection_reasons.append("review_video_no_decodable_frames")
    if visible_count == 0 and frame_count > 0:
        rejection_reasons.append("review_video_all_blank")
    leading_blank_seconds = leading_blank_frames / fps if fps > 0.0 else None
    if (
        leading_blank_frames > REVIEW_VIDEO_MAX_LEADING_BLANK_FRAMES
        and (
            leading_blank_seconds is None
            or leading_blank_seconds > REVIEW_VIDEO_MAX_LEADING_BLANK_SECONDS
        )
    ):
        rejection_reasons.append("review_video_leading_blank_frames")
    if max_rendered_ratio < REVIEW_VIDEO_MIN_RENDERED_PIXEL_RATIO and frame_count > 0:
        rejection_reasons.append("review_video_unreadable_frames")

    return {
        "schemaVersion": 1,
        "path": str(video_path),
        "passed": not rejection_reasons,
        "rejectionReasons": dedupe_text(rejection_reasons),
        "fps": fps,
        "frameCount": frame_count,
        "frameCountHint": frame_count_hint,
        "visibleFrameCount": visible_count,
        "leadingBlankFrames": leading_blank_frames,
        "leadingBlankSeconds": leading_blank_seconds,
        "firstVisibleFrame": first_visible_frame,
        "firstVisibleSeconds": (
            first_visible_frame / fps
            if first_visible_frame is not None and fps > 0.0
            else None
        ),
        "minRenderedPixelRatio": min_rendered_ratio if frame_count else None,
        "maxRenderedPixelRatio": max_rendered_ratio if frame_count else None,
        "meanLuma": statistics.mean(mean_luma_values) if mean_luma_values else None,
        "blankPixelThreshold": REVIEW_VIDEO_BLANK_PIXEL_THRESHOLD,
        "minRenderedPixelRatioThreshold": REVIEW_VIDEO_MIN_RENDERED_PIXEL_RATIO,
        "maxLeadingBlankSeconds": REVIEW_VIDEO_MAX_LEADING_BLANK_SECONDS,
        "maxLeadingBlankFrames": REVIEW_VIDEO_MAX_LEADING_BLANK_FRAMES,
    }


def render_review_window_contact_sheet(
    *,
    item: ReviewItem,
    window: DetectionWindow,
    output_dir: Path,
    frame_count: int,
    vlm_review_style: bool = False,
) -> list[Path]:
    try:
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError("Playwright is required for dense LLM review rendering.") from exc

    output_dir.mkdir(parents=True, exist_ok=True)
    options = (
        vlm_review_render_options(item.settings_options)
        if vlm_review_style
        else with_fixed_preview_camera_options(item.settings_options)
    )
    with sync_playwright() as playwright:
        browser = launch_chromium_browser(playwright)
        try:
            page = browser.new_page(viewport={"width": 960, "height": 720}, device_scale_factor=1)
            page.goto(item.preview_html_path.resolve().as_uri(), wait_until="networkidle")
            page.wait_for_function("() => window.exerciseMotionAutomation != null")
            export_payload = page.evaluate(
                """({ startSeconds, endSeconds, options }) => window.exerciseMotionAutomation.bakeTimeRange(startSeconds, endSeconds, options)""",
                {
                    "startSeconds": window.start_seconds,
                    "endSeconds": window.end_seconds,
                    "options": options,
                },
            )
            frame_indices = sample_review_frame_indices(export_payload, frame_count)
            frame_timestamps = frame_timestamps_for_indices(
                export_payload if isinstance(export_payload, dict) else {},
                frame_indices,
            )
            frame_data_urls = render_baked_wear_frames_with_playwright(
                page,
                export_payload=export_payload,
                frame_indices=frame_indices,
                options=options,
            )
        finally:
            browser.close()
    return write_review_contact_sheets_from_data_urls(
        frame_data_urls,
        output_dir,
        timestamps=frame_timestamps,
        sequence_labels=True,
        frames_per_sheet=contact_sheet_frames_per_sheet(frame_count),
    )


def render_source_review_window_contact_sheet(
    *,
    item: ReviewItem,
    window: DetectionWindow,
    output_dir: Path,
    frame_count: int,
) -> list[Path]:
    source_video_path = item.candidate_workspace / "input" / "selected_segment.mp4"
    if not source_video_path.exists():
        source_video_path = item.candidate_workspace / "input" / "source.mp4"
    if not source_video_path.exists():
        return []
    render_window = source_video_window_for_review_window(
        item=item,
        source_video_path=source_video_path,
        window=window,
    )
    return render_video_window_contact_sheet(
        video_path=source_video_path,
        window=render_window,
        output_dir=output_dir,
        frame_count=frame_count,
    )


def source_video_window_for_review_window(
    *,
    item: ReviewItem,
    source_video_path: Path,
    window: DetectionWindow,
) -> DetectionWindow:
    source_duration = source_video_duration_seconds(source_video_path)
    return map_review_window_to_source_video_window(
        item=item,
        window=window,
        source_duration_seconds=source_duration,
    )


def source_video_duration_seconds(source_video_path: Path) -> float:
    try:
        return max(0.0, float(read_basic_video_metadata(source_video_path).duration_seconds))
    except Exception:
        return 0.0


def render_video_window_contact_sheet(
    *,
    video_path: Path,
    window: DetectionWindow,
    output_dir: Path,
    frame_count: int,
    contact_sheet_tile_width: int = DEFAULT_LLM_REVIEW_CONTACT_SHEET_CELL_WIDTH,
    contact_sheet_frames_per_sheet_override: int | None = None,
    contact_sheet_jpeg_quality: int = SOURCE_CUT_CONTACT_SHEET_JPEG_QUALITY,
) -> list[Path]:
    if not video_path.exists():
        return []
    try:
        frames_per_sheet = (
            contact_sheet_frames_per_sheet(max(1, frame_count))
            if contact_sheet_frames_per_sheet_override is None
            else max(1, int(contact_sheet_frames_per_sheet_override))
        )
        return extract_window_frames(
            video_path=video_path,
            window=window,
            frames_per_window=max(1, frame_count),
            max_frame_width=DEFAULT_RANK_FRAME_WIDTH,
            contact_sheet_enabled=True,
            contact_sheet_columns=contact_sheet_columns(frames_per_sheet),
            contact_sheet_tile_width=max(160, int(contact_sheet_tile_width)),
            contact_sheet_frames_per_sheet=frames_per_sheet,
            contact_sheet_jpeg_quality=max(1, min(100, int(contact_sheet_jpeg_quality))),
            contact_sheet_sequence_labels=True,
            output_dir=output_dir,
        )
    except Exception:
        return []


def write_review_contact_sheet_from_data_urls(
    data_urls: list[str],
    output_path: Path,
    *,
    timestamps: list[float] | None = None,
    sequence_labels: bool = False,
    sequence_label_offset: int = 0,
    sequence_label_total: int | None = None,
) -> None:
    if not data_urls:
        raise ValueError("At least one rendered frame is required to write a review contact sheet.")
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except ImportError as exc:
        raise RuntimeError("opencv-python and numpy are required to write review contact sheets.") from exc

    frames = []
    for data_url in data_urls:
        _, _, encoded = str(data_url).partition(",")
        image_bytes = base64.b64decode(encoded)
        image = cv2.imdecode(np.frombuffer(image_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
        if image is None:
            raise RuntimeError("Failed to decode rendered preview frame.")
        height, width = image.shape[:2]
        if width > DEFAULT_LLM_REVIEW_CONTACT_SHEET_CELL_WIDTH:
            scale = DEFAULT_LLM_REVIEW_CONTACT_SHEET_CELL_WIDTH / width
            image = cv2.resize(
                image,
                (DEFAULT_LLM_REVIEW_CONTACT_SHEET_CELL_WIDTH, max(1, int(round(height * scale)))),
                interpolation=cv2.INTER_AREA,
            )
        timestamp = timestamps[len(frames)] if timestamps is not None and len(timestamps) > len(frames) else None
        if sequence_labels or timestamp is not None:
            draw_contact_sheet_tile_label(
                cv2,
                image,
                frame_number=sequence_label_offset + len(frames) + 1,
                total_frames=sequence_label_total or len(data_urls),
                timestamp_seconds=timestamp if timestamp is not None else 0.0,
                sequence_labels=sequence_labels,
            )
        frames.append(image)

    cell_height = max(frame.shape[0] for frame in frames)
    cell_width = max(frame.shape[1] for frame in frames)
    columns = contact_sheet_columns(len(frames))
    rows = math.ceil(len(frames) / columns)
    sheet = np.zeros((rows * cell_height, columns * cell_width, 3), dtype=np.uint8)
    for index, frame in enumerate(frames):
        row = index // columns
        column = index % columns
        y = row * cell_height
        x = column * cell_width
        sheet[y : y + frame.shape[0], x : x + frame.shape[1]] = frame
    output_path.parent.mkdir(parents=True, exist_ok=True)
    if not cv2.imwrite(str(output_path), sheet):
        raise RuntimeError(f"Failed to write review contact sheet to {output_path}.")


def write_review_contact_sheets_from_data_urls(
    data_urls: list[str],
    output_dir: Path,
    *,
    timestamps: list[float] | None = None,
    sequence_labels: bool = False,
    frames_per_sheet: int | None = None,
) -> list[Path]:
    if not data_urls:
        raise ValueError("At least one rendered frame is required to write review contact sheets.")
    sheet_size = (
        max(1, int(frames_per_sheet))
        if frames_per_sheet is not None
        else contact_sheet_frames_per_sheet(len(data_urls))
    )
    multiple_sheets = len(data_urls) > sheet_size
    output_paths: list[Path] = []
    for sheet_index, start_index in enumerate(range(0, len(data_urls), sheet_size), start=1):
        end_index = start_index + sheet_size
        output_path = (
            output_dir / f"contact_sheet_{sheet_index:02d}.jpg"
            if multiple_sheets
            else output_dir / "contact_sheet.jpg"
        )
        write_review_contact_sheet_from_data_urls(
            data_urls[start_index:end_index],
            output_path,
            timestamps=timestamps[start_index:end_index] if timestamps is not None else None,
            sequence_labels=sequence_labels,
            sequence_label_offset=start_index,
            sequence_label_total=len(data_urls),
        )
        output_paths.append(output_path)
    return output_paths


def contact_sheet_columns(frame_count: int) -> int:
    if frame_count <= 4:
        return max(1, frame_count)
    if frame_count <= 16:
        return 4
    if frame_count <= 30:
        return 5
    return 6


def contact_sheet_frames_per_sheet(frame_count: int) -> int:
    return min(
        DEFAULT_LLM_REVIEW_CONTACT_SHEET_FRAMES_PER_SHEET,
        max(1, int(frame_count)),
    )


def frange_inclusive(start: float, stop: float, step: float) -> list[float]:
    if step <= 0:
        return [start]
    values: list[float] = []
    value = start
    while value <= stop + 1e-6:
        values.append(value)
        value += step
    if not values or abs(values[-1] - stop) > 1e-6:
        values.append(stop)
    return values


def source_cut_min_candidate_duration_seconds(
    *,
    chunk_estimate: Any,
    exercise_motion_contract: dict[str, Any] | None,
) -> float:
    estimated_min = parse_optional_float(getattr(chunk_estimate, "rep_duration_min_sec", None))
    estimated_max = parse_optional_float(getattr(chunk_estimate, "rep_duration_max_sec", None))
    if contract_accepts_ongoing_action_interval(exercise_motion_contract):
        floor = ACTIVE_TRAVEL_SOURCE_CUT_MIN_SECONDS
    else:
        floor = max(
            SOURCE_CUT_ROBUST_MIN_SECONDS,
            (estimated_min or SOURCE_CUT_ROBUST_MIN_SECONDS) * SOURCE_CUT_ROBUST_MIN_ESTIMATED_DURATION_RATIO,
        )
    if observable_motion_spec_requires_return(exercise_motion_contract):
        floor = max(
            floor,
            SOURCE_WINDOW_FULL_CYCLE_MIN_SECONDS,
            (estimated_min or SOURCE_WINDOW_FULL_CYCLE_MIN_SECONDS)
            * SOURCE_WINDOW_FULL_CYCLE_MIN_ESTIMATED_DURATION_RATIO,
        )
    if estimated_max is not None and estimated_max > 0:
        floor = min(floor, estimated_max)
    return max(SOURCE_CUT_REFINEMENT_MIN_SECONDS, floor)


def build_source_video_pyramid_candidate_windows(
    *,
    window: DetectionWindow,
    chunk_estimate: Any,
    min_duration_floor_seconds: float,
    use_estimated_duration_floor: bool = True,
) -> list[SourceWindowCandidateSpec]:
    duration = max(0.0, window.end_seconds - window.start_seconds)
    if duration <= 0.5:
        return []
    if duration + 1e-6 < min_duration_floor_seconds:
        return []
    rep_min = parse_optional_float(getattr(chunk_estimate, "rep_duration_min_sec", None))
    rep_max = parse_optional_float(getattr(chunk_estimate, "rep_duration_max_sec", None))
    estimated_min = rep_min or min(duration, SOURCE_CUT_ROBUST_MIN_SECONDS)
    robust_floor = (
        max(
            min_duration_floor_seconds,
            min(duration, estimated_min * SOURCE_CUT_ROBUST_MIN_ESTIMATED_DURATION_RATIO),
        )
        if use_estimated_duration_floor
        else min(duration, min_duration_floor_seconds)
    )
    target_durations: list[float] = []
    candidate_duration = duration
    while candidate_duration > robust_floor + 0.10:
        target_durations.append(candidate_duration)
        next_duration = candidate_duration * SOURCE_CUT_PROGRESSIVE_SHRINK_FACTOR
        if next_duration >= candidate_duration - 0.05:
            break
        candidate_duration = next_duration
    target_durations.append(robust_floor)
    unique_durations: list[float] = []
    for candidate_duration in target_durations:
        rounded = round(min(duration, max(robust_floor, candidate_duration)), 2)
        if all(abs(rounded - existing) > 0.1 for existing in unique_durations):
            unique_durations.append(rounded)
    unique_durations.sort(reverse=True)

    specs: list[SourceWindowCandidateSpec] = []
    seen: set[tuple[float, float]] = set()

    def append_window(
        start: float,
        end: float,
        *,
        level_index: int,
        level_duration: float,
        level_ratio: float,
        stride_seconds: float,
        position_index: int,
        position_count: int,
        strategy: str = "progressive_multiscale_sliding",
        min_allowed_duration: float | None = None,
        boundary_anchor: str | None = None,
    ) -> None:
        min_duration = robust_floor if min_allowed_duration is None else max(SOURCE_CUT_REFINEMENT_MIN_SECONDS, min_allowed_duration)
        start = max(window.start_seconds, min(window.end_seconds, start))
        end = max(start, min(window.end_seconds, end))
        if end - start + 1e-6 < min_duration:
            return
        key = (round(start, 2), round(end, 2))
        if key in seen:
            return
        seen.add(key)
        chunking = {
            "strategy": strategy,
            "levelIndex": level_index,
            "levelDurationSeconds": round(level_duration, 3),
            "levelRatio": round(level_ratio, 4),
            "shrinkFactor": SOURCE_CUT_PROGRESSIVE_SHRINK_FACTOR,
            "strideSeconds": round(stride_seconds, 3),
            "strideRatio": SOURCE_CUT_PROGRESSIVE_STRIDE_RATIO,
            "maxWindowsPerLevel": SOURCE_CUT_PROGRESSIVE_MAX_WINDOWS_PER_LEVEL,
            "positionIndex": position_index,
            "positionCount": position_count,
            "parentStartSeconds": window.start_seconds,
            "parentEndSeconds": window.end_seconds,
            "parentDurationSeconds": round(duration, 3),
            "minDurationFloorSeconds": round(min_duration, 3),
            "sourceCutRobustFloorSeconds": round(robust_floor, 3),
        }
        if boundary_anchor is not None:
            chunking["boundaryAnchor"] = boundary_anchor
        specs.append(
            SourceWindowCandidateSpec(
                window=DetectionWindow(index=len(specs), start_seconds=key[0], end_seconds=key[1]),
                chunking=chunking,
            )
        )

    for level_index, candidate_duration in enumerate(unique_durations):
        available = max(0.0, duration - candidate_duration)
        level_ratio = candidate_duration / duration if duration > 0.0 else 1.0
        if available <= 1e-6:
            offsets = [0.0]
            stride_seconds = 0.0
        else:
            requested_stride = max(0.25, candidate_duration * SOURCE_CUT_PROGRESSIVE_STRIDE_RATIO)
            capped_stride = max(
                requested_stride,
                available / max(1, SOURCE_CUT_PROGRESSIVE_MAX_WINDOWS_PER_LEVEL - 1),
            )
            stride_seconds = min(available, capped_stride)
            offsets = []
            offset = 0.0
            while offset < available - 1e-6:
                offsets.append(offset)
                offset += stride_seconds
            offsets.append(available)
        deduped_offsets: list[float] = []
        for offset in offsets:
            rounded_offset = round(max(0.0, min(available, offset)), 2)
            if rounded_offset not in deduped_offsets:
                deduped_offsets.append(rounded_offset)
        for position_index, offset in enumerate(deduped_offsets):
            start = window.start_seconds + offset
            append_window(
                start,
                start + candidate_duration,
                level_index=level_index,
                level_duration=candidate_duration,
                level_ratio=level_ratio,
                stride_seconds=stride_seconds,
                position_index=position_index,
                position_count=len(deduped_offsets),
            )

    # Rep-duration estimates are useful for prioritizing the main pyramid, but
    # they are not reliable enough to define a legal cut boundary.  Sweep down
    # to the technical sampling floor so a fast, complete repetition can end
    # cleanly before a following partial repetition begins.  Pose-cycle and VLM
    # boundary validation still decide whether any short window is usable.
    boundary_floor = SOURCE_CUT_REFINEMENT_MIN_SECONDS
    boundary_ceiling = min(robust_floor, duration)
    if boundary_floor + 0.05 < boundary_ceiling:
        span = boundary_ceiling - boundary_floor
        sweep_count = min(
            SOURCE_CUT_END_BOUNDARY_SWEEP_MAX_WINDOWS,
            max(2, int(math.ceil(span / 0.10)) + 1),
        )
        sweep_durations = [
            round(boundary_floor + (span * index / max(1, sweep_count - 1)), 2)
            for index in range(sweep_count)
        ]
        deduped_sweep_durations: list[float] = []
        for sweep_duration in sweep_durations:
            if all(abs(sweep_duration - existing) > 0.05 for existing in deduped_sweep_durations):
                deduped_sweep_durations.append(sweep_duration)
        sweep_level_index = len(unique_durations)
        for position_index, candidate_duration in enumerate(deduped_sweep_durations):
            append_window(
                window.start_seconds,
                window.start_seconds + candidate_duration,
                level_index=sweep_level_index,
                level_duration=candidate_duration,
                level_ratio=candidate_duration / duration if duration > 0.0 else 1.0,
                stride_seconds=0.0,
                position_index=position_index,
                position_count=len(deduped_sweep_durations),
                strategy="progressive_start_anchored_end_boundary_sweep",
                min_allowed_duration=boundary_floor,
                boundary_anchor="start",
            )

    return [
        SourceWindowCandidateSpec(
            window=DetectionWindow(
                index=index,
                start_seconds=spec.window.start_seconds,
                end_seconds=spec.window.end_seconds,
            ),
            chunking=spec.chunking,
        )
        for index, spec in enumerate(specs)
    ]


def build_source_cut_candidate_windows(
    *,
    window: DetectionWindow,
    chunk_estimate: Any,
    max_candidates: int | None = None,
    min_estimated_duration_ratio: float = MOVEMENT_CUT_MIN_ESTIMATED_DURATION_RATIO,
    min_duration_floor_seconds: float | None = None,
) -> list[DetectionWindow]:
    duration = max(0.0, window.end_seconds - window.start_seconds)
    if duration <= 0.5:
        return []
    if min_duration_floor_seconds is not None and duration + 1e-6 < min_duration_floor_seconds:
        return []
    candidate_limit = None if max_candidates is None or max_candidates <= 0 else max_candidates
    rep_min = parse_optional_float(getattr(chunk_estimate, "rep_duration_min_sec", None))
    rep_max = parse_optional_float(getattr(chunk_estimate, "rep_duration_max_sec", None))
    estimated_min_duration = rep_min or min(duration, 2.0)
    min_estimated_duration_ratio = max(0.0, float(min_estimated_duration_ratio))
    estimated_floor = estimated_min_duration * min_estimated_duration_ratio
    if min_estimated_duration_ratio >= 1.0:
        ratio_min_duration = max(SOURCE_CUT_REFINEMENT_MIN_SECONDS, estimated_floor)
    else:
        ratio_min_duration = max(
            SOURCE_CUT_REFINEMENT_MIN_SECONDS,
            min(estimated_min_duration, estimated_floor),
        )
    configured_floor = (
        SOURCE_CUT_REFINEMENT_MIN_SECONDS
        if min_duration_floor_seconds is None
        else max(SOURCE_CUT_REFINEMENT_MIN_SECONDS, float(min_duration_floor_seconds))
    )
    min_duration = min(duration, max(configured_floor, ratio_min_duration))
    max_duration = min(duration, max(min_duration, rep_max or duration))
    target_duration = min(max_duration, max(min_duration, (min_duration + max_duration) * 0.5))
    candidate_durations = [
        target_duration,
        min_duration,
        max(min_duration, estimated_min_duration * 0.75),
        max(min_duration, estimated_min_duration),
        max(min_duration, target_duration * 0.8),
        min(max_duration, target_duration * 1.2),
        max_duration,
    ]
    ladder_duration = min_duration
    while ladder_duration < duration:
        candidate_durations.append(ladder_duration)
        ladder_duration *= 1.25
    candidate_durations.append(duration)
    unique_durations: list[float] = []
    for candidate_duration in candidate_durations:
        rounded = round(min(duration, max(SOURCE_CUT_REFINEMENT_MIN_SECONDS, candidate_duration)), 2)
        if all(abs(rounded - existing) > 0.1 for existing in unique_durations):
            unique_durations.append(rounded)
    unique_durations.sort()

    windows: list[DetectionWindow] = []
    seen: set[tuple[float, float]] = set()
    short_window_limit = None if candidate_limit is None else max(0, candidate_limit - 1)

    def append_window(start: float, end: float) -> bool:
        if end - start < SOURCE_CUT_REFINEMENT_MIN_SECONDS:
            return False
        key = (round(start, 2), round(end, 2))
        if key in seen:
            return False
        seen.add(key)
        windows.append(DetectionWindow(index=len(windows), start_seconds=key[0], end_seconds=key[1]))
        return True

    for candidate_duration in unique_durations:
        if short_window_limit == 0 or (
            short_window_limit is not None and len(windows) >= short_window_limit
        ):
            break
        available = max(0.0, duration - candidate_duration)
        step = max(0.25, candidate_duration * 0.50)
        starts = [
            window.start_seconds + offset
            for offset in frange_inclusive(0.0, available, step)
        ]
        starts.append(window.end_seconds - candidate_duration)
        for start in starts:
            if short_window_limit is not None and len(windows) >= short_window_limit:
                break
            start = max(window.start_seconds, min(window.end_seconds - candidate_duration, start))
            end = min(window.end_seconds, start + candidate_duration)
            append_window(start, end)

    append_window(window.start_seconds, window.end_seconds)
    if candidate_limit is not None and len(windows) > candidate_limit:
        windows = windows[: max(0, candidate_limit - 1)] + [windows[-1]]
    return [
        DetectionWindow(index=index, start_seconds=candidate.start_seconds, end_seconds=candidate.end_seconds)
        for index, candidate in enumerate(windows)
    ]


def cut_candidate_attachment_prompt_lines(candidates: list[SourceCutCandidate]) -> list[str]:
    lines: list[str] = []
    attachment_index = 1
    for candidate in candidates:
        sheet_count = max(1, len(candidate.frame_paths))
        boundary_paths = [Path(path) for path in candidate.boundary_audit_frame_paths]
        embedded_audit_count = 0
        for index, boundary_path in enumerate(boundary_paths):
            if index >= len(candidate.frame_paths) or Path(candidate.frame_paths[index]) != boundary_path:
                break
            embedded_audit_count += 1
        if embedded_audit_count:
            chronological_count = max(0, sheet_count - embedded_audit_count)
            chronological_start = attachment_index + embedded_audit_count
            chronological_end = attachment_index + sheet_count - 1
            audit_label = (
                "start and finish boundary audit sheets"
                if embedded_audit_count >= 2
                else "a start boundary audit sheet"
            )
            chronological_label = (
                f"attachments {chronological_start}-{chronological_end} are the full chronological sheets"
                if chronological_count > 1
                else f"attachment {chronological_start} is the full chronological sheet"
                if chronological_count == 1
                else "no full chronological sheet is attached"
            )
            sheet_label = f"the first {embedded_audit_count} attachment(s) are {audit_label}; {chronological_label}"
        elif sheet_count == 1:
            sheet_label = f"attachment {attachment_index} is the full chronological sheet"
        else:
            sheet_label = f"attachments {attachment_index}-{attachment_index + sheet_count - 1} are the full chronological sheets"
        lines.append(
            f"- Candidate {candidate.candidate_id}: {candidate.window.start_seconds:.2f}s "
            f"to {candidate.window.end_seconds:.2f}s; {sheet_label}."
        )
        attachment_index += sheet_count
    return lines


def movement_topology_from_contract(contract: dict[str, Any] | None) -> dict[str, Any] | None:
    prompt_contract = exercise_motion_contract_for_prompt(contract)
    contract_payload = prompt_contract if isinstance(prompt_contract, dict) else contract
    if not isinstance(contract_payload, dict):
        return None
    topology = contract_payload.get("movementTopology")
    if not isinstance(topology, dict):
        return None
    start_state = topology.get("startState")
    end_state = topology.get("endState")
    phases = topology.get("phases")
    if not isinstance(start_state, dict) or not isinstance(end_state, dict) or not isinstance(phases, list):
        return None
    normalized_phases = [
        {"id": str(phase.get("id") or "").strip(), "label": str(phase.get("label") or "").strip()}
        for phase in phases
        if isinstance(phase, dict)
    ]
    if (
        not str(start_state.get("label") or "").strip()
        or not str(end_state.get("label") or "").strip()
        or not normalized_phases
        or any(not phase["id"] or not phase["label"] for phase in normalized_phases)
    ):
        return None
    return {
        "schemaVersion": 1,
        "completionMode": str(topology.get("completionMode") or "").strip(),
        "startState": {"id": "start_state", "label": str(start_state.get("label")).strip()},
        "phases": normalized_phases,
        "endState": {"id": "end_state", "label": str(end_state.get("label")).strip()},
    }


def contract_completion_mode(contract: dict[str, Any] | None) -> str:
    prompt_contract = exercise_motion_contract_for_prompt(contract)
    contract_payload = prompt_contract if isinstance(prompt_contract, dict) else contract
    if not isinstance(contract_payload, dict):
        return ""
    topology = contract_payload.get("movementTopology")
    topology_mode = topology.get("completionMode") if isinstance(topology, dict) else None
    return slugify(str(contract_payload.get("completionMode") or topology_mode or "")).replace("-", "_")


def contract_accepts_ongoing_action_interval(contract: dict[str, Any] | None) -> bool:
    return contract_completion_mode(contract) in {"active_travel", "stable_hold"}


def movement_topology_accepts_ongoing_action_interval(movement_topology: dict[str, Any] | None) -> bool:
    if not isinstance(movement_topology, dict):
        return False
    completion_mode = slugify(str(movement_topology.get("completionMode") or "")).replace("-", "_")
    return completion_mode in {"active_travel", "stable_hold"}


def movement_topology_evidence_prompt(contract: dict[str, Any] | None) -> str:
    topology = movement_topology_from_contract(contract)
    if topology is None:
        return ""
    if movement_topology_accepts_ongoing_action_interval(topology):
        return (
            "This contract describes an ongoing action. A clean interval entirely inside the target action is complete "
            "without showing approach, a predetermined destination, stopping, or return to start. Report the visible "
            "target-action phases, but do not reject merely because the clip begins and ends while the action continues. "
        )
    phase_ids = [str(phase["id"]) for phase in topology["phases"]]
    return (
        "The structured movement topology is mandatory. Report startStateMatch and endStateMatch as exactly match, mismatch, or uncertain. "
        "Report phaseEvidence as one item for every visibly observed required phase, using only the exact phase IDs from the contract and a normalized timeline position from 0.0 (first frame) to 1.0 (last frame). "
        f"For approval, phaseEvidence must contain every required phase exactly once in this exact order: {json.dumps(phase_ids)}. "
        "Do not copy the expected phase IDs unless the visible frames actually show each phase at increasing positions. "
        "A return-to-start candidate that begins at an interior/end-range state and returns to that same wrong state must report boundary mismatches even when its endpoints resemble each other. "
    )


def build_source_cut_candidate_choice_prompt(
    *,
    exercise_name: str,
    candidate_title: str,
    candidate: SourceCutCandidate,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> str:
    candidate_lines = cut_candidate_attachment_prompt_lines([candidate])
    required_equipment = two_scale_named_equipment(exercise_name)
    equipment_section = (
        f"Required named equipment: {required_equipment}. Set namedEquipmentEngagedStatus to engaged only when "
        "that exact equipment is visibly held, worn, attached, or connected to the moving performer throughout "
        "the exercise action. Use absent for bodyweight or different equipment, and unclear when image evidence "
        "cannot verify it. "
        if required_equipment != "none"
        else "Set namedEquipmentEngagedStatus to not_applicable because the target has no named equipment requirement. "
    )
    contract_section = build_source_cut_exercise_contract_prompt_section(exercise_motion_contract)
    topology_evidence_section = movement_topology_evidence_prompt(exercise_motion_contract)
    topology_schema = (
        ', "startStateMatch": "match|mismatch|uncertain", "endStateMatch": "match|mismatch|uncertain", '
        '"phaseEvidence": [{"phaseId": string, "position": number_0_to_1}]'
        if topology_evidence_section
        else ""
    )
    ongoing_action_section = (
        "The contract completion mode is an ongoing action. A window that starts cleanly inside the target action, "
        "continues showing that action, and ends cleanly while it is still continuing is a completeMovement. Set "
        "finishBoundaryClean true for that case. Do not require approach, a destination, stopping, exit, or return to start. "
        if contract_accepts_ongoing_action_interval(exercise_motion_contract)
        else ""
    )
    return (
        "Classify one candidate source-video cut for an exercise animation.\n"
        f"Target exercise: {exercise_name}.\n"
        "Use only the attached source-window frames as evidence. Ignore title, labels, captions, and outside context.\n"
        f"{contract_section}"
        f"{topology_evidence_section}"
        f"{ongoing_action_section}"
        "The candidate may have one or more chronological contact sheets. Read all sheets together in attachment order. "
        "Boundary audit sheets repeat the first or last frames at larger size; use them only to inspect whether the visible cut starts and ends cleanly. "
        f"{CONTACT_SHEET_READING_INSTRUCTIONS}"
        "Attachments are in this exact order:\n"
        + "\n".join(candidate_lines)
        + "\n\nClassify only this candidate. "
        "Ignore written labels, captions, arrows, diagrams, and instruction text; the visible body must perform all named actions/phases of the target movement. "
        "Every visible exercise-changing qualifier in the target name or exercise guidance must be satisfied by the frames, not inferred from the title. "
        "Examples of qualifiers include load/weighted, equipment, support surface, stance, limb count, grip, body orientation, incline/decline, assisted/unsupported, and direction. "
        "If a qualifier such as weighted/load/equipment/support cannot be visually verified, reject as wrong_variant or unclear. "
        "When the target says weighted or loaded, a real external load/resistance must be visible as held, worn, attached, or connected to the moving person. "
        "Do not count bodyweight alone, a bench, floor, anchor strap, support belt, partner, or setup fixture as weighted unless an actual load or resistance is visibly attached or held. "
        f"{equipment_section}"
        "A candidate showing only one named phase is partial_movement, but do not require an extra repetition or extra return after the normal finish posture. "
        "Use the candidate id exactly as shown in the attachment list, for example A, B, or C; do not write 'Candidate A'. "
        "The code owns timing and will choose among separately reviewed candidates after classification; do not select a winner and do not return timestamps. "
        "Do not approve a candidate merely because a correct repetition appears somewhere inside it; the whole candidate window must be the useful movement-only segment. "
        "Approve only when the frames clearly show one complete, useful execution of the target exercise: correct visible movement, meaningful start, full action path, natural finish or return, readable real source footage, and no material setup/reset/filler inside the cut. "
        "Audit the phase order before approving: the first visible execution frames must show the natural pre-action posture or the first exercise-defining action, the chronological sheets must show the required action path in contract order, and the final execution frames must show the natural finish/return posture. "
        "A deepest, bottom, contracted, lockout, or end-range posture may be a valid repetition boundary. Do not reject it by posture name alone; approve when the visible action leaves that posture, reaches the opposite turning point, and returns cleanly to the same posture. "
        "When the target name or contract describes an action plus return, opposite direction, completion, or repeated phase sequence, require those phases to be visible in the correct order; do not infer a missing first or last phase. "
        "Preparation, waiting, adjustment, repositioning, approach, exit, reset, cleanup, equipment transition, and contact/support/implement changes before or after the contract-required action are setup_or_filler unless the target name or contract explicitly requires them. "
        "A meaningful start is the actual start posture of the same execution, not the return from a previous rep or an idle/reset period before a later rep. "
        "The first material body motion after the cut starts must be the first action of the same execution. "
        "If the cut starts with recovery/return/standing-up from a previous execution and only later begins another execution, reject as bad_boundary or setup_or_filler. "
        "Reject when the cut begins with the finish/return of a previous repetition, then waits/resets/setups before another repetition, even if the later repetition looks correct. "
        "Reject if the athlete is mostly waiting, adjusting, repositioning, changing contact/support/implement relationship, or preparing before the target movement begins. "
        "Reject if the cut is the wrong exercise or variant, only setup, mostly static, partial, missing the start or finish/return, cut mid-repetition, visibly changes into a different grip/support/implement relationship, too unclear to verify, synthetic/rendered, or low-quality source evidence. "
        "If the contract says the exercise returns to start or has both directions, require both directions of the main movement. "
        "If unsure, set approved false and use unclear or low_confidence. "
        "Do not invent frame numbers, timestamps, selected candidate IDs, or chain-of-thought. "
        "reject must use only these fixed tags: wrong_exercise, wrong_variant, partial_movement, mechanics_inconsistent, contact_changed, bad_boundary, setup_or_filler, low_source_quality, low_confidence, synthetic_subject, unclear. Use [] only when approved is true. "
        "completeMovement must be true only when the full execution is visible from meaningful start through natural finish. "
        "startBoundaryClean must be false when the first frames are mid-repetition, recovery from a previous repetition, setup, waiting, equipment transition, or repositioning. A stable top or bottom posture is clean when it directly begins the reviewed repetition. "
        "finishBoundaryClean must be false when the final frames are mid-repetition, setup/reset, cleanup, equipment transition, changing contact/support/implement relationship, walking/stepping into or out of equipment, releasing/returning equipment, or missing the natural return/finish posture. "
        "setupOrFiller must be true when material setup, waiting, adjustment, unrack/rerack, reset, or filler is inside the cut. "
        "Decision order: first set completeMovement, startBoundaryClean, finishBoundaryClean, and setupOrFiller from the visible frames; then set approved true only when completeMovement is true, both boundary fields are true, setupOrFiller is false, confidence is high, and reject is empty. "
        "If approved is false, reject must contain at least one matching tag. If approved is true, reject must be []. "
        "note must be one short sentence with at most 10 words.\n"
        "Return JSON only with exactly one row in this schema: {\"candidates\": [{\"id\": string, \"approved\": boolean, \"confidence\": number_0_to_1, \"completeMovement\": boolean, \"startBoundaryClean\": boolean, \"finishBoundaryClean\": boolean, \"setupOrFiller\": boolean, \"namedEquipmentEngagedStatus\": \"engaged|absent|unclear|not_applicable\", \"reject\": [string], \"note\": string"
        + topology_schema
        + "}]}. "
        "Classify from visible evidence only; code applies thresholds, retries, and failure handling."
    )


def build_source_cut_exercise_contract_prompt_section(contract: dict[str, Any] | None) -> str:
    prompt_contract = exercise_motion_contract_for_prompt(contract)
    if prompt_contract is None:
        return ""
    return (
        "Exercise-specific source movement contract. Use this to judge whether the full visible window is a clean movement-only segment for the requested exercise. "
        "Treat this guidance as a visual checklist, not as proof that a window is correct. "
        "Reject windows that show a wrong variant, setup-only content, unclear evidence, partial movement, bad start boundary, bad finish boundary, or setup/reset/equipment transition according to this guidance. "
        "If the guidance includes Boundary, enforce it when setting startBoundaryClean, finishBoundaryClean, setupOrFiller, and approved. "
        "Do not add camera, crop, person-count, or exact timestamp duties.\n"
        f"{exercise_motion_contract_prompt_body(prompt_contract)}\n"
    )


def normalize_source_cut_candidate_id(value: object) -> str:
    text = str(value or "").strip().upper()
    if text.startswith("CANDIDATE "):
        text = text[len("CANDIDATE ") :].strip()
    return re.sub(r"[^A-Z0-9_-]", "", text)


def source_cut_candidate_id_for_index(index: int) -> str:
    value = max(0, int(index))
    parts: list[str] = []
    while True:
        value, remainder = divmod(value, 26)
        parts.append(chr(ord("A") + remainder))
        if value == 0:
            break
        value -= 1
    return "".join(reversed(parts))


def build_movement_cut_candidate_choice_prompt(
    *,
    exercise_name: str,
    candidate_title: str,
    candidate: SourceCutCandidate,
    exercise_motion_contract: dict[str, Any] | None = None,
    minimum_complete_duration_seconds: float | None = None,
) -> str:
    candidate_lines = cut_candidate_attachment_prompt_lines([candidate])
    contract_section = build_movement_cut_exercise_motion_contract_prompt_section(exercise_motion_contract)
    topology_evidence_section = movement_topology_evidence_prompt(exercise_motion_contract)
    topology_schema = (
        ', "startStateMatch": "match|mismatch|uncertain", "endStateMatch": "match|mismatch|uncertain", '
        '"phaseEvidence": [{"phaseId": string, "position": number_0_to_1}]'
        if topology_evidence_section
        else ""
    )
    duration_floor_section = (
        f"A complete movement should normally be at least {minimum_complete_duration_seconds:.2f}s for this exercise; "
        "treat shorter candidates as partial unless the full start, action path, and finish are unmistakably visible. "
        if minimum_complete_duration_seconds is not None and minimum_complete_duration_seconds > 0.0
        else ""
    )
    return (
        "Classify one candidate movement cut from the attached rendered/source review contact sheets.\n"
        f"Target exercise: {exercise_name}.\n"
        f"Candidate video title: {candidate_title}.\n"
        + contract_section
        + topology_evidence_section
        + duration_floor_section
        +
        "The candidate window may have one or more chronological contact sheets. Read all sheets together in attachment order. "
        "Boundary audit sheets repeat first or last frames at larger size; use them only to inspect whether the visible cut starts and ends cleanly. "
        f"{CONTACT_SHEET_READING_INSTRUCTIONS}"
        "Attachments are in this exact order:\n"
        + "\n".join(candidate_lines)
        + "\n\nClassify only this candidate. "
        "Ignore written labels, captions, arrows, diagrams, and instruction text; the visible body must perform all named actions/phases of the target movement. "
        "A candidate showing only one named phase is partial_movement, but do not require an extra repetition or extra return after the normal finish posture. "
        "The code will choose the shortest passing candidate after all candidates have been reviewed separately; do not select a winner. "
        "Do not approve a candidate merely because a correct repetition appears somewhere inside it; the whole candidate window must be the useful movement-only segment. "
        "Approve only when the frames clearly show one complete useful target movement: correct visible exercise, meaningful start, full action path, natural finish or return, and no material setup/reset/filler inside the cut. "
        "Reject if the movement is wrong, partial, mostly setup, mostly static, missing the start or finish/return, cut mid-repetition, includes setup/reset/equipment transition before or after the action, visibly changes into a different grip/support/implement relationship, or is too unclear to verify. "
        "If the contract says the exercise returns to start or has both directions, require both directions of the main movement. "
        "Do not require the first and last pose to match unless the target movement itself requires that. "
        "Do not invent timestamps, selected candidate IDs, frame numbers, or chain-of-thought. "
        "If unsure, set approved false and use unclear or low_confidence.\n"
        "Use reject tags only from: wrong_exercise, wrong_variant, partial_movement, mechanics_inconsistent, contact_changed, bad_boundary, setup_or_filler, low_source_quality, low_confidence, synthetic_subject, unclear. "
        "completeMovement must be true only when the full execution is visible from meaningful start through natural finish. "
        "startBoundaryClean must be false when the first frames are mid-repetition, bottom/end posture, recovery from a previous repetition, setup, waiting, equipment transition, or repositioning. "
        "finishBoundaryClean must be false when the final frames are mid-repetition, setup/reset, cleanup, equipment transition, changing contact/support/implement relationship, walking/stepping into or out of equipment, releasing/returning equipment, or missing the natural return/finish posture. "
        "setupOrFiller must be true when material setup, waiting, adjustment, unrack/rerack, reset, or filler is inside the cut. "
        "Strict phase-order check before approval: completeMovement must be false unless the ordered frames visibly show the target movement's meaningful start, the main action moving away from that start, the exercise-specific peak/end-range or required middle phase, and the natural return/finish after that phase. "
        "Do not count standing still, foot shuffling, walking/stepping under equipment, rack contact, equipment approach/exit, or repositioning as the target movement unless the exercise guidance explicitly defines that transition as the exercise. "
        "If the sequence mostly shows setup/transition and only the beginning of the target action, set completeMovement false, setupOrFiller true when applicable, and reject with partial_movement or setup_or_filler. "
        "Decision order: first set completeMovement, startBoundaryClean, finishBoundaryClean, and setupOrFiller from the visible frames; then set approved true only when completeMovement is true, both boundary fields are true, setupOrFiller is false, confidence is high, and reject is empty. "
        "If approved is false, reject must contain at least one matching tag. If approved is true, reject must be []. "
        "Keep note to one short sentence. Return JSON only with exactly one row in this schema: "
        "{\"candidates\":[{\"id\": string, \"approved\": boolean, \"confidence\": number_0_to_1, \"completeMovement\": boolean, \"startBoundaryClean\": boolean, \"finishBoundaryClean\": boolean, \"setupOrFiller\": boolean, \"reject\": [string], \"note\": string"
        + topology_schema
        + "}]}. Return exactly one row."
    )


def build_movement_cut_exercise_motion_contract_prompt_section(contract: dict[str, Any] | None) -> str:
    prompt_contract = exercise_motion_contract_for_prompt(contract)
    if prompt_contract is None:
        return ""
    return (
        "Movement-cut exercise guidance. Use this exercise-specific guidance to decide whether a candidate window contains the actual full target movement. "
        "A valid cut should include only the meaningful start, full action path, and natural finish/return described by the guidance. "
        "Reject windows that only show setup, only one phase, a wrong variant, a bad boundary, or setup/reset/equipment transition before or after the exercise action. "
        "If the guidance includes Boundary, enforce it as the movement-only segment contract. "
        "If no candidate window satisfies the guidance, choose null.\n"
        f"{exercise_motion_contract_prompt_body(prompt_contract)}\n"
    )


def build_final_output_source_contract_prompt_section(contract: dict[str, Any] | None) -> str:
    prompt_contract = exercise_motion_contract_for_prompt(contract)
    if prompt_contract is None:
        return ""
    guidance = exercise_motion_contract_prompt_body(prompt_contract)
    if not guidance:
        return ""
    return (
        "Final-output movement guidance. Use this exercise-specific guidance to understand the selected movement that the generated preview should preserve. "
        "Do not use it to re-select source boundaries or to hard-reject borderline source timing. "
        "Only hard-reject when the generated preview clearly violates the exercise identity or contains a clear artifact failure.\n"
        f"{guidance}\n"
    )


def exercise_motion_contract_for_review_item(item: ReviewItem, ranking: LoopRanking | None) -> dict[str, Any] | None:
    ranking_payload = ranking.payload if ranking is not None and isinstance(ranking.payload, dict) else {}
    contract = ranking_payload.get("exerciseMotionContract")
    if isinstance(contract, dict):
        prompt_contract = exercise_motion_contract_for_prompt(contract)
        if prompt_contract is not None:
            return prompt_contract
        if observable_motion_spec_for_contract(contract) is not None:
            return contract
    prompt_contract = exercise_motion_contract_from_candidate(item.candidate)
    if prompt_contract is not None:
        return prompt_contract
    segment_selection_path = item.candidate_workspace / "segment_detection" / "segment_selection.json"
    if not segment_selection_path.exists():
        return None
    try:
        segment_payload = json.loads(segment_selection_path.read_text(encoding="utf-8"))
    except Exception:
        return None
    if not isinstance(segment_payload, dict):
        return None
    contract = segment_payload.get("exerciseMotionContract")
    prompt_contract = exercise_motion_contract_for_prompt(contract if isinstance(contract, dict) else None)
    if prompt_contract is not None:
        return prompt_contract
    for stage in segment_payload.get("preWhamSourceValidationStages") or []:
        if not isinstance(stage, dict):
            continue
        contract = stage.get("exerciseMotionContract")
        prompt_contract = exercise_motion_contract_for_prompt(contract if isinstance(contract, dict) else None)
        if prompt_contract is not None:
            return prompt_contract
    return None


def exercise_motion_contract_from_candidate(candidate: dict[str, Any]) -> dict[str, Any] | None:
    candidate_contract = candidate.get("exerciseMotionContract")
    if isinstance(candidate_contract, dict):
        prompt_contract = exercise_motion_contract_for_prompt(candidate_contract)
        if prompt_contract is not None:
            return prompt_contract
        if observable_motion_spec_for_contract(candidate_contract) is not None:
            return candidate_contract

    payload = candidate.get("visionPayload")
    if not isinstance(payload, dict):
        return None
    for key in ("exerciseMotionContract",):
        contract = payload.get(key)
        prompt_contract = exercise_motion_contract_for_prompt(contract if isinstance(contract, dict) else None)
        if prompt_contract is not None:
            return prompt_contract
    advisory_payload = payload.get("advisoryVlmSourceReview")
    if isinstance(advisory_payload, dict):
        contract = advisory_payload.get("exerciseMotionContract")
        prompt_contract = exercise_motion_contract_for_prompt(contract if isinstance(contract, dict) else None)
        if prompt_contract is not None:
            return prompt_contract
    return None


def source_cut_frame_motion_rejection_reasons_from_visual_integrity(
    metrics: dict[str, Any],
    *,
    motion_coverage: dict[str, Any] | None = None,
) -> list[str]:
    if not metrics or not bool(metrics.get("passed", True)):
        return []
    diff_count = parse_optional_int(metrics.get("previousFrameDiffCount"))
    if diff_count is None or diff_count < 5:
        return []
    max_diff = parse_optional_float(metrics.get("maxPreviousFrameDiff")) or 0.0
    p90_diff = parse_optional_float(metrics.get("p90PreviousFrameDiff")) or 0.0
    active_ratio = parse_optional_float(metrics.get("activePreviousFrameDiffRatio")) or 0.0
    target_motion = (
        motion_coverage.get("targetMotionObservability")
        if isinstance(motion_coverage, dict)
        else None
    )
    active_travel_locomotion = (
        motion_coverage.get("activeTravelLocomotion")
        if isinstance(motion_coverage, dict)
        else None
    )
    active_travel_locomotion_passed = not (
        isinstance(active_travel_locomotion, dict)
        and bool(active_travel_locomotion.get("required"))
        and not bool(active_travel_locomotion.get("passed"))
    )
    if (
        isinstance(target_motion, dict)
        and bool(target_motion.get("required"))
        and bool(target_motion.get("passed"))
        and active_travel_locomotion_passed
    ):
        return []
    if max_diff < SOURCE_CUT_MIN_STATIC_MAX_FRAME_DIFF and p90_diff < SOURCE_CUT_MIN_P90_FRAME_DIFF:
        return ["source_cut_too_static"]
    if (
        active_ratio < SOURCE_CUT_MIN_ACTIVE_FRAME_DIFF_RATIO
        and p90_diff < SOURCE_CUT_MIN_P90_FRAME_DIFF
        and max_diff < SOURCE_CUT_WEAK_MOTION_MAX_FRAME_DIFF
    ):
        return ["source_cut_weak_visual_motion"]
    return []


def source_cut_candidates_payload(candidates: list[SourceCutCandidate]) -> list[dict[str, Any]]:
    return [
        {
            "candidateId": candidate.candidate_id,
            "startSeconds": candidate.window.start_seconds,
            "endSeconds": candidate.window.end_seconds,
            "framePaths": [str(path) for path in candidate.frame_paths],
            "boundaryAuditFramePaths": [str(path) for path in candidate.boundary_audit_frame_paths],
            "sampleFramePaths": [str(path) for path in candidate.sample_frame_paths],
            "visualIntegrity": candidate.visual_integrity,
            "frameMotionRejectionReasons": source_cut_frame_motion_rejection_reasons_from_visual_integrity(
                candidate.visual_integrity,
                motion_coverage=candidate.motion_coverage,
            ),
            "posePrefilter": candidate.pose_prefilter,
            **({"motionCoverage": candidate.motion_coverage} if candidate.motion_coverage else {}),
            **({"chunking": candidate.chunking} if candidate.chunking else {}),
        }
        for candidate in candidates
    ]


def movement_cut_manual_trim_payload(
    *,
    reason: str,
    candidates: list[SourceCutCandidate],
    scorecard_rows: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "movementCutManualTrimRequired": True,
        "movementCutManualTrimReason": reason,
        "movementCutManualTrimCandidateWindows": source_cut_candidates_payload(candidates),
    }
    if scorecard_rows is not None:
        payload["movementCutManualTrimScorecardCandidates"] = scorecard_rows
    return payload


def source_cut_sample_frame_paths(output_dir: Path) -> list[Path]:
    return sorted(path for path in output_dir.glob("frame_*.jpg") if path.is_file())


def detect_source_scene_boundaries(
    video_path: Path,
    *,
    timeline_window: DetectionWindow,
    cache_path: Path | None = None,
) -> dict[str, Any]:
    """Detect edits/fades once for the parent source interval with PySceneDetect."""
    started = time.perf_counter()
    start_seconds = max(0.0, float(timeline_window.start_seconds))
    end_seconds = max(start_seconds, float(timeline_window.end_seconds))
    cache_key = source_scene_analysis_cache_key(
        video_path,
        start_seconds=start_seconds,
        end_seconds=end_seconds,
    )
    cached = load_source_scene_analysis_cache(cache_path, expected_cache_key=cache_key)
    if cached is not None:
        return {
            **cached,
            "cacheStatus": "reused",
            "cachePath": str(cache_path.resolve()) if cache_path is not None else None,
            "cacheLookupElapsedSeconds": elapsed_seconds(started),
        }
    base_payload: dict[str, Any] = {
        "enabled": True,
        "analysisStartSeconds": round(start_seconds, 3),
        "analysisEndSeconds": round(end_seconds, 3),
        "detectors": ["AdaptiveDetector", "ThresholdDetector"],
        "sceneAnalysisPolicyVersion": SOURCE_CUT_SCENE_ANALYSIS_POLICY_VERSION,
        "sourceCacheKey": cache_key,
        "cacheStatus": "generated",
        "cachePath": str(cache_path.resolve()) if cache_path is not None else None,
    }
    if end_seconds - start_seconds <= SOURCE_CUT_SCENE_BOUNDARY_EDGE_TOLERANCE_SECONDS * 2.0:
        result = {
            **base_payload,
            "status": "interval_too_short",
            "boundarySeconds": [],
            "sceneCount": 1,
            "elapsedSeconds": elapsed_seconds(started),
        }
        write_source_scene_analysis_cache(cache_path, result)
        return result
    try:
        from scenedetect import AdaptiveDetector, SceneManager, ThresholdDetector, open_video  # type: ignore
    except ImportError as exc:
        return {
            **base_payload,
            "status": "dependency_unavailable",
            "boundarySeconds": [],
            "sceneCount": 0,
            "error": str(exc)[:500],
            "elapsedSeconds": elapsed_seconds(started),
        }

    try:
        video = open_video(str(video_path))
        video.seek(start_seconds)
        scene_manager = SceneManager()
        scene_manager.auto_downscale = True
        scene_manager.add_detector(
            AdaptiveDetector(
                adaptive_threshold=3.0,
                min_scene_len=SOURCE_CUT_SCENE_MIN_LENGTH_SECONDS,
                window_width=2,
                min_content_val=15.0,
            )
        )
        scene_manager.add_detector(
            ThresholdDetector(
                threshold=12.0,
                min_scene_len=SOURCE_CUT_SCENE_MIN_LENGTH_SECONDS,
                add_final_scene=True,
            )
        )
        processed_frame_count = scene_manager.detect_scenes(
            video=video,
            end_time=end_seconds,
            show_progress=False,
        )
        scenes = scene_manager.get_scene_list(start_in_scene=True)
        boundary_seconds = sorted(
            {
                round(float(scene_start.seconds), 6)
                for scene_start, _scene_end in scenes[1:]
                if start_seconds < float(scene_start.seconds) < end_seconds
            }
        )
        result = {
            **base_payload,
            "status": "ok",
            "boundarySeconds": boundary_seconds,
            "sceneCount": max(1, len(scenes)),
            "processedFrameCount": int(processed_frame_count),
            "elapsedSeconds": elapsed_seconds(started),
        }
        write_source_scene_analysis_cache(cache_path, result)
        return result
    except Exception as exc:
        return {
            **base_payload,
            "status": "analysis_failed",
            "boundarySeconds": [],
            "sceneCount": 0,
            "errorType": type(exc).__name__,
            "error": str(exc)[:500],
            "elapsedSeconds": elapsed_seconds(started),
        }


def source_scene_analysis_cache_key(
    video_path: Path,
    *,
    start_seconds: float,
    end_seconds: float,
) -> str:
    payload = {
        "policyVersion": SOURCE_CUT_SCENE_ANALYSIS_POLICY_VERSION,
        "sourceSha256": file_sha256(video_path),
        "startSeconds": round(start_seconds, 6),
        "endSeconds": round(end_seconds, 6),
        "adaptiveThreshold": 3.0,
        "adaptiveWindowWidth": 2,
        "adaptiveMinContentValue": 15.0,
        "thresholdDetectorThreshold": 12.0,
        "minSceneLengthSeconds": SOURCE_CUT_SCENE_MIN_LENGTH_SECONDS,
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def load_source_scene_analysis_cache(
    cache_path: Path | None,
    *,
    expected_cache_key: str,
) -> dict[str, Any] | None:
    if cache_path is None or not cache_path.exists():
        return None
    try:
        payload = json.loads(cache_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, TypeError):
        return None
    if not isinstance(payload, dict):
        return None
    if payload.get("sourceCacheKey") != expected_cache_key:
        return None
    if parse_optional_int(payload.get("sceneAnalysisPolicyVersion")) != SOURCE_CUT_SCENE_ANALYSIS_POLICY_VERSION:
        return None
    if payload.get("status") not in {"ok", "interval_too_short"}:
        return None
    return payload


def write_source_scene_analysis_cache(
    cache_path: Path | None,
    payload: dict[str, Any],
) -> None:
    if cache_path is None:
        return
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path = cache_path.with_name(
        f"{cache_path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    temporary_path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    temporary_path.replace(cache_path)


def source_camera_stability_cache_key(
    scene_detection: dict[str, Any],
    *,
    pose_payload: dict[str, Any] | None,
    source_offset_seconds: float,
) -> str:
    pose_mask_evidence: list[dict[str, Any]] = []
    if isinstance(pose_payload, dict):
        for sample in pose_payload.get("dominantPoseSamples") or []:
            if not isinstance(sample, dict):
                continue
            pose_mask_evidence.append(
                {
                    "timeSeconds": first_float(
                        sample.get("timeSeconds"),
                        sample.get("timestampSeconds"),
                        sample.get("time"),
                        sample.get("timestamp"),
                    ),
                    "bbox": sample.get("bbox") or sample.get("boundingBox"),
                }
            )
    payload = {
        "policyVersion": CAMERA_STABILITY_POLICY_VERSION,
        "sourceCacheKey": scene_detection.get("sourceCacheKey"),
        "sourceOffsetSeconds": round(source_offset_seconds, 6),
        "sceneBoundaries": scene_detection.get("boundarySeconds") or [],
        "poseMaskEvidence": pose_mask_evidence,
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def add_source_scene_camera_stability(
    video_path: Path,
    *,
    timeline_window: DetectionWindow,
    scene_detection: dict[str, Any],
    pose_payload: dict[str, Any] | None,
    source_offset_seconds: float,
    cache_path: Path | None,
) -> dict[str, Any]:
    cache_key = source_camera_stability_cache_key(
        scene_detection,
        pose_payload=pose_payload,
        source_offset_seconds=source_offset_seconds,
    )
    cached_report = scene_detection.get("cameraStability")
    if (
        scene_detection.get("cameraStabilityCacheKey") == cache_key
        and isinstance(cached_report, dict)
        and parse_optional_int(cached_report.get("policyVersion")) == CAMERA_STABILITY_POLICY_VERSION
    ):
        return {
            **scene_detection,
            "cameraStability": {**cached_report, "cacheStatus": "reused"},
        }
    scene_windows = cut_free_source_scene_windows(
        scene_detection,
        timeline_window=timeline_window,
    )
    report = analyze_video_scene_camera_stability(
        video_path,
        scene_windows=scene_windows,
        pose_payload=pose_payload,
        source_offset_seconds=source_offset_seconds,
    )
    enriched = {
        **scene_detection,
        "cameraStabilityCacheKey": cache_key,
        "cameraStability": {**report, "cacheStatus": "generated"},
    }
    write_source_scene_analysis_cache(cache_path, enriched)
    return enriched


def cut_free_source_scene_windows(
    scene_detection: dict[str, Any] | None,
    *,
    timeline_window: DetectionWindow,
) -> list[DetectionWindow]:
    start_seconds = float(timeline_window.start_seconds)
    end_seconds = float(timeline_window.end_seconds)
    if end_seconds <= start_seconds:
        return []
    boundaries: list[float] = []
    if isinstance(scene_detection, dict) and scene_detection.get("status") == "ok":
        tolerance = SOURCE_CUT_SCENE_BOUNDARY_EDGE_TOLERANCE_SECONDS
        boundaries = sorted(
            {
                float(value)
                for value in scene_detection.get("boundarySeconds") or []
                if isinstance(value, (int, float))
                and start_seconds + tolerance < float(value) < end_seconds - tolerance
            }
        )
    edges = [start_seconds, *boundaries, end_seconds]
    return [
        DetectionWindow(index=index, start_seconds=scene_start, end_seconds=scene_end)
        for index, (scene_start, scene_end) in enumerate(zip(edges, edges[1:]))
        if scene_end > scene_start
    ]


def source_scene_camera_stability_by_index(
    scene_detection: dict[str, Any] | None,
) -> dict[int, dict[str, Any]]:
    if not isinstance(scene_detection, dict):
        return {}
    report = scene_detection.get("cameraStability")
    if not isinstance(report, dict):
        return {}
    return {
        int(item["sceneIndex"]): item
        for item in report.get("scenes") or []
        if isinstance(item, dict) and isinstance(item.get("sceneIndex"), int)
    }


def candidate_source_scene_windows(
    scene_detection: dict[str, Any] | None,
    *,
    timeline_window: DetectionWindow,
) -> list[DetectionWindow]:
    scene_windows = cut_free_source_scene_windows(
        scene_detection,
        timeline_window=timeline_window,
    )
    camera_metrics = source_scene_camera_stability_by_index(scene_detection)
    return [
        scene
        for scene in scene_windows
        if str(camera_metrics.get(scene.index, {}).get("classification") or "unknown")
        in {"stable", "unknown"}
    ]


def source_scene_camera_stability_summary(
    scene_detection: dict[str, Any] | None,
    *,
    scene_index: int,
) -> dict[str, Any] | None:
    metrics = source_scene_camera_stability_by_index(scene_detection).get(scene_index)
    if metrics is None:
        return None
    return {key: value for key, value in metrics.items() if key != "pairs"}


def add_source_scene_metadata(
    spec: SourceWindowCandidateSpec,
    *,
    scene_window: DetectionWindow,
    scene_count: int,
    camera_stability: dict[str, Any] | None = None,
) -> SourceWindowCandidateSpec:
    return SourceWindowCandidateSpec(
        window=spec.window,
        chunking={
            **spec.chunking,
            "sceneAware": True,
            "sceneIndex": scene_window.index,
            "sceneCount": scene_count,
            "sceneStartSeconds": round(scene_window.start_seconds, 3),
            "sceneEndSeconds": round(scene_window.end_seconds, 3),
            **(
                {"backgroundCameraStability": camera_stability}
                if camera_stability is not None
                else {}
            ),
        },
    )


def build_scene_aware_source_video_candidate_windows(
    *,
    timeline_window: DetectionWindow,
    scene_detection: dict[str, Any] | None,
    chunk_estimate: Any,
    min_duration_floor_seconds: float,
    use_estimated_duration_floor: bool = True,
) -> list[SourceWindowCandidateSpec]:
    all_scene_windows = cut_free_source_scene_windows(
        scene_detection,
        timeline_window=timeline_window,
    )
    scene_windows = candidate_source_scene_windows(
        scene_detection,
        timeline_window=timeline_window,
    )
    specs: list[SourceWindowCandidateSpec] = []
    seen: set[tuple[float, float]] = set()
    for scene_window in scene_windows:
        scene_specs = build_source_video_pyramid_candidate_windows(
            window=scene_window,
            chunk_estimate=chunk_estimate,
            min_duration_floor_seconds=min_duration_floor_seconds,
            use_estimated_duration_floor=use_estimated_duration_floor,
        )
        for scene_spec in scene_specs:
            if isinstance(scene_spec, DetectionWindow):
                scene_spec = SourceWindowCandidateSpec(window=scene_spec)
            key = (
                round(scene_spec.window.start_seconds, 2),
                round(scene_spec.window.end_seconds, 2),
            )
            if key in seen:
                continue
            seen.add(key)
            specs.append(
                add_source_scene_metadata(
                    scene_spec,
                    scene_window=scene_window,
                    scene_count=len(all_scene_windows),
                    camera_stability=source_scene_camera_stability_summary(
                        scene_detection,
                        scene_index=scene_window.index,
                    ),
                )
            )
    return [
        SourceWindowCandidateSpec(
            window=DetectionWindow(
                index=index,
                start_seconds=spec.window.start_seconds,
                end_seconds=spec.window.end_seconds,
            ),
            chunking=spec.chunking,
        )
        for index, spec in enumerate(specs)
    ]


def source_cut_scene_integrity_metrics(
    scene_detection: dict[str, Any] | None,
    *,
    candidate_window: DetectionWindow,
) -> dict[str, Any]:
    """Reject candidates that cross a detected edit while allowing aligned edges."""
    if not isinstance(scene_detection, dict):
        return {
            "enabled": False,
            "status": "not_run",
            "passed": True,
            "rejectionReasons": [],
            "internalBoundarySeconds": [],
        }
    status = str(scene_detection.get("status") or "unknown")
    start_seconds = float(candidate_window.start_seconds)
    end_seconds = float(candidate_window.end_seconds)
    tolerance = SOURCE_CUT_SCENE_BOUNDARY_EDGE_TOLERANCE_SECONDS
    internal_boundaries = [
        float(value)
        for value in scene_detection.get("boundarySeconds") or []
        if isinstance(value, (int, float))
        and start_seconds + tolerance < float(value) < end_seconds - tolerance
    ]
    passed = not internal_boundaries
    return {
        "enabled": bool(scene_detection.get("enabled", True)),
        "status": status,
        "passed": passed,
        "rejectionReasons": [] if passed else ["source_cut_scene_transition"],
        "candidateStartSeconds": round(start_seconds, 3),
        "candidateEndSeconds": round(end_seconds, 3),
        "edgeToleranceSeconds": tolerance,
        "internalBoundarySeconds": [round(value, 3) for value in internal_boundaries],
        "analysisStartSeconds": scene_detection.get("analysisStartSeconds"),
        "analysisEndSeconds": scene_detection.get("analysisEndSeconds"),
        "analysisElapsedSeconds": scene_detection.get("elapsedSeconds"),
        "sceneCount": scene_detection.get("sceneCount"),
        "processedFrameCount": scene_detection.get("processedFrameCount"),
        "detectors": scene_detection.get("detectors", []),
        **(
            {"analysisErrorType": scene_detection.get("errorType")}
            if scene_detection.get("errorType")
            else {}
        ),
        **({"analysisError": scene_detection.get("error")} if scene_detection.get("error") else {}),
    }


def merge_source_cut_scene_integrity(
    visual_integrity: dict[str, Any],
    scene_integrity: dict[str, Any] | None,
) -> dict[str, Any]:
    if not isinstance(scene_integrity, dict):
        return visual_integrity
    merged = dict(visual_integrity)
    merged["sceneDetection"] = scene_integrity
    scene_rejections = [str(reason) for reason in scene_integrity.get("rejectionReasons") or [] if str(reason)]
    merged["rejectionReasons"] = dedupe_text(
        [str(reason) for reason in merged.get("rejectionReasons") or [] if str(reason)]
        + scene_rejections
    )
    merged["passed"] = bool(merged.get("passed", True)) and bool(scene_integrity.get("passed", True))
    return merged


def merge_source_cut_camera_stability(
    visual_integrity: dict[str, Any],
    camera_stability: dict[str, Any] | None,
) -> dict[str, Any]:
    if not isinstance(camera_stability, dict):
        return visual_integrity
    merged = dict(visual_integrity)
    merged["backgroundCameraStability"] = camera_stability
    classification = str(camera_stability.get("classification") or "unknown")
    rejection_reasons = [
        str(reason)
        for reason in merged.get("rejectionReasons") or []
        if str(reason)
    ]
    if classification == "stable":
        # Background feature tracking distinguishes camera motion from the
        # athlete's motion, so it owns this decision when it is conclusive.
        rejection_reasons = [
            reason
            for reason in rejection_reasons
            if reason != "source_cut_excessive_camera_motion"
        ]
        merged["legacyCameraMotionHeuristicSuppressed"] = True
    elif classification in {"moderate", "unstable"}:
        rejection_reasons.append("source_scene_unstable_camera")
    merged["rejectionReasons"] = dedupe_text(rejection_reasons)
    merged["passed"] = not merged["rejectionReasons"]
    return merged


def source_cut_visual_integrity_metrics(frame_paths: list[Path]) -> dict[str, Any]:
    if not frame_paths:
        return {
            "passed": False,
            "rejectionReasons": ["source_cut_no_sample_frames"],
            "sampleFrameCount": 0,
        }
    try:
        import cv2  # type: ignore
        import numpy as np  # type: ignore
    except ImportError:
        return {
            "passed": False,
            "rejectionReasons": ["source_cut_visual_integrity_dependencies_missing"],
            "sampleFrameCount": len(frame_paths),
        }

    samples: list[dict[str, Any]] = []
    previous_image = None
    previous_layout_signature: tuple[float, ...] | None = None
    previous_edge_signature: tuple[float, ...] | None = None
    for index, frame_path in enumerate(frame_paths):
        image = cv2.imread(str(frame_path))
        if image is None:
            samples.append({"frameIndex": index, "path": str(frame_path), "readable": False})
            continue
        hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        edges = cv2.Canny(gray, 50, 150)
        frame_diff = None
        if previous_image is not None and previous_image.shape == image.shape:
            frame_diff = float(np.mean(cv2.absdiff(image, previous_image)) / 255.0)
        previous_image = image
        layout_signature = compute_frame_layout_signature(image)
        edge_signature = compute_frame_edge_signature(image)
        layout_jump = signature_mean_absolute_difference(previous_layout_signature, layout_signature)
        edge_jump = signature_mean_absolute_difference(previous_edge_signature, edge_signature)
        previous_layout_signature = layout_signature
        previous_edge_signature = edge_signature
        samples.append(
            {
                "frameIndex": index,
                "path": str(frame_path),
                "readable": True,
                "grayMean": float(np.mean(gray)),
                "grayStd": float(np.std(gray)),
                "nonWhiteRatio": float(np.mean(np.any(image < 245, axis=2))),
                "darkRatio": float(np.mean(gray < 80)),
                "saturatedRatio": float(np.mean(hsv[:, :, 1] > 30)),
                "edgeRatio": float(np.mean(edges > 0)),
                "previousFrameDiff": frame_diff,
                "frameLayoutJump": layout_jump,
                "frameEdgeJump": edge_jump,
            }
        )

    readable = [sample for sample in samples if sample.get("readable")]
    if len(readable) < max(3, min(4, len(frame_paths))):
        return {
            "passed": False,
            "rejectionReasons": ["source_cut_too_few_readable_frames"],
            "sampleFrameCount": len(frame_paths),
            "readableFrameCount": len(readable),
            "frames": samples,
        }

    def median_metric(key: str) -> float:
        values = [float(sample[key]) for sample in readable if isinstance(sample.get(key), (int, float))]
        return float(np.median(values)) if values else 0.0

    median_gray_std = median_metric("grayStd")
    median_dark_ratio = median_metric("darkRatio")
    median_saturated_ratio = median_metric("saturatedRatio")
    median_non_white_ratio = median_metric("nonWhiteRatio")
    median_edge_ratio = median_metric("edgeRatio")
    washed_out_frames: list[int] = []
    for sample in readable:
        gray_std = float(sample["grayStd"])
        dark_ratio = float(sample["darkRatio"])
        saturated_ratio = float(sample["saturatedRatio"])
        non_white_ratio = float(sample["nonWhiteRatio"])
        edge_ratio = float(sample["edgeRatio"])
        low_contrast_outlier = gray_std < median_gray_std * 0.82
        low_dark_outlier = dark_ratio < max(0.025, median_dark_ratio * 0.40)
        low_saturation_outlier = saturated_ratio < max(0.03, median_saturated_ratio * 0.40)
        low_foreground_outlier = non_white_ratio < max(0.10, median_non_white_ratio * 0.55)
        weak_edges_outlier = edge_ratio < max(0.035, median_edge_ratio * 0.70)
        if (low_contrast_outlier and (low_dark_outlier or low_saturation_outlier or low_foreground_outlier)) or (
            low_dark_outlier and low_saturation_outlier and weak_edges_outlier
        ):
            washed_out_frames.append(int(sample["frameIndex"]))

    frame_diffs = [
        float(sample["previousFrameDiff"])
        for sample in readable
        if isinstance(sample.get("previousFrameDiff"), (int, float))
    ]
    layout_jumps = [
        float(sample["frameLayoutJump"])
        for sample in readable
        if isinstance(sample.get("frameLayoutJump"), (int, float))
    ]
    edge_jumps = [
        float(sample["frameEdgeJump"])
        for sample in readable
        if isinstance(sample.get("frameEdgeJump"), (int, float))
    ]
    max_frame_diff = max(frame_diffs) if frame_diffs else 0.0
    median_frame_diff = float(np.median(frame_diffs)) if frame_diffs else 0.0
    p75_frame_diff = float(np.percentile(frame_diffs, 75)) if frame_diffs else 0.0
    p90_frame_diff = float(np.percentile(frame_diffs, 90)) if frame_diffs else 0.0
    active_frame_diff_count = sum(
        1
        for frame_diff in frame_diffs
        if frame_diff >= SOURCE_CUT_ACTIVE_FRAME_DIFF_THRESHOLD
    )
    active_frame_diff_ratio = active_frame_diff_count / max(1, len(frame_diffs))
    max_layout_jump = max(layout_jumps) if layout_jumps else 0.0
    max_edge_jump = max(edge_jumps) if edge_jumps else 0.0
    median_layout_jump = float(np.median(layout_jumps)) if layout_jumps else 0.0
    median_edge_jump = float(np.median(edge_jumps)) if edge_jumps else 0.0
    excessive_camera_motion = bool(
        len(layout_jumps) >= 2
        and len(edge_jumps) >= 2
        and median_layout_jump >= FRAME_LAYOUT_SUSTAINED_CAMERA_MOTION_THRESHOLD
        and median_edge_jump >= FRAME_EDGE_SUSTAINED_CAMERA_MOTION_THRESHOLD
    )
    visual_jump_count = sum(
        1
        for sample in readable
        if source_cut_sample_has_visual_jump(
            parse_optional_float(sample.get("frameLayoutJump")),
            parse_optional_float(sample.get("frameEdgeJump")),
        )
    )
    visual_jump_ratio = visual_jump_count / max(1, len(readable) - 1)
    visual_jump_blocking = source_cut_visual_jump_is_blocking(
        visual_jump_count=visual_jump_count,
        visual_jump_ratio=visual_jump_ratio,
        max_frame_diff=max_frame_diff,
    )
    readable_frame_indexes = [int(sample["frameIndex"]) for sample in readable]
    boundary_frame_indexes = set(readable_frame_indexes[:1] + readable_frame_indexes[-1:])
    washed_out_blocking = bool(boundary_frame_indexes.intersection(washed_out_frames)) or (
        max_consecutive_integer_run(washed_out_frames) >= 2
    )
    rejection_reasons: list[str] = []
    if washed_out_blocking:
        rejection_reasons.append("source_cut_washed_out_or_fade_frame")
    if visual_jump_blocking:
        rejection_reasons.append("source_cut_visual_jump")
    if excessive_camera_motion:
        rejection_reasons.append("source_cut_excessive_camera_motion")
    return {
        "passed": not rejection_reasons,
        "rejectionReasons": rejection_reasons,
        "sampleFrameCount": len(frame_paths),
        "readableFrameCount": len(readable),
        "washedOutFrameIndexes": washed_out_frames,
        "washedOutBlocking": washed_out_blocking,
        "maxPreviousFrameDiff": max_frame_diff,
        "medianPreviousFrameDiff": median_frame_diff,
        "p75PreviousFrameDiff": p75_frame_diff,
        "p90PreviousFrameDiff": p90_frame_diff,
        "previousFrameDiffCount": len(frame_diffs),
        "activePreviousFrameDiffThreshold": SOURCE_CUT_ACTIVE_FRAME_DIFF_THRESHOLD,
        "activePreviousFrameDiffCount": active_frame_diff_count,
        "activePreviousFrameDiffRatio": active_frame_diff_ratio,
        "visualJumpCount": visual_jump_count,
        "visualJumpRatio": visual_jump_ratio,
        "visualJumpBlocking": visual_jump_blocking,
        "maxFrameLayoutJump": max_layout_jump,
        "maxFrameEdgeJump": max_edge_jump,
        "medianFrameLayoutJump": median_layout_jump,
        "medianFrameEdgeJump": median_edge_jump,
        "excessiveCameraMotion": excessive_camera_motion,
        "medianGrayStd": median_gray_std,
        "medianDarkRatio": median_dark_ratio,
        "medianSaturatedRatio": median_saturated_ratio,
        "medianNonWhiteRatio": median_non_white_ratio,
        "medianEdgeRatio": median_edge_ratio,
        "frames": samples,
    }


def max_consecutive_integer_run(values: list[int]) -> int:
    longest = 0
    current = 0
    previous: int | None = None
    for value in sorted(set(values)):
        current = current + 1 if previous is not None and value == previous + 1 else 1
        longest = max(longest, current)
        previous = value
    return longest


def source_cut_visual_jump_is_blocking(
    *,
    visual_jump_count: int,
    visual_jump_ratio: float,
    max_frame_diff: float,
) -> bool:
    if visual_jump_count <= 0 and max_frame_diff < 0.18:
        return False
    # A real edit is normally an isolated discontinuity. Dense moderate changes
    # across most samples are continuous large body motion, not repeated cuts.
    return max_frame_diff >= 0.45 or visual_jump_ratio <= 0.35


def source_cut_sample_has_visual_jump(layout_jump: float | None, edge_jump: float | None) -> bool:
    layout_value = layout_jump or 0.0
    edge_value = edge_jump or 0.0
    return (
        layout_value >= FRAME_LAYOUT_HARD_CUT_JUMP_THRESHOLD
        or edge_value >= FRAME_EDGE_HARD_CUT_JUMP_THRESHOLD
        or (
            layout_value >= FRAME_LAYOUT_CUT_JUMP_THRESHOLD
            and edge_value >= FRAME_EDGE_CUT_JUMP_THRESHOLD
        )
    )


def source_cut_sample_timestamps(
    *,
    candidate_window: DetectionWindow,
    sample_count: int,
) -> list[float]:
    if sample_count <= 0:
        return []
    if sample_count == 1:
        return [candidate_window.start_seconds]
    duration = max(0.0, candidate_window.end_seconds - candidate_window.start_seconds)
    return [
        candidate_window.start_seconds + duration * (index / max(1, sample_count - 1))
        for index in range(sample_count)
    ]


def build_source_cut_boundary_audit_contact_sheets(
    *,
    sample_frame_paths: list[Path],
    candidate_window: DetectionWindow,
    output_dir: Path,
) -> list[Path]:
    sample_count = len(sample_frame_paths)
    if sample_count < 4:
        return []
    frame_count = min(SOURCE_CUT_BOUNDARY_AUDIT_FRAME_COUNT, sample_count)
    timestamps = source_cut_sample_timestamps(
        candidate_window=candidate_window,
        sample_count=sample_count,
    )
    audit_paths: list[Path] = []
    start_sheet = build_frame_contact_sheet(
        frame_paths=sample_frame_paths[:frame_count],
        timestamps=timestamps[:frame_count],
        output_path=output_dir / "start_boundary_audit_contact_sheet.jpg",
        columns=contact_sheet_columns(frame_count),
        tile_width=SOURCE_CUT_BOUNDARY_AUDIT_TILE_WIDTH,
        jpeg_quality=SOURCE_CUT_BOUNDARY_AUDIT_JPEG_QUALITY,
        sequence_labels=True,
        sequence_label_offset=0,
        sequence_label_total=sample_count,
    )
    if start_sheet is not None:
        audit_paths.append(start_sheet)
    if sample_count > frame_count:
        finish_start_index = max(0, sample_count - frame_count)
        finish_sheet = build_frame_contact_sheet(
            frame_paths=sample_frame_paths[finish_start_index:],
            timestamps=timestamps[finish_start_index:],
            output_path=output_dir / "finish_boundary_audit_contact_sheet.jpg",
            columns=contact_sheet_columns(frame_count),
            tile_width=SOURCE_CUT_BOUNDARY_AUDIT_TILE_WIDTH,
            jpeg_quality=SOURCE_CUT_BOUNDARY_AUDIT_JPEG_QUALITY,
            sequence_labels=True,
            sequence_label_offset=finish_start_index,
            sequence_label_total=sample_count,
        )
        if finish_sheet is not None:
            audit_paths.append(finish_sheet)
    return audit_paths


def build_source_cut_candidate(
    *,
    candidate_id: str,
    candidate_window: DetectionWindow,
    contact_sheet_paths: list[Path],
    output_dir: Path,
    pose_prefilter: dict[str, Any] | None = None,
    chunking: dict[str, Any] | None = None,
    scene_integrity: dict[str, Any] | None = None,
    camera_stability: dict[str, Any] | None = None,
    include_boundary_audit: bool = False,
) -> SourceCutCandidate | None:
    if not contact_sheet_paths:
        return None
    sample_frame_paths = source_cut_sample_frame_paths(output_dir)
    visual_integrity = merge_source_cut_camera_stability(
        merge_source_cut_scene_integrity(
            source_cut_visual_integrity_metrics(sample_frame_paths),
            scene_integrity,
        ),
        camera_stability,
    )
    boundary_audit_paths = (
        build_source_cut_boundary_audit_contact_sheets(
            sample_frame_paths=sample_frame_paths,
            candidate_window=candidate_window,
            output_dir=output_dir,
        )
        if include_boundary_audit
        else []
    )
    return SourceCutCandidate(
        candidate_id=candidate_id,
        window=candidate_window,
        frame_paths=list(contact_sheet_paths),
        boundary_audit_frame_paths=boundary_audit_paths,
        sample_frame_paths=sample_frame_paths,
        visual_integrity=visual_integrity,
        pose_prefilter=pose_prefilter or {},
        chunking=chunking or {},
    )


def source_cut_candidate_passes_visual_integrity(candidate: SourceCutCandidate) -> bool:
    return bool(candidate.visual_integrity.get("passed"))


def source_cut_candidate_visual_rejection_reasons(
    candidate: SourceCutCandidate,
    *,
    ignore_reasons: Iterable[str] = (),
) -> list[str]:
    ignored = {str(reason) for reason in ignore_reasons}
    return [
        str(reason)
        for reason in candidate.visual_integrity.get("rejectionReasons") or []
        if str(reason) and str(reason) not in ignored
    ]


def source_cut_candidate_frame_motion_rejection_reasons(candidate: SourceCutCandidate) -> list[str]:
    return source_cut_frame_motion_rejection_reasons_from_visual_integrity(
        candidate.visual_integrity,
        motion_coverage=candidate.motion_coverage,
    )


def source_cut_candidate_passes_frame_motion(candidate: SourceCutCandidate) -> bool:
    return not source_cut_candidate_frame_motion_rejection_reasons(candidate)


def source_cut_pose_valid_chunks(pose_payload: dict[str, Any] | None) -> list[dict[str, float]]:
    if not isinstance(pose_payload, dict):
        return []
    valid_chunks = pose_payload.get("validChunks")
    if not isinstance(valid_chunks, list):
        return []
    chunks: list[dict[str, float]] = []
    for item in valid_chunks:
        if not isinstance(item, dict):
            continue
        start = parse_optional_float(item.get("startSeconds"))
        end = parse_optional_float(item.get("endSeconds"))
        if start is None or end is None or end <= start:
            continue
        chunks.append(
            {
                "startSeconds": start,
                "endSeconds": end,
                "score": parse_optional_float(item.get("score")) or 0.0,
            }
        )
    return chunks


def source_cut_candidate_pose_prefilter_metrics(
    *,
    candidate_window: DetectionWindow,
    pose_payload: dict[str, Any] | None,
    source_offset_seconds: float = 0.0,
) -> dict[str, Any]:
    valid_chunks = source_cut_pose_valid_chunks(pose_payload)
    candidate_start = max(0.0, source_offset_seconds + candidate_window.start_seconds)
    candidate_end = max(candidate_start, source_offset_seconds + candidate_window.end_seconds)
    candidate_duration = max(0.0, candidate_end - candidate_start)
    if not valid_chunks:
        return {
            "enabled": False,
            "passed": True,
            "skippedReasons": ["source_cut_pose_prefilter_payload_unavailable"],
            "sourceOffsetSeconds": source_offset_seconds,
            "candidateOriginalStartSeconds": candidate_start,
            "candidateOriginalEndSeconds": candidate_end,
        }
    best_overlap = 0.0
    best_chunk: dict[str, float] | None = None
    for chunk in valid_chunks:
        overlap_start = max(candidate_start, chunk["startSeconds"])
        overlap_end = min(candidate_end, chunk["endSeconds"])
        overlap = max(0.0, overlap_end - overlap_start)
        if overlap > best_overlap:
            best_overlap = overlap
            best_chunk = chunk
    overlap_ratio = best_overlap / max(candidate_duration, 1e-6)
    passed = overlap_ratio >= 0.20 or (
        best_chunk is not None
        and candidate_start >= best_chunk["startSeconds"] - 0.25
        and candidate_end <= best_chunk["endSeconds"] + 0.25
    )
    return {
        "enabled": True,
        "passed": passed,
        "rejectionReasons": [] if passed else ["source_cut_no_yolo_pose_motion_overlap"],
        "sourceOffsetSeconds": source_offset_seconds,
        "candidateOriginalStartSeconds": candidate_start,
        "candidateOriginalEndSeconds": candidate_end,
        "bestPoseOverlapSeconds": best_overlap,
        "bestPoseOverlapRatio": overlap_ratio,
        "bestPoseChunk": best_chunk,
        "validPoseChunkCount": len(valid_chunks),
    }


def source_cut_candidate_passes_pose_prefilter(candidate: SourceCutCandidate) -> bool:
    # The YOLO pose overlap is only diagnostic here. It is too brittle as a
    # hard source-cut gate because discovery may validate a different chunk
    # than the source window being refined.
    return True


def source_cut_candidate_passes_pre_motion_filters(candidate: SourceCutCandidate) -> bool:
    ignore_reasons = (
        SOURCE_CUT_KINEMATIC_SUBJECT_MOTION_REJECTION_REASONS
        if source_cut_candidate_is_kinematic(candidate)
        else ()
    )
    visual_ok = not source_cut_candidate_visual_rejection_reasons(
        candidate,
        ignore_reasons=ignore_reasons,
    )
    return (
        visual_ok
        and source_cut_candidate_passes_frame_motion(candidate)
        and source_cut_candidate_passes_pose_prefilter(candidate)
    )


def source_cut_candidate_eligible_for_vlm(candidate: SourceCutCandidate) -> bool:
    if not source_cut_candidate_passes_pre_motion_filters(candidate):
        return False
    if source_cut_candidate_is_kinematic(candidate):
        # Cycle proposals are the intended 1-2 VLM cuts. The pose phase
        # completeness gate is calibrated for the duration pyramid and would
        # drop a true cycle as "partial" or "multiple cycles".
        return True
    phase_metrics = candidate.motion_coverage.get("candidateFullRepetitionPhaseCompletenessMetrics")
    if isinstance(phase_metrics, dict):
        completeness_state = source_window_completeness_state(
            {"candidateFullRepetitionPhaseCompletenessMetrics": phase_metrics}
        )
        # Missing/occluded pose evidence remains eligible for visual review.
        # Resolved one-way partials and multi-repetition cuts have better
        # candidates elsewhere in the pyramid and must not be revived by VLM.
        if (
            completeness_state == "partial"
            or phase_metrics_have_resolved_multiple_cycles(phase_metrics)
        ):
            return False
    return True


def source_cut_candidate_passes_motion_coverage(candidate: SourceCutCandidate) -> bool:
    if not candidate.motion_coverage:
        return True
    return bool(candidate.motion_coverage.get("passed", True))


def source_pose_sample_time_seconds(sample: dict[str, Any]) -> float | None:
    return first_float(
        sample.get("timeSeconds"),
        sample.get("timestampSeconds"),
        sample.get("time"),
        sample.get("timestamp"),
    )


def source_pose_prefilter_sample_count(pose_payload: dict[str, Any] | None) -> int:
    if not isinstance(pose_payload, dict):
        return 0
    samples_value = pose_payload.get("dominantPoseSamples")
    if not isinstance(samples_value, list):
        return 0
    return sum(1 for sample in samples_value if isinstance(sample, dict))


def source_pose_prefilter_has_samples(pose_payload: dict[str, Any] | None) -> bool:
    return source_pose_prefilter_sample_count(pose_payload) > 0


def source_pose_keypoint_to_point3(value: Any) -> list[float] | None:
    if not isinstance(value, (list, tuple)) or len(value) < 2:
        return None
    x = parse_optional_float(value[0])
    y = parse_optional_float(value[1])
    if x is None or y is None:
        return None
    return [float(x), float(y), 0.0]


def source_pose_midpoint3(left: list[float] | None, right: list[float] | None) -> list[float] | None:
    if left is not None and right is not None:
        return [
            (left[0] + right[0]) * 0.5,
            (left[1] + right[1]) * 0.5,
            (left[2] + right[2]) * 0.5,
        ]
    return left or right


def source_pose_skeleton_payload_for_window(
    pose_payload: dict[str, Any] | None,
    *,
    candidate_window: DetectionWindow,
    source_offset_seconds: float = 0.0,
) -> dict[str, Any] | None:
    if not isinstance(pose_payload, dict):
        return None
    samples_value = pose_payload.get("dominantPoseSamples")
    if not isinstance(samples_value, list):
        return None
    candidate_start = max(0.0, source_offset_seconds + candidate_window.start_seconds)
    candidate_end = max(candidate_start, source_offset_seconds + candidate_window.end_seconds)
    sample_fps = parse_optional_float(pose_payload.get("sampleFps"))
    boundary_tolerance_seconds = (
        min(0.50, max(0.0, 0.50 / sample_fps))
        if sample_fps is not None and sample_fps > 1e-6
        else 0.25
    )
    frames: list[dict[str, Any]] = []
    joint_names: set[str] = set()
    for sample in samples_value:
        if not isinstance(sample, dict):
            continue
        time_seconds = source_pose_sample_time_seconds(sample)
        if (
            time_seconds is None
            or time_seconds < candidate_start - boundary_tolerance_seconds
            or time_seconds > candidate_end + boundary_tolerance_seconds
        ):
            continue
        keypoints = sample.get("keypoints")
        if not isinstance(keypoints, dict):
            continue
        joints: dict[str, list[float]] = {}
        for name, value in keypoints.items():
            point = source_pose_keypoint_to_point3(value)
            if point is None:
                continue
            joints[str(name)] = point
        pelvis = source_pose_midpoint3(joints.get("left_hip"), joints.get("right_hip"))
        if pelvis is None:
            continue
        joints["pelvis"] = pelvis
        joints["hips"] = pelvis
        shoulder_center = source_pose_midpoint3(joints.get("left_shoulder"), joints.get("right_shoulder"))
        if shoulder_center is not None:
            joints["shoulders"] = shoulder_center
        joint_names.update(joints)
        frames.append(
            {
                "sourceTimeSec": float(time_seconds),
                "joints": joints,
            }
        )
    if not frames:
        return None
    frames.sort(key=lambda frame: float(frame.get("sourceTimeSec", 0.0)))
    return {
        "jointNames": sorted(joint_names),
        "rootJoint": "pelvis",
        "frames": frames,
        "coordinateSpace": pose_payload.get("dominantPoseSampleCoordinateSpace", "normalized_image_xy"),
        "sourcePoseSampleBoundaryToleranceSeconds": boundary_tolerance_seconds,
    }


def source_pose_temporal_foot_contacts(
    frames: list[dict[str, Any]],
    *,
    joint_name: str,
    body_span: float,
) -> list[dict[str, Any]]:
    """Detect stance intervals without treating the whole clip as one contact.

    The exact source gate already requires a stable camera. A rolling source-pixel
    range therefore separates detector jitter from a planted ankle, while the
    ankle's lower-envelope check avoids locking a briefly stationary lifted foot.
    Ratios, rather than source frame numbers, make the evidence portable to the
    independently sampled WHAM/Wear timeline.
    """
    if len(frames) < SOURCE_POSE_CONTACT_MIN_SAMPLE_COUNT or body_span <= 1e-6:
        return []
    points: list[list[float] | None] = []
    for frame in frames:
        joints = frame.get("joints") if isinstance(frame, dict) else None
        point = joints.get(joint_name) if isinstance(joints, dict) else None
        points.append([float(point[0]), float(point[1])] if is_point3(point) else None)
    observed_y = sorted(point[1] for point in points if point is not None)
    if len(observed_y) < SOURCE_POSE_CONTACT_MIN_SAMPLE_COUNT:
        return []
    ground_y = observed_y[round((len(observed_y) - 1) * 0.80)]
    stationary: list[bool] = []
    local_ranges: list[float | None] = []
    for index, point in enumerate(points):
        if point is None:
            stationary.append(False)
            local_ranges.append(None)
            continue
        window = [
            sample
            for sample in points[max(0, index - 2) : min(len(points), index + 3)]
            if sample is not None
        ]
        if len(window) < 3:
            stationary.append(False)
            local_ranges.append(None)
            continue
        x_range = max(sample[0] for sample in window) - min(sample[0] for sample in window)
        y_range = max(sample[1] for sample in window) - min(sample[1] for sample in window)
        local_range_ratio = math.hypot(x_range, y_range) / body_span
        near_ground = point[1] >= ground_y - body_span * SOURCE_POSE_CONTACT_GROUND_HEIGHT_RATIO_THRESHOLD
        stationary.append(
            near_ground
            and local_range_ratio <= SOURCE_POSE_CONTACT_LOCAL_RANGE_RATIO_THRESHOLD
        )
        local_ranges.append(local_range_ratio)

    # Bridge one missed detector sample inside an otherwise stable stance.
    for index in range(1, len(stationary) - 1):
        if not stationary[index] and stationary[index - 1] and stationary[index + 1] and points[index] is not None:
            stationary[index] = True

    intervals: list[dict[str, Any]] = []
    start: int | None = None
    for index in range(len(stationary) + 1):
        active = index < len(stationary) and stationary[index]
        if active and start is None:
            start = index
        if active or start is None:
            continue
        end = index - 1
        if end - start + 1 >= SOURCE_POSE_CONTACT_MIN_SAMPLE_COUNT:
            interval_ranges = [
                value for value in local_ranges[start : end + 1] if value is not None
            ]
            median_range = statistics.median(interval_ranges) if interval_ranges else None
            range_confidence = (
                clamp_unit(1.0 - median_range / SOURCE_POSE_CONTACT_LOCAL_RANGE_RATIO_THRESHOLD)
                if median_range is not None
                else 0.0
            )
            coverage_confidence = min(1.0, (end - start + 1) / 8.0)
            intervals.append(
                {
                    "jointName": joint_name,
                    "supportKind": "foot",
                    "sourceStartSample": start,
                    "sourceEndSample": end,
                    "startRatio": start / max(1, len(frames) - 1),
                    "endRatio": end / max(1, len(frames) - 1),
                    "confidence": 0.55 + 0.45 * range_confidence * coverage_confidence,
                    "sampleCount": end - start + 1,
                    "medianLocalRangeRatio": median_range,
                }
            )
        start = None
    return intervals


def source_pose_stationary_foot_support_evidence(
    source_pose_payload: dict[str, Any],
) -> dict[str, Any]:
    """Identify continuously stationary feet from the exact source pixels.

    WHAM drift must not decide whether a support was stationary.  We use robust
    chunk centers from the source 2D pose so detector jitter is tolerated while
    genuine travelling or distal-leg motion remains observable.
    """
    frames = source_pose_payload.get("frames")
    if not isinstance(frames, list) or len(frames) < DETERMINISTIC_SUPPORT_MIN_SAMPLE_COUNT:
        return {
            "source": "exact_selected_source_video_yolo_pose",
            "reason": "insufficient_source_pose_frames",
            "feet": {},
        }
    body_spans: list[float] = []
    for frame in frames:
        joints = frame.get("joints") if isinstance(frame, dict) else None
        if not isinstance(joints, dict):
            continue
        points = [value for value in joints.values() if is_point3(value)]
        if points:
            y_values = [float(point[1]) for point in points]
            body_spans.append(max(y_values) - min(y_values))
    positive_body_spans = [value for value in body_spans if value > 1e-6]
    body_span = statistics.median(positive_body_spans) if positive_body_spans else 0.0
    if body_span <= 1e-6:
        return {
            "source": "exact_selected_source_video_yolo_pose",
            "reason": "invalid_source_pose_body_span",
            "feet": {},
        }

    foot_evidence: dict[str, Any] = {}
    temporal_contacts: list[dict[str, Any]] = []
    for side in ("left", "right"):
        joint_name = f"{side}_ankle"
        points = []
        for frame in frames:
            joints = frame.get("joints") if isinstance(frame, dict) else None
            point = joints.get(joint_name) if isinstance(joints, dict) else None
            if is_point3(point):
                points.append([float(point[0]), float(point[1])])
        coverage_ratio = len(points) / len(frames)
        chunk_size = max(3, math.ceil(len(points) / 5)) if points else 3
        chunk_centers = [
            [
                statistics.median(point[0] for point in chunk),
                statistics.median(point[1] for point in chunk),
            ]
            for start in range(0, len(points), chunk_size)
            if len(chunk := points[start : start + chunk_size]) >= 3
        ]
        if len(chunk_centers) >= 2:
            x_range = max(point[0] for point in chunk_centers) - min(
                point[0] for point in chunk_centers
            )
            y_range = max(point[1] for point in chunk_centers) - min(
                point[1] for point in chunk_centers
            )
            chunk_center_range_ratio = math.hypot(x_range, y_range) / body_span
            endpoint_displacement_ratio = math.dist(
                chunk_centers[0], chunk_centers[-1]
            ) / body_span
        else:
            chunk_center_range_ratio = None
            endpoint_displacement_ratio = None
        contact_intervals = source_pose_temporal_foot_contacts(
            frames,
            joint_name=joint_name,
            body_span=body_span,
        )
        temporal_contacts.extend(contact_intervals)
        temporal_coverage_ratio = sum(
            int(interval["sampleCount"]) for interval in contact_intervals
        ) / len(frames)
        continuous_support = bool(
            coverage_ratio >= 0.60
            and chunk_center_range_ratio is not None
            and endpoint_displacement_ratio is not None
            and chunk_center_range_ratio
            <= SOURCE_POSE_SUPPORT_STATIONARY_CHUNK_RANGE_RATIO_THRESHOLD
            and endpoint_displacement_ratio
            <= SOURCE_POSE_SUPPORT_STATIONARY_ENDPOINT_RATIO_THRESHOLD
            and temporal_coverage_ratio >= 0.70
        )
        foot_evidence[side] = {
            "jointName": joint_name,
            "continuousSupport": continuous_support,
            "sampleCount": len(points),
            "coverageRatio": coverage_ratio,
            "chunkCenterCount": len(chunk_centers),
            "chunkCenterRangeRatio": chunk_center_range_ratio,
            "endpointDisplacementRatio": endpoint_displacement_ratio,
            "temporalContactCoverageRatio": temporal_coverage_ratio,
            "contactIntervals": contact_intervals,
        }
    return {
        "source": "exact_selected_source_video_yolo_pose",
        "reason": "source_pose_stationary_support_measurement",
        "bodySpan": body_span,
        "chunkCenterRangeRatioThreshold": SOURCE_POSE_SUPPORT_STATIONARY_CHUNK_RANGE_RATIO_THRESHOLD,
        "endpointDisplacementRatioThreshold": SOURCE_POSE_SUPPORT_STATIONARY_ENDPOINT_RATIO_THRESHOLD,
        "localContactRangeRatioThreshold": SOURCE_POSE_CONTACT_LOCAL_RANGE_RATIO_THRESHOLD,
        "contactGroundHeightRatioThreshold": SOURCE_POSE_CONTACT_GROUND_HEIGHT_RATIO_THRESHOLD,
        "contacts": temporal_contacts,
        "feet": foot_evidence,
    }


def source_pose_dominant_root_relative_axis_track(
    frames: list[dict[str, Any]],
    *,
    joint_names: list[str],
    root_joint: str,
    min_frames: int,
    preferred_joint_predicate: Callable[[str], bool] | None = None,
    allow_all_joint_fallback: bool = True,
) -> dict[str, Any] | None:
    excluded = {root_joint, "pelvis", "hips", "root"}
    candidate_joints = [name for name in joint_names if name not in excluded]

    def best_for(joints_to_consider: list[str], *, selection: str) -> dict[str, Any] | None:
        best: dict[str, Any] | None = None
        for joint_name in joints_to_consider:
            points: list[list[float]] = []
            for frame in frames:
                joints = frame.get("joints")
                if not isinstance(joints, dict):
                    continue
                point = joints.get(joint_name)
                root = joints.get(root_joint)
                if is_point3(point) and is_point3(root):
                    point3 = point3_to_float_list(point)
                    root3 = point3_to_float_list(root)
                    points.append([point3[axis] - root3[axis] for axis in range(3)])
            if len(points) < max(min_frames, int(len(frames) * 0.60)):
                continue
            for axis in range(3):
                values = [point[axis] for point in points]
                value_range = max(values) - min(values)
                if best is None or value_range > float(best["range"]):
                    best = {
                        "joint": joint_name,
                        "axis": axis,
                        "range": value_range,
                        "values": values,
                        "selection": selection,
                    }
        return best

    if preferred_joint_predicate is not None:
        preferred_joints = [name for name in candidate_joints if preferred_joint_predicate(name)]
        preferred_best = best_for(preferred_joints, selection="preferred")
        if preferred_best is not None:
            return preferred_best
        if not allow_all_joint_fallback:
            return None
    return best_for(candidate_joints, selection="fallback_all_joints")


def full_repetition_phase_completeness_metrics_from_source_pose_payload(
    payload: dict[str, Any],
    *,
    exercise_name: str,
    ranking_payload: dict[str, Any] | None = None,
    chunk_estimate: Any | None = None,
) -> dict[str, Any]:
    complexity = movement_complexity_for_validation(
        exercise_name,
        ranking_payload=ranking_payload,
        chunk_estimate=chunk_estimate,
    ).strip().lower()
    motion_contract = target_motion_contract_from_ranking_payload(ranking_payload)
    target_motion_profile = target_motion_profile_for_exercise(
        exercise_name,
        contract=motion_contract,
    )
    observable_spec = observable_motion_spec_for_contract(motion_contract)
    requires_return = observable_motion_spec_requires_return(motion_contract)
    if motion_contract is not None and not requires_return:
        return empty_full_repetition_phase_completeness_metrics(
            required=False,
            reason="completion_mode_does_not_require_repetition_phase_return",
            movement_complexity=complexity,
        )
    required = (
        complexity in {"simple", "compound"}
        or target_motion_profile is not None
        or requires_return
    )
    if not required:
        return empty_full_repetition_phase_completeness_metrics(
            required=False,
            reason="movement_complexity_does_not_require_repetition_phase_return",
            movement_complexity=complexity,
        )
    frames_value = payload.get("frames")
    joint_names_value = payload.get("jointNames")
    if not isinstance(frames_value, list) or not isinstance(joint_names_value, list):
        return empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="missing_source_pose_frames_or_joint_names",
            movement_complexity=complexity,
        )
    frames = [frame for frame in frames_value if isinstance(frame, dict)]
    min_frames = SOURCE_CUT_POSE_PHASE_COMPLETENESS_MIN_FRAMES
    if len(frames) < min_frames:
        return empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="insufficient_source_pose_samples",
            frame_count=len(frames),
            movement_complexity=complexity,
        )
    joint_names = [str(name) for name in joint_names_value]
    root_joint = str(payload.get("rootJoint") or "")
    if root_joint not in joint_names:
        return empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="missing_source_pose_root_joint",
            frame_count=len(frames),
            movement_complexity=complexity,
        )
    body_height = body_height_from_payload_frames(frames)
    if body_height <= 1e-6:
        return empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="invalid_source_pose_body_height",
            frame_count=len(frames),
            movement_complexity=complexity,
        )
    lower_body_target = exercise_requires_lower_body_motion(exercise_name, contract=motion_contract)
    distal_lower_body_target = (
        isinstance(target_motion_profile, dict)
        and target_motion_profile.get("profile") == DISTAL_LEG_VERTICAL_RAISE_PROFILE_KEY
    )
    primary_regions = {
        str(region).strip().lower()
        for region in (observable_spec or {}).get("primaryMovingRegions", [])
        if str(region).strip()
    }
    preferred_joint_region, preferred_joint_predicate, upper_body_target = phase_joint_preference(
        primary_regions=primary_regions,
        lower_body_target=lower_body_target,
        distal_lower_body_target=distal_lower_body_target,
        movement_complexity=complexity,
    )
    observable_motion_metrics = (
        materialized_observable_motion_spec_metrics(
            frames,
            spec=observable_spec,
            body_span=body_height,
        )
        if observable_spec is not None
        else None
    )
    dominant = source_pose_dominant_root_relative_axis_track(
        frames,
        joint_names=joint_names,
        root_joint=root_joint,
        min_frames=min_frames,
        preferred_joint_predicate=preferred_joint_predicate,
        allow_all_joint_fallback=preferred_joint_predicate is None,
    )
    observable_dominant = (
        dominant_observable_motion_phase_track(
            frames,
            spec=observable_spec,
            body_span=body_height,
        )
        if observable_spec is not None
        else None
    )
    angle_dominant = dominant_joint_angle_phase_track(
        frames,
        upper_body=upper_body_target,
        lower_body=lower_body_target,
    )
    if observable_dominant is not None and (
        dominant is None
        or (
            phase_track_has_return(observable_dominant["values"])
            and not phase_track_has_return(dominant["values"])
        )
    ):
        dominant = observable_dominant
    if angle_dominant is not None and (
        dominant is None
        or (
            phase_track_has_return(angle_dominant["values"])
            and not phase_track_has_return(dominant["values"])
        )
    ):
        dominant = angle_dominant
    if dominant is None:
        return empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="missing_source_pose_dominant_motion_track",
            frame_count=len(frames),
            movement_complexity=complexity,
        )
    values = dominant["values"]
    if not isinstance(values, list) or len(values) < min_frames:
        return empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="insufficient_source_pose_dominant_motion_samples",
            frame_count=len(frames),
            movement_complexity=complexity,
        )
    raw_motion_range = float(dominant["range"])
    signal_evidence = phase_track_signal_evidence(values)
    values = signal_evidence["smoothedValues"]
    motion_range = raw_motion_range
    phase_motion_range = max(values) - min(values)
    range_normalization = parse_optional_float(dominant.get("rangeNormalization")) or body_height
    motion_range_ratio = motion_range / range_normalization
    if bool(signal_evidence["resolved"]):
        probe_complete_cycle, probe_phase_sequence = has_one_or_more_major_repetition_cycles(values)
        if (
            probe_complete_cycle
            and len(probe_phase_sequence) != 3
            and motion_range_ratio < FULL_REPETITION_PHASE_COMPLETENESS_MIN_RANGE_RATIO
        ):
            signal_evidence = {
                **signal_evidence,
                "resolved": False,
                "reason": "phase_excursion_not_resolved_from_clip_noise",
            }
    if not bool(signal_evidence["resolved"]):
        return {
            "required": True,
            "passed": False,
            "reason": "source_pose_dominant_motion_not_resolved_from_clip_noise",
            "movementComplexity": complexity,
            "targetMotionProfile": target_motion_profile.get("profile") if target_motion_profile is not None else None,
            "observableMotionSpec": observable_spec,
            "frameCount": len(frames),
            "sampleCount": len(values),
            "bodyHeight": body_height,
            "dominantJoint": dominant["joint"],
            "dominantJointSelection": dominant.get("selection"),
            "preferredJointRegion": preferred_joint_region,
            "dominantAxis": dominant["axis"],
            "dominantMotionRange": motion_range,
            "dominantMotionRawRange": raw_motion_range,
            "dominantMotionRangeRatio": motion_range_ratio,
            "motionResolutionMethod": "clip_noise_separation",
            "observableMotionMetrics": observable_motion_metrics,
            "phaseSignalEvidence": {key: value for key, value in signal_evidence.items() if key != "smoothedValues"},
            "endpointPhaseDeltaRatio": abs(float(values[-1]) - float(values[0])) / max(phase_motion_range, 1e-8),
            "maxEndpointPhaseDeltaRatio": FULL_REPETITION_PHASE_COMPLETENESS_MAX_ENDPOINT_DELTA_RATIO,
        }

    min_value = min(values)
    max_value = max(values)
    min_index = values.index(min_value)
    max_index = values.index(max_value)
    sample_count = len(values)
    edge_margin = max(1, int(round((sample_count - 1) * FULL_REPETITION_PHASE_COMPLETENESS_EDGE_MARGIN_RATIO)))
    interior_min = edge_margin <= min_index <= (sample_count - 1 - edge_margin)
    interior_max = edge_margin <= max_index <= (sample_count - 1 - edge_margin)
    endpoint_delta_ratio = abs(float(values[-1]) - float(values[0])) / max(phase_motion_range, 1e-8)
    has_return_phase = endpoint_delta_ratio <= FULL_REPETITION_PHASE_COMPLETENESS_MAX_ENDPOINT_DELTA_RATIO
    has_interior_extreme = interior_min or interior_max
    finish_at_extreme = min_index >= sample_count - 1 - edge_margin or max_index >= sample_count - 1 - edge_margin
    requires_return = observable_motion_spec_requires_return(motion_contract)
    has_complete_cycle, major_phase_sequence = has_one_or_more_major_repetition_cycles(values)
    has_single_cycle = (
        len(major_phase_sequence) == 3
        and has_complete_cycle
    )
    passed = has_return_phase and has_interior_extreme and has_single_cycle
    reason = (
        "source_pose_full_repetition_phase_return_detected"
        if passed
        else "source_pose_multiple_or_unclean_repetition_cycles"
        if has_return_phase and has_interior_extreme and has_complete_cycle
        else "source_pose_no_complete_repetition_cycle"
        if has_return_phase and has_interior_extreme
        else "source_pose_one_way_partial_repetition_phase"
    )
    return {
        "required": True,
        "passed": passed,
        "reason": reason,
        "movementComplexity": complexity,
        "targetMotionProfile": target_motion_profile.get("profile") if target_motion_profile is not None else None,
        "observableMotionSpec": observable_spec,
        "frameCount": len(frames),
        "sampleCount": sample_count,
        "bodyHeight": body_height,
        "dominantJoint": dominant["joint"],
        "dominantJointSelection": dominant.get("selection"),
        "preferredJointRegion": preferred_joint_region,
        "dominantAxis": dominant["axis"],
        "dominantMotionRange": motion_range,
        "dominantMotionRawRange": raw_motion_range,
        "phaseMotionRange": phase_motion_range,
        "dominantMotionRangeRatio": motion_range_ratio,
        "motionResolutionMethod": "clip_noise_separation",
        "observableMotionMetrics": observable_motion_metrics,
        "phaseSignalEvidence": {key: value for key, value in signal_evidence.items() if key != "smoothedValues"},
        "startValue": float(values[0]),
        "endValue": float(values[-1]),
        "minValue": float(min_value),
        "maxValue": float(max_value),
        "minFrameIndex": min_index,
        "maxFrameIndex": max_index,
        "edgeMarginFrameCount": edge_margin,
        "endpointPhaseDeltaRatio": endpoint_delta_ratio,
        "maxEndpointPhaseDeltaRatio": FULL_REPETITION_PHASE_COMPLETENESS_MAX_ENDPOINT_DELTA_RATIO,
        "hasReturnPhase": has_return_phase,
        "hasInteriorExtreme": has_interior_extreme,
        "hasSingleMajorCycle": has_single_cycle,
        "hasCompleteMajorCycle": has_complete_cycle,
        "majorPhaseSequence": major_phase_sequence,
        "finishAtExtreme": finish_at_extreme,
        "requiresReturn": requires_return,
        "interiorMin": interior_min,
        "interiorMax": interior_max,
    }


def source_cut_candidate_motion_coverage_metrics(
    *,
    candidate_window: DetectionWindow,
    pose_payload: dict[str, Any],
    exercise_name: str,
    chunk_estimate: Any,
    exercise_motion_contract: dict[str, Any] | None = None,
    source_offset_seconds: float = 0.0,
) -> dict[str, Any]:
    source_pose_payload = source_pose_skeleton_payload_for_window(
        pose_payload,
        candidate_window=candidate_window,
        source_offset_seconds=source_offset_seconds,
    )
    if source_pose_payload is None:
        phase_metrics = empty_full_repetition_phase_completeness_metrics(
            required=True,
            reason="source_cut_pose_samples_unavailable",
        )
        return {
            "passed": False,
            "sourcePoseSampleCount": 0,
            "rejectionReasons": ["source_cut_insufficient_repetition_phase_evidence"],
            "skippedReasons": ["source_cut_pose_samples_unavailable"],
            "candidateFullRepetitionPhaseCompletenessMetrics": phase_metrics,
        }
    phase_metrics = full_repetition_phase_completeness_metrics_from_source_pose_payload(
        source_pose_payload,
        exercise_name=exercise_name,
        ranking_payload={"exerciseMotionContract": exercise_motion_contract},
        chunk_estimate=chunk_estimate,
    )
    phase_required = bool(phase_metrics.get("required"))
    phase_reason = str(phase_metrics.get("reason") or "")
    phase_evidence_missing = "insufficient" in phase_reason or "unavailable" in phase_reason
    phase_passed = bool(phase_metrics.get("passed", True)) and not phase_evidence_missing
    rejection_reasons: list[str] = []
    if phase_required and not phase_passed:
        rejection_reasons.append(
            "source_cut_insufficient_repetition_phase_evidence"
            if phase_evidence_missing
            else "source_cut_incomplete_repetition_phase"
        )
    target_motion_observability = materialized_target_motion_observability_metrics_from_payload(
        source_pose_payload,
        exercise_name=exercise_name,
        ranking_payload={"exerciseMotionContract": exercise_motion_contract},
    )
    active_travel_locomotion = active_travel_locomotion_metrics_from_source_pose_payload(
        source_pose_payload,
        required=contract_accepts_ongoing_action_interval(exercise_motion_contract),
    )
    if bool(active_travel_locomotion.get("required")) and not bool(active_travel_locomotion.get("passed")):
        rejection_reasons.append("source_cut_missing_active_travel_locomotion")
    return {
        "passed": not rejection_reasons,
        "sourcePoseSampleCount": len(source_pose_payload.get("frames") or []),
        "rejectionReasons": rejection_reasons,
        "skippedReasons": [],
        "candidateFullRepetitionPhaseCompletenessMetrics": phase_metrics,
        "targetMotionObservability": target_motion_observability,
        "activeTravelLocomotion": active_travel_locomotion,
    }


def source_window_completeness_state(metrics: dict[str, Any]) -> str:
    phase = metrics.get("candidateFullRepetitionPhaseCompletenessMetrics")
    if not isinstance(phase, dict):
        return "uncertain"
    if not bool(phase.get("required")):
        return "complete"
    if bool(phase.get("passed")):
        return "complete"
    reason = str(phase.get("reason") or "").lower()
    if "unavailable" in reason or "insufficient" in reason:
        return "uncertain"
    if "one_way" in reason or "partial" in reason or bool(phase.get("finishAtExtreme")):
        return "partial"
    return "invalid"


def movement_cut_target_motion_gate_metrics(
    *,
    exercise_name: str,
    candidate_metrics: dict[str, Any],
    candidate_phase_metrics: dict[str, Any] | None,
    chunk_estimate: Any | None = None,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> dict[str, Any]:
    complexity = movement_complexity_for_validation(
        exercise_name,
        chunk_estimate=chunk_estimate,
    ).strip().lower()
    target_motion_profile = target_motion_profile_for_exercise(
        exercise_name,
        contract=exercise_motion_contract,
    )
    target_profile_key = (
        str(target_motion_profile.get("profile"))
        if isinstance(target_motion_profile, dict) and target_motion_profile.get("profile")
        else None
    )
    observable_spec = observable_motion_spec_for_contract(exercise_motion_contract)
    required = (
        complexity in {"simple", "compound"}
        or target_motion_profile is not None
        or observable_spec is not None
    )
    lower_body_target = exercise_requires_lower_body_motion(
        exercise_name,
        contract=exercise_motion_contract,
    )
    root_vertical_range = parse_optional_float(candidate_metrics.get("rootVerticalRangeRatio"))
    lower_body_proximal_range = parse_optional_float(candidate_metrics.get("lowerBodyProximalRootRelativeRangeRatio"))
    lower_body_distal_range = parse_optional_float(candidate_metrics.get("lowerBodyDistalRootRelativeRangeRatio"))
    upper_body_range = parse_optional_float(candidate_metrics.get("upperBodyRootRelativeRangeRatio"))
    distal_allowed = target_profile_key == "distal_leg_vertical_raise"
    if distal_allowed:
        target_region = "lower_body_distal"
        target_range = lower_body_distal_range
    elif lower_body_target:
        target_region = "lower_body"
        distal_target_range = (lower_body_distal_range or 0.0) if distal_allowed else 0.0
        target_range = max(
            root_vertical_range or 0.0,
            lower_body_proximal_range or 0.0,
            distal_target_range,
        )
    else:
        target_region = "upper_body"
        target_range = upper_body_range

    dominant_joint = None
    if candidate_phase_metrics is not None:
        dominant_joint_value = candidate_phase_metrics.get("dominantJoint")
        dominant_joint = str(dominant_joint_value) if dominant_joint_value is not None else None
    distal_lower_body_dominant = (
        dominant_joint is not None
        and is_lower_body_distal_joint(dominant_joint)
        and not distal_allowed
    )
    target_to_distal_ratio = None
    if lower_body_distal_range is not None and lower_body_distal_range > 1e-6 and target_range is not None:
        target_to_distal_ratio = target_range / lower_body_distal_range
    distal_range_dominates_target = (
        lower_body_distal_range is not None
        and lower_body_distal_range >= MOVEMENT_CUT_MIN_TARGET_REGION_MOTION_RANGE_RATIO
        and target_range is not None
        and (
            lower_body_distal_range >= target_range * MOVEMENT_CUT_DISTAL_DOMINANCE_MIN_RATIO
            or target_to_distal_ratio is not None
            and target_to_distal_ratio <= MOVEMENT_CUT_DISTAL_DOMINANCE_MAX_TARGET_TO_DISTAL_RATIO
        )
    )
    distal_dominance_gate_required = (
        not lower_body_target
        or target_range is None
        or target_range < MOVEMENT_CUT_MIN_TARGET_REGION_MOTION_RANGE_RATIO
    )
    distal_dominates_target = (
        (distal_lower_body_dominant or distal_range_dominates_target)
        and distal_dominance_gate_required
        and distal_range_dominates_target
    )

    rejection_reasons: list[str] = []
    skipped_reasons: list[str] = []
    if not required:
        skipped_reasons.append("movement_cut_target_motion_gate_not_required_for_complexity")
    elif target_range is None:
        skipped_reasons.append("movement_cut_target_motion_range_missing")
    else:
        if target_range < MOVEMENT_CUT_MIN_TARGET_REGION_MOTION_RANGE_RATIO:
            rejection_reasons.append("movement_cut_low_target_region_motion")
        if distal_dominates_target:
            rejection_reasons.append("movement_cut_distal_setup_motion_dominates")

    return {
        "required": required,
        "passed": not rejection_reasons,
        "rejectionReasons": rejection_reasons,
        "skippedReasons": skipped_reasons,
        "exerciseName": exercise_name,
        "movementComplexity": complexity,
        "targetMotionProfile": target_profile_key,
        "observableMotionSpec": observable_spec,
        "targetMotionRegion": target_region,
        "targetMotionRangeRatio": target_range,
        "minTargetMotionRangeRatio": MOVEMENT_CUT_MIN_TARGET_REGION_MOTION_RANGE_RATIO,
        "rootVerticalRangeRatio": root_vertical_range,
        "lowerBodyProximalRootRelativeRangeRatio": lower_body_proximal_range,
        "lowerBodyDistalRootRelativeRangeRatio": lower_body_distal_range,
        "upperBodyRootRelativeRangeRatio": upper_body_range,
        "dominantPhaseJoint": dominant_joint,
        "distalLowerBodyDominant": distal_lower_body_dominant,
        "distalRangeDominatesTarget": distal_range_dominates_target,
        "distalLowerBodyTargetAllowed": distal_allowed,
        "distalDominanceGateRequired": distal_dominance_gate_required,
        "targetToDistalMotionRatio": target_to_distal_ratio,
        "distalDominanceMinRatio": MOVEMENT_CUT_DISTAL_DOMINANCE_MIN_RATIO,
        "maxTargetToDistalMotionRatio": MOVEMENT_CUT_DISTAL_DOMINANCE_MAX_TARGET_TO_DISTAL_RATIO,
    }


def movement_cut_candidate_motion_coverage_metrics(
    *,
    item: ReviewItem,
    parent_window: DetectionWindow,
    candidate_window: DetectionWindow,
    chunk_estimate: Any | None = None,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not item.skeleton_path.exists():
        return {
            "passed": True,
            "skippedReasons": ["movement_cut_motion_coverage_skeleton_missing"],
        }
    try:
        parent_metrics = compute_source_capture_motion_strength_metrics(
            item.skeleton_path,
            start_seconds=parent_window.start_seconds,
            end_seconds=parent_window.end_seconds,
        )
        candidate_metrics = compute_source_capture_motion_strength_metrics(
            item.skeleton_path,
            start_seconds=candidate_window.start_seconds,
            end_seconds=candidate_window.end_seconds,
        )
    except Exception:
        return {
            "passed": True,
            "skippedReasons": ["movement_cut_motion_coverage_metrics_unavailable"],
        }

    parent_range = parse_optional_float(parent_metrics.get("primaryMotionRangeRatio"))
    candidate_range = parse_optional_float(candidate_metrics.get("primaryMotionRangeRatio"))
    rejection_reasons: list[str] = []
    skipped_reasons: list[str] = []
    coverage_ratio: float | None = None
    if parent_range is None or candidate_range is None:
        skipped_reasons.append("movement_cut_motion_coverage_range_missing")
    elif parent_range <= 1e-6:
        skipped_reasons.append("movement_cut_parent_motion_range_zero")
    else:
        coverage_ratio = clamp_unit(candidate_range / parent_range)
        if (
            parent_range >= LOOP_SOURCE_STRONG_MOTION_RATIO_MIN
            and coverage_ratio < MOVEMENT_CUT_MIN_SOURCE_MOTION_COVERAGE_RATIO
        ):
            rejection_reasons.append("movement_cut_low_source_motion_coverage")

    parent_phase_metrics: dict[str, Any] | None = None
    candidate_phase_metrics: dict[str, Any] | None = None
    try:
        parent_phase_metrics = full_repetition_phase_completeness_metrics_from_skeleton_path(
            item.skeleton_path,
            exercise_name=item.exercise_name,
            ranking_payload={"exerciseMotionContract": exercise_motion_contract},
            chunk_estimate=chunk_estimate,
            start_seconds=parent_window.start_seconds,
            end_seconds=parent_window.end_seconds,
            fallback_to_full=False,
        )
        candidate_phase_metrics = full_repetition_phase_completeness_metrics_from_skeleton_path(
            item.skeleton_path,
            exercise_name=item.exercise_name,
            ranking_payload={"exerciseMotionContract": exercise_motion_contract},
            chunk_estimate=chunk_estimate,
            start_seconds=candidate_window.start_seconds,
            end_seconds=candidate_window.end_seconds,
            fallback_to_full=False,
        )
    except Exception:
        skipped_reasons.append("movement_cut_phase_completeness_metrics_unavailable")
    if (
        candidate_phase_metrics is not None
        and bool(candidate_phase_metrics.get("required"))
        and not bool(candidate_phase_metrics.get("passed", True))
    ):
        rejection_reasons.append("movement_cut_incomplete_repetition_phase")
        if observable_motion_spec_requires_return(exercise_motion_contract):
            rejection_reasons.append("movement_cut_required_return_phase_missing")
    candidate_has_complete_repetition_phase = (
        candidate_phase_metrics is not None
        and bool(candidate_phase_metrics.get("required"))
        and bool(candidate_phase_metrics.get("passed"))
        and str(candidate_phase_metrics.get("reason") or "")
        in {
            "full_repetition_phase_return_detected",
            "source_pose_full_repetition_phase_return_detected",
        }
    )
    coverage_satisfied_by_complete_phase = False
    if (
        candidate_has_complete_repetition_phase
        and "movement_cut_low_source_motion_coverage" in rejection_reasons
    ):
        rejection_reasons = [
            reason
            for reason in rejection_reasons
            if reason != "movement_cut_low_source_motion_coverage"
        ]
        coverage_satisfied_by_complete_phase = True

    target_motion_gate = movement_cut_target_motion_gate_metrics(
        exercise_name=item.exercise_name,
        candidate_metrics=candidate_metrics,
        candidate_phase_metrics=candidate_phase_metrics,
        chunk_estimate=chunk_estimate,
        exercise_motion_contract=exercise_motion_contract,
    )
    rejection_reasons.extend(
        str(reason)
        for reason in target_motion_gate.get("rejectionReasons", [])
    )
    skipped_reasons.extend(
        str(reason)
        for reason in target_motion_gate.get("skippedReasons", [])
    )

    payload = {
        "passed": not rejection_reasons,
        "rejectionReasons": rejection_reasons,
        "skippedReasons": skipped_reasons,
        "sourceMotionCoverageRatio": coverage_ratio,
        "minSourceMotionCoverageRatio": MOVEMENT_CUT_MIN_SOURCE_MOTION_COVERAGE_RATIO,
        "strongParentMotionRangeRatioMin": LOOP_SOURCE_STRONG_MOTION_RATIO_MIN,
        "parentPrimaryMotionRangeRatio": parent_range,
        "candidatePrimaryMotionRangeRatio": candidate_range,
        "parentMotionStrengthScore": parse_optional_float(parent_metrics.get("motionStrengthScore")),
        "candidateMotionStrengthScore": parse_optional_float(candidate_metrics.get("motionStrengthScore")),
        "parentMotionStrengthMetrics": parent_metrics,
        "candidateMotionStrengthMetrics": candidate_metrics,
        "motionCoverageSatisfiedByCompleteRepetitionPhase": coverage_satisfied_by_complete_phase,
        "targetMotionGate": target_motion_gate,
    }
    if parent_phase_metrics is not None:
        payload["parentFullRepetitionPhaseCompletenessMetrics"] = parent_phase_metrics
    if candidate_phase_metrics is not None:
        payload["candidateFullRepetitionPhaseCompletenessMetrics"] = candidate_phase_metrics
    return payload


def movement_cut_candidate_passes_motion_coverage(candidate: SourceCutCandidate) -> bool:
    if not candidate.motion_coverage:
        return True
    return bool(candidate.motion_coverage.get("passed", True))


def movement_cut_candidate_hard_motion_rejection_reasons(candidate: SourceCutCandidate) -> list[str]:
    rejection_reasons = candidate.motion_coverage.get("rejectionReasons") if candidate.motion_coverage else None
    if not isinstance(rejection_reasons, list):
        return []
    return [
        str(reason)
        for reason in rejection_reasons
        if str(reason) in MOVEMENT_CUT_HARD_MOTION_REJECTION_REASONS
    ]


def movement_cut_candidate_has_hard_motion_rejection(candidate: SourceCutCandidate) -> bool:
    return bool(movement_cut_candidate_hard_motion_rejection_reasons(candidate))


