def extract_json_object_with_trailing_repair(raw: str) -> dict[str, Any] | None:
    try:
        payload = extract_json_object(raw)
    except Exception:
        payload = None
    if isinstance(payload, dict):
        return payload
    text = str(raw or "").strip()
    start = text.find("{")
    if start < 0:
        return None
    candidate = text[start:].strip()
    repaired_candidate = repair_incomplete_json_object(candidate)
    if repaired_candidate is None:
        return None
    repaired_variants = [
        repaired_candidate,
        re.sub(r",(\s*[}\]])", r"\1", repaired_candidate),
    ]
    decoder = json.JSONDecoder()
    for repaired_text in dedupe_text(repaired_variants):
        try:
            repaired, _end = decoder.raw_decode(repaired_text)
        except json.JSONDecodeError:
            continue
        if isinstance(repaired, dict):
            return repaired
    return None


def repair_incomplete_json_object(text: str) -> str | None:
    stack: list[str] = []
    in_string = False
    escape = False
    for char in text:
        if in_string:
            if escape:
                escape = False
            elif char == "\\":
                escape = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "{":
            stack.append("}")
        elif char == "[":
            stack.append("]")
        elif char in ("}", "]"):
            if not stack or stack[-1] != char:
                return None
            stack.pop()
    repaired = text
    if in_string:
        if escape and repaired.endswith("\\"):
            repaired = repaired[:-1]
        repaired += '"'
    return repaired + "".join(reversed(stack))


def source_cut_candidate_duration(candidate: SourceCutCandidate) -> float:
    return max(0.0, candidate.window.end_seconds - candidate.window.start_seconds)


def cut_candidate_meets_duration_floor(
    candidate: SourceCutCandidate,
    min_duration_seconds: float | None,
) -> bool:
    if min_duration_seconds is None or min_duration_seconds <= 0.0:
        return True
    return source_cut_candidate_duration(candidate) + 1e-6 >= min_duration_seconds


def cut_candidate_contact_sheet_frame_count(requested_frame_count: int) -> int:
    return min(
        CUT_CANDIDATE_MAX_CONTACT_SHEET_FRAMES,
        max(CUT_CANDIDATE_MIN_CONTACT_SHEET_FRAMES, int(requested_frame_count)),
    )


def source_cut_scorecard_thresholds(*, has_contract: bool) -> dict[str, float]:
    return {
        "confidence": (
            SOURCE_CUT_CLASSIFIER_MIN_CONFIDENCE_WITH_CONTRACT
            if has_contract
            else SOURCE_CUT_CLASSIFIER_MIN_CONFIDENCE_WITHOUT_CONTRACT
        ),
    }


