def parse_source_cut_scorecard_score(value: Any) -> float | None:
    score = parse_optional_float(value)
    if score is None or not math.isfinite(score) or not 0.0 <= score <= 1.0:
        return None
    return score


def source_cut_scorecard_payload_has_valid_confidence(payload: dict[str, Any]) -> bool:
    candidates = source_cut_scorecard_candidate_payloads(payload)
    if not candidates:
        return False
    classifier_candidates = [
        candidate
        for candidate in candidates
        if any(key in candidate for key in ("approved", "accepted", "valid", "pass"))
    ]
    return all(
        parse_source_cut_scorecard_score(candidate.get("confidence")) is not None
        for candidate in classifier_candidates
    )


def source_cut_scorecard_candidate_payloads(payload: dict[str, Any]) -> list[dict[str, Any]]:
    candidates = payload.get("candidates")
    if not isinstance(candidates, list):
        return []
    return [item for item in candidates if isinstance(item, dict)]


def normalize_source_cut_scorecard_reject_tags(value: Any) -> tuple[list[str], list[str]]:
    raw_items: list[Any]
    if value is None:
        raw_items = []
    elif isinstance(value, str):
        raw_items = re.split(r"[,;\n]+", value)
    elif isinstance(value, Iterable) and not isinstance(value, (dict, bytes, bytearray)):
        raw_items = list(value)
    else:
        raw_items = [value]

    tags: list[str] = []
    invalid_tags: list[str] = []
    for item in raw_items:
        raw_tag = slugify(str(item or "")).replace("-", "_")
        tag = SOURCE_CUT_SCORECARD_REJECT_TAG_ALIASES.get(raw_tag, raw_tag)
        if not tag:
            continue
        if tag not in SOURCE_CUT_SCORECARD_ALLOWED_REJECT_TAGS:
            invalid_tags.append(raw_tag)
            tag = "invalid_reject_tag"
        if tag not in tags:
            tags.append(tag)
    return tags, invalid_tags


def source_cut_classifier_note_conflict_reasons(*, approved: bool | None, note: str) -> list[str]:
    if approved is not True or not note:
        return []
    lower_note = note.lower()
    lower_note = re.sub(
        r"\b(?:no|not|without|does not include|doesn't include|does not show|doesn't show)\s+"
        r"(?:material\s+)?(?:setup|reset|filler|cleanup|partial|wrong|missing|lacking)\b",
        " ",
        lower_note,
    )
    conflict_phrases = (
        "cannot verify",
        "can't verify",
        "not visible",
        "not clearly",
        "unclear",
        "setup",
        "reset",
        "partial",
        "wrong",
        "different variant",
        "different variation",
        "missing",
        "lacks",
    )
    if any(phrase in lower_note for phrase in conflict_phrases):
        return ["source_cut_classifier_note_conflict"]
    return []


def normalize_boundary_state_match(value: Any) -> str | None:
    normalized = slugify(str(value or "")).replace("-", "_")
    aliases = {
        "matches": "match",
        "matched": "match",
        "true": "match",
        "does_not_match": "mismatch",
        "not_match": "mismatch",
        "false": "mismatch",
        "unknown": "uncertain",
        "unclear": "uncertain",
    }
    normalized = aliases.get(normalized, normalized)
    return normalized if normalized in {"match", "mismatch", "uncertain"} else None


def topology_phase_evidence(
    value: Any,
) -> tuple[list[dict[str, Any]], list[str]]:
    if not isinstance(value, list):
        return [], ["phaseEvidence"]
    evidence: list[dict[str, Any]] = []
    missing_fields: list[str] = []
    for index, item in enumerate(value):
        if not isinstance(item, dict):
            missing_fields.append(f"phaseEvidence[{index}]")
            continue
        phase_id = str(item.get("phaseId") or item.get("phase_id") or "").strip()
        position = parse_optional_float(item.get("position"))
        if not phase_id:
            missing_fields.append(f"phaseEvidence[{index}].phaseId")
        if position is None:
            missing_fields.append(f"phaseEvidence[{index}].position")
        evidence.append({
            "phaseId": phase_id,
            "position": position,
        })
    return evidence, missing_fields


def topology_evidence_rejection_reasons(
    payload: dict[str, Any],
    movement_topology: dict[str, Any],
) -> tuple[dict[str, Any], list[str], list[str]]:
    start_match = normalize_boundary_state_match(payload.get("startStateMatch"))
    end_match = normalize_boundary_state_match(payload.get("endStateMatch"))
    evidence, evidence_missing_fields = topology_phase_evidence(payload.get("phaseEvidence"))
    missing_fields = list(evidence_missing_fields)
    ongoing_action_interval = movement_topology_accepts_ongoing_action_interval(movement_topology)
    if start_match is None:
        missing_fields.append("startStateMatch")
    if end_match is None and not ongoing_action_interval:
        missing_fields.append("endStateMatch")

    expected_phase_ids = [
        str(phase.get("id") or "").strip()
        for phase in movement_topology.get("phases", [])
        if isinstance(phase, dict)
    ]
    observed_phase_ids = [str(item.get("phaseId") or "") for item in evidence]
    positions = [item.get("position") for item in evidence]
    positions_valid = (
        len(positions) == len(expected_phase_ids)
        and all(isinstance(position, (int, float)) and 0.0 <= float(position) <= 1.0 for position in positions)
    )
    positions_increasing = positions_valid and all(
        float(positions[index]) < float(positions[index + 1])
        for index in range(len(positions) - 1)
    )

    reasons: list[str] = []
    if start_match != "match":
        reasons.append("source_cut_contract_start_state_mismatch" if start_match == "mismatch" else "source_cut_contract_start_state_uncertain")
    if not ongoing_action_interval and end_match != "match":
        reasons.append("source_cut_contract_end_state_mismatch" if end_match == "mismatch" else "source_cut_contract_end_state_uncertain")
    if observed_phase_ids != expected_phase_ids:
        reasons.append("source_cut_contract_phase_sequence_mismatch")
    if not positions_valid:
        reasons.append("source_cut_contract_phase_positions_invalid")
    elif not positions_increasing:
        reasons.append("source_cut_contract_phase_order_invalid")
    for field in missing_fields:
        reasons.append(f"source_cut_scorecard_missing_{field}")
    return (
        {
            "required": True,
            "passed": not reasons,
            "reason": (
                "ongoing_action_interval_requires_start_state_and_action_phases"
                if ongoing_action_interval
                else "complete_movement_requires_boundary_states_and_action_phases"
            ),
            "completionMode": movement_topology.get("completionMode"),
            "expectedStartState": movement_topology.get("startState"),
            "expectedEndState": movement_topology.get("endState"),
            "expectedPhaseIds": expected_phase_ids,
            "startStateMatch": start_match,
            "endStateMatch": end_match,
            "phaseEvidence": evidence,
            "observedPhaseIds": observed_phase_ids,
            "positionsValid": positions_valid,
            "positionsIncreasing": positions_increasing,
            "endStateRequired": not ongoing_action_interval,
        },
        dedupe_text(reasons),
        dedupe_text(missing_fields),
    )






def source_cut_camera_stability_classification(
    candidate: SourceCutCandidate | None,
) -> str:
    if candidate is None:
        return "unknown"
    metrics = candidate.visual_integrity.get("backgroundCameraStability")
    if not isinstance(metrics, dict):
        return "unknown"
    return str(metrics.get("classification") or "unknown")


def apply_source_cut_camera_stability_score(
    score: float,
    *,
    candidate: SourceCutCandidate | None,
) -> float:
    if source_cut_camera_stability_classification(candidate) == "moderate":
        return max(0.0, score - 0.04)
    return score


def source_cut_scorecard_row(
    payload: dict[str, Any],
    *,
    candidates_by_id: dict[str, SourceCutCandidate],
    thresholds: dict[str, float],
    legacy_thresholds: dict[str, float],
    movement_topology: dict[str, Any] | None = None,
    required_equipment: str = "none",
) -> dict[str, Any]:
    candidate_id = normalize_source_cut_candidate_id(
        payload.get("id")
        or payload.get("candidate_id")
        or payload.get("candidateId")
    )
    uses_classifier_schema = any(
        key in payload
        for key in ("approved", "accepted", "valid", "pass")
    )
    reject_tags, invalid_reject_tags = normalize_source_cut_scorecard_reject_tags(payload.get("reject"))
    note = str(payload.get("note") or payload.get("reason") or "").strip()
    if len(note) > 180:
        note = note[:180].rstrip() + "..."

    if uses_classifier_schema:
        approved_value = (
            payload.get("approved")
            if "approved" in payload
            else payload.get("accepted")
            if "accepted" in payload
            else payload.get("valid")
            if "valid" in payload
            else payload.get("pass")
        )
        approved = parse_optional_bool(approved_value)
        confidence = parse_source_cut_scorecard_score(payload.get("confidence"))
        missing_fields = []
        if approved is None:
            missing_fields.append("approved")
        if confidence is None:
            missing_fields.append("confidence")
        complete_movement = first_bool(
            payload.get("completeMovement"),
            payload.get("complete_movement"),
            payload.get("fullMovement"),
            payload.get("full_movement"),
        )
        start_boundary_clean = first_bool(
            payload.get("startBoundaryClean"),
            payload.get("start_boundary_clean"),
            payload.get("startClean"),
            payload.get("start_clean"),
        )
        finish_boundary_clean = first_bool(
            payload.get("finishBoundaryClean"),
            payload.get("finish_boundary_clean"),
            payload.get("finishClean"),
            payload.get("finish_clean"),
            payload.get("endBoundaryClean"),
            payload.get("end_boundary_clean"),
        )
        setup_or_filler = first_bool(
            payload.get("setupOrFiller"),
            payload.get("setup_or_filler"),
            payload.get("mostlySetup"),
            payload.get("mostly_setup"),
        )
        if complete_movement is None:
            missing_fields.append("completeMovement")
        if start_boundary_clean is None:
            missing_fields.append("startBoundaryClean")
        if finish_boundary_clean is None:
            missing_fields.append("finishBoundaryClean")
        if setup_or_filler is None:
            missing_fields.append("setupOrFiller")
        equipment_status = str(
            payload.get("namedEquipmentEngagedStatus")
            or payload.get("named_equipment_engaged_status")
            or ""
        ).strip().casefold()
        valid_equipment_statuses = {"engaged", "absent", "unclear", "not_applicable"}
        equipment_required = normalize_observed_equipment_name(required_equipment) != "none"
        if equipment_required and equipment_status not in valid_equipment_statuses:
            missing_fields.append("namedEquipmentEngagedStatus")

        candidate = candidates_by_id.get(candidate_id)
        target_motion_observability = (
            candidate.motion_coverage.get("targetMotionObservability")
            if candidate is not None and isinstance(candidate.motion_coverage, dict)
            else None
        )
        ongoing_action_interval = movement_topology_accepts_ongoing_action_interval(movement_topology)
        allowed_ongoing_reject_tags = {"partial_movement"}
        if start_boundary_clean is True:
            allowed_ongoing_reject_tags.add("bad_boundary")
        ongoing_action_override = bool(
            ongoing_action_interval
            and candidate is not None
            and bool(candidate.motion_coverage.get("passed"))
            and isinstance(target_motion_observability, dict)
            and bool(target_motion_observability.get("passed"))
            and start_boundary_clean is not False
            and setup_or_filler is not True
            and not invalid_reject_tags
            and set(reject_tags).issubset(allowed_ongoing_reject_tags)
        )
        effective_approved = approved is True or ongoing_action_override

        rejection_reasons: list[str] = []
        if candidate_id not in candidates_by_id:
            rejection_reasons.append("source_cut_scorecard_unknown_candidate_id")
        for field in missing_fields:
            rejection_reasons.append(f"source_cut_scorecard_missing_{field}")
        if not effective_approved:
            rejection_reasons.append("source_cut_model_rejected")
            if not reject_tags:
                rejection_reasons.append("source_cut_scorecard_missing_reject_tag")
        if complete_movement is False and not ongoing_action_override:
            rejection_reasons.append("source_cut_partial_movement")
        if start_boundary_clean is False:
            rejection_reasons.append("source_cut_start_boundary_bad")
        if finish_boundary_clean is False and not ongoing_action_override:
            rejection_reasons.append("source_cut_finish_boundary_bad")
        if setup_or_filler is True:
            rejection_reasons.append("source_cut_setup_or_filler")
        if equipment_required and equipment_status == "absent":
            rejection_reasons.append("source_cut_required_equipment_absent")
        elif equipment_required and equipment_status in {"unclear", "not_applicable"}:
            rejection_reasons.append("source_cut_required_equipment_unverified")
        if invalid_reject_tags:
            rejection_reasons.append("source_cut_scorecard_invalid_reject_tag")
        for tag in reject_tags:
            if ongoing_action_override and tag in allowed_ongoing_reject_tags:
                continue
            rejection_reasons.append(f"source_cut_scorecard_reject_{tag}")
        if confidence is not None and confidence < thresholds["confidence"]:
            rejection_reasons.append("source_cut_low_confidence")
        rejection_reasons.extend(
            source_cut_classifier_note_conflict_reasons(
                approved=effective_approved,
                note=note,
            )
        )
        topology_evidence = None
        if movement_topology is not None:
            topology_evidence, topology_reasons, topology_missing_fields = topology_evidence_rejection_reasons(
                payload,
                movement_topology,
            )
            rejection_reasons.extend(topology_reasons)
            missing_fields.extend(topology_missing_fields)

        phase_metrics = (
            candidate.motion_coverage.get("candidateFullRepetitionPhaseCompletenessMetrics")
            if candidate is not None
            else None
        )
        phase_range_ratio = (
            parse_optional_float(phase_metrics.get("dominantMotionRangeRatio"))
            if isinstance(phase_metrics, dict)
            else None
        )
        minimum_phase_range_ratio = (
            parse_optional_float(phase_metrics.get("minDominantMotionRangeRatio"))
            if isinstance(phase_metrics, dict)
            else None
        )
        endpoint_phase_delta_ratio = (
            parse_optional_float(phase_metrics.get("endpointPhaseDeltaRatio"))
            if isinstance(phase_metrics, dict)
            else None
        )
        maximum_endpoint_delta_ratio = (
            parse_optional_float(phase_metrics.get("maxEndpointPhaseDeltaRatio"))
            if isinstance(phase_metrics, dict)
            else None
        )
        phase_signal_evidence = (
            phase_metrics.get("phaseSignalEvidence")
            if isinstance(phase_metrics, dict)
            else None
        )
        phase_resolved_from_clip_noise = bool(
            isinstance(phase_signal_evidence, dict)
            and phase_signal_evidence.get("resolved") is True
        )
        legacy_high_margin_phase_evidence = bool(
            phase_range_ratio is not None
            and minimum_phase_range_ratio is not None
            and phase_range_ratio >= minimum_phase_range_ratio * 2.0
            and endpoint_phase_delta_ratio is not None
            and maximum_endpoint_delta_ratio is not None
            and endpoint_phase_delta_ratio <= maximum_endpoint_delta_ratio * 0.4
        )
        # Deterministic pose coverage is evidence about technical observability,
        # not exercise identity.  Keep the diagnostic, but never let it erase a
        # semantic rejection such as wrong exercise, setup/filler, or partial
        # movement.
        deterministic_full_cycle_override = bool(
            candidate is not None
            and candidate.motion_coverage.get("passed") is True
            and isinstance(phase_metrics, dict)
            and phase_metrics.get("passed") is True
            and (phase_resolved_from_clip_noise or legacy_high_margin_phase_evidence)
            and isinstance(topology_evidence, dict)
            and topology_evidence.get("passed") is True
            and not (
                set(reject_tags)
                & {
                    "wrong_exercise",
                    "wrong_variant",
                    "mechanics_inconsistent",
                    "contact_changed",
                    "low_source_quality",
                    "synthetic_subject",
                    "unclear",
                }
            )
        )
        deduped_reasons = dedupe_text(rejection_reasons)
        model_score = apply_source_cut_camera_stability_score(
            0.0 if confidence is None else confidence,
            candidate=candidate,
        )
        return {
            "id": candidate_id,
            "approved": approved,
            "confidence": confidence,
            "completeMovement": complete_movement,
            "startBoundaryClean": start_boundary_clean,
            "finishBoundaryClean": finish_boundary_clean,
            "setupOrFiller": setup_or_filler,
            "namedEquipmentEngagedStatus": equipment_status or None,
            "requiredEquipment": required_equipment if equipment_required else "none",
            "reject": reject_tags,
            "invalidRejectTags": invalid_reject_tags,
            "note": note,
            "score": clamp_unit(model_score),
            "passed": not deduped_reasons,
            "rejectionReasons": deduped_reasons,
            "missingFields": missing_fields,
            "movementTopologyEvidence": topology_evidence,
            "ongoingActionIntervalOverride": ongoing_action_override,
            "deterministicFullCycleOverride": deterministic_full_cycle_override,
            "cameraStabilityClassification": source_cut_camera_stability_classification(candidate),
        }

    scores = {
        field: parse_source_cut_scorecard_score(payload.get(field))
        for field in SOURCE_CUT_SCORECARD_REQUIRED_FIELDS
    }
    missing_fields = [field for field, value in scores.items() if value is None]

    rejection_reasons: list[str] = []
    if candidate_id not in candidates_by_id:
        rejection_reasons.append("source_cut_scorecard_unknown_candidate_id")
    for field in missing_fields:
        rejection_reasons.append(f"source_cut_scorecard_missing_{field}")
    if invalid_reject_tags:
        rejection_reasons.append("source_cut_scorecard_invalid_reject_tag")
    for tag in reject_tags:
        rejection_reasons.append(f"source_cut_scorecard_reject_{tag}")

    exercise_match = scores["exercise_match"]
    full_movement = scores["full_movement"]
    start_visible = scores["start_visible"]
    finish_visible = scores["finish_visible"]
    mechanics_consistency = scores["mechanics_consistency"]
    start_state_ready = scores["start_state_ready"]
    start_boundary_clean = scores["start_boundary_clean"]
    finish_boundary_clean = scores["finish_boundary_clean"]
    setup_or_filler = scores["setup_or_filler"]
    source_quality = scores["source_quality"]
    confidence = scores["confidence"]
    if exercise_match is not None and exercise_match < legacy_thresholds["exercise_match"]:
        rejection_reasons.append("source_cut_wrong_exercise")
    if full_movement is not None and full_movement < legacy_thresholds["full_movement"]:
        rejection_reasons.append("source_cut_partial_movement")
    if start_visible is not None and start_visible < legacy_thresholds["start_visible"]:
        rejection_reasons.append("source_cut_start_not_visible")
    if finish_visible is not None and finish_visible < legacy_thresholds["finish_visible"]:
        rejection_reasons.append("source_cut_finish_not_visible")
    if mechanics_consistency is not None and mechanics_consistency < legacy_thresholds["mechanics_consistency"]:
        rejection_reasons.append("source_cut_mechanics_inconsistent")
    if start_state_ready is not None and start_state_ready < legacy_thresholds["start_state_ready"]:
        rejection_reasons.append("source_cut_scorecard_reject_start_state_not_ready")
        rejection_reasons.append("source_cut_start_state_not_ready")
    if start_boundary_clean is not None and start_boundary_clean < legacy_thresholds["start_boundary_clean"]:
        rejection_reasons.append("source_cut_scorecard_reject_start_boundary_bad")
        rejection_reasons.append("source_cut_start_boundary_bad")
    if finish_boundary_clean is not None and finish_boundary_clean < legacy_thresholds["finish_boundary_clean"]:
        rejection_reasons.append("source_cut_scorecard_reject_finish_boundary_bad")
        rejection_reasons.append("source_cut_finish_boundary_bad")
    if setup_or_filler is not None and setup_or_filler > legacy_thresholds["setup_or_filler"]:
        rejection_reasons.append("source_cut_setup_or_filler")
    if source_quality is not None and source_quality < legacy_thresholds["source_quality"]:
        rejection_reasons.append("source_cut_low_source_quality")
    if confidence is not None and confidence < legacy_thresholds["confidence"]:
        rejection_reasons.append("source_cut_low_confidence")

    deduped_reasons: list[str] = []
    for reason in rejection_reasons:
        if reason not in deduped_reasons:
            deduped_reasons.append(reason)

    score_values = [
        exercise_match,
        full_movement,
        start_visible,
        finish_visible,
        mechanics_consistency,
        start_state_ready,
        start_boundary_clean,
        finish_boundary_clean,
        None if setup_or_filler is None else 1.0 - setup_or_filler,
        source_quality,
        confidence,
    ]
    resolved_score_values = [float(value) for value in score_values if value is not None]
    candidate = candidates_by_id.get(candidate_id)
    model_score = apply_source_cut_camera_stability_score(
        min(resolved_score_values) if len(resolved_score_values) == len(score_values) else 0.0,
        candidate=candidate,
    )
    return {
        "id": candidate_id,
        "exercise_match": exercise_match,
        "full_movement": full_movement,
        "start_visible": start_visible,
        "finish_visible": finish_visible,
        "mechanics_consistency": mechanics_consistency,
        "start_state_ready": start_state_ready,
        "start_boundary_clean": start_boundary_clean,
        "finish_boundary_clean": finish_boundary_clean,
        "setup_or_filler": setup_or_filler,
        "source_quality": source_quality,
        "confidence": confidence,
        "reject": reject_tags,
        "invalidRejectTags": invalid_reject_tags,
        "note": note,
        "score": clamp_unit(model_score),
        "passed": not deduped_reasons,
        "rejectionReasons": deduped_reasons,
        "missingFields": missing_fields,
        "cameraStabilityClassification": source_cut_camera_stability_classification(candidate),
    }


def build_source_cut_scorecard_ranking(
    payload: dict[str, Any],
    candidates: list[SourceCutCandidate],
    *,
    has_contract: bool,
    raw: str,
    movement_topology: dict[str, Any] | None = None,
    required_equipment: str = "none",
) -> LoopRanking:
    thresholds = source_cut_scorecard_thresholds(has_contract=has_contract)
    legacy_thresholds = legacy_source_cut_scorecard_thresholds(has_contract=has_contract)
    candidates_by_id = {
        normalize_source_cut_candidate_id(candidate.candidate_id): candidate
        for candidate in candidates
    }
    rows = [
        source_cut_scorecard_row(
            item,
            candidates_by_id=candidates_by_id,
            thresholds=thresholds,
            legacy_thresholds=legacy_thresholds,
            movement_topology=movement_topology,
            required_equipment=required_equipment,
        )
        for item in source_cut_scorecard_candidate_payloads(payload)
    ]
    passing: list[tuple[float, float, float, SourceCutCandidate, dict[str, Any]]] = []
    for row in rows:
        candidate = candidates_by_id.get(str(row["id"]))
        if candidate is None or not bool(row["passed"]):
            continue
        score = float(row["score"])
        passing.append(
            (
                source_cut_candidate_duration(candidate),
                -score,
                -float(candidate.window.end_seconds),
                candidate,
                row,
            )
        )

    base_payload: dict[str, Any] = {
        "sourceCutScorecardSchemaVersion": 3,
        "sourceCutScorecardThresholds": thresholds,
        "sourceCutScorecardContractPresent": has_contract,
        "sourceCutScorecardCandidates": rows,
        "sourceCutClassifierSchema": "approved_confidence_equipment_reject_note",
        "sourceCutMovementTopologyRequired": movement_topology is not None,
        "sourceCutSelectionPolicy": "progressive_multiscale_stable_level_then_score",
        "sourceCutCandidates": source_cut_candidates_payload(candidates),
    }
    if not passing:
        return LoopRanking(
            score=0.0,
            reasons=["source_candidate_scorecard_no_passing_candidate"],
            raw_response=raw,
            payload={
                **base_payload,
                "score": 0.0,
                "modelScore": 0.0,
            },
            model_score=0.0,
        )

    _duration, negative_score, _negative_end, selected, selected_row = min(passing)
    score = -negative_score
    note = str(selected_row.get("note") or "source_candidate_scorecard_passed")
    return LoopRanking(
        score=score,
        reasons=[note, "source_candidate_scorecard_passed", "source_candidate_window_choice"],
        raw_response=raw,
        payload={
            **base_payload,
            "score": score,
            "modelScore": score,
            "selectedCandidateId": selected.candidate_id,
            "selected_section_start_seconds": selected.window.start_seconds,
            "selected_section_end_seconds": selected.window.end_seconds,
            "selectedScorecard": selected_row,
        },
        model_score=score,
    )


def build_movement_cut_scorecard_ranking(
    payload: dict[str, Any],
    candidates: list[SourceCutCandidate],
    *,
    has_contract: bool,
    raw: str,
    movement_topology: dict[str, Any] | None = None,
) -> LoopRanking:
    source_ranking = build_source_cut_scorecard_ranking(
        payload,
        candidates,
        has_contract=has_contract,
        raw=raw,
        movement_topology=movement_topology,
    )
    source_payload = source_ranking.payload if isinstance(source_ranking.payload, dict) else {}
    movement_payload: dict[str, Any] = {
        "score": source_payload.get("score", source_ranking.score),
        "modelScore": source_payload.get("modelScore", source_ranking.model_score),
        "movementCutScorecardSchemaVersion": source_payload.get("sourceCutScorecardSchemaVersion", 1),
        "movementCutScorecardThresholds": source_payload.get("sourceCutScorecardThresholds"),
        "movementCutScorecardContractPresent": source_payload.get("sourceCutScorecardContractPresent", has_contract),
        "movementCutScorecardCandidates": source_payload.get("sourceCutScorecardCandidates", []),
        "movementCutSelectionPolicy": "shortest_scorecard_complete_movement",
        "movementCutCandidates": source_payload.get("sourceCutCandidates", source_cut_candidates_payload(candidates)),
        "finalCutResponsibility": "movement_window_selection_only",
    }
    for key in (
        "selectedCandidateId",
        "selected_section_start_seconds",
        "selected_section_end_seconds",
        "selectedScorecard",
    ):
        if key in source_payload:
            movement_payload[key] = source_payload[key]
    reasons = [
        str(reason)
        .replace("source_candidate_scorecard_passed", "movement_cut_scorecard_passed")
        .replace("source_candidate_window_choice", "movement_cut_candidate_window_choice")
        .replace("source_candidate_scorecard_no_passing_candidate", "movement_cut_scorecard_no_passing_candidate")
        for reason in source_ranking.reasons
    ]
    return LoopRanking(
        score=source_ranking.score,
        reasons=dedupe_text(reasons),
        raw_response=source_ranking.raw_response,
        payload=movement_payload,
        model_score=source_ranking.model_score,
        continuity_score=source_ranking.continuity_score,
        continuity_metrics=source_ranking.continuity_metrics,
    )


def parse_source_cut_candidate_choice(
    raw: str,
    candidates: list[SourceCutCandidate],
    *,
    has_contract: bool = True,
    exercise_motion_contract: dict[str, Any] | None = None,
    required_equipment: str = "none",
) -> LoopRanking | None:
    payload = extract_json_object_with_trailing_repair(raw)
    if not isinstance(payload, dict):
        return None
    if not source_cut_scorecard_payload_has_valid_confidence(payload):
        return None
    return build_source_cut_scorecard_ranking(
        payload,
        candidates,
        has_contract=has_contract,
        raw=raw,
        movement_topology=movement_topology_from_contract(exercise_motion_contract),
        required_equipment=required_equipment,
    )


def parse_movement_cut_candidate_choice(
    raw: str,
    candidates: list[SourceCutCandidate],
    *,
    min_duration_seconds: float | None = None,
    has_contract: bool = True,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> LoopRanking | None:
    payload = extract_json_object_with_trailing_repair(raw)
    if not isinstance(payload, dict):
        return None
    if not source_cut_scorecard_payload_has_valid_confidence(payload):
        return None
    ranking = build_movement_cut_scorecard_ranking(
        payload,
        candidates,
        has_contract=has_contract,
        raw=raw,
        movement_topology=movement_topology_from_contract(exercise_motion_contract),
    )
    if min_duration_seconds is None or ranking.score <= 0.0:
        return ranking
    selected_window = selected_window_from_cut_ranking(ranking)
    if selected_window is None:
        return ranking
    if window_duration_seconds(selected_window) + 1e-6 >= min_duration_seconds:
        return ranking
    ranking_payload = dict(ranking.payload or {})
    ranking_payload["movementCutMinSelectedDurationSeconds"] = min_duration_seconds
    ranking_payload["movementCutDurationFloorRejected"] = True
    return LoopRanking(
        score=0.0,
        reasons=dedupe_text([*ranking.reasons, "movement_cut_selected_duration_below_floor"]),
        raw_response=ranking.raw_response,
        payload=ranking_payload,
        model_score=0.0,
    )


def cut_candidate_error_payload(candidate_ids: list[str], exc: BaseException) -> dict[str, Any]:
    message = str(exc)
    if len(message) > 1200:
        message = message[:1200] + "...[truncated]"
    payload = {
        "candidateIds": candidate_ids,
        "errorType": exc.__class__.__name__,
        "message": message,
    }
    if is_critical_vlm_interaction_error(exc):
        payload["criticalVlmError"] = vlm_error_payload(exc)
    return payload


def write_cut_candidate_critical_vlm_error_reports(
    candidates: list[SourceCutCandidate],
    exc: BaseException,
    *,
    context: dict[str, Any] | None = None,
) -> None:
    if not is_critical_vlm_interaction_error(exc):
        return
    candidate_context = {
        "candidateIds": [candidate.candidate_id for candidate in candidates],
        "candidateWindows": [
            {
                "id": candidate.candidate_id,
                "startSeconds": candidate.window.start_seconds,
                "endSeconds": candidate.window.end_seconds,
                "framePaths": [str(path) for path in candidate.frame_paths],
                "boundaryAuditFramePaths": [str(path) for path in candidate.boundary_audit_frame_paths],
            }
            for candidate in candidates
        ],
    }
    for candidate in candidates:
        if not candidate.frame_paths:
            continue
        write_critical_vlm_error_report(
            candidate.frame_paths[0].parent,
            exc,
            context={
                **candidate_context,
                **(context or {}),
                "reportCandidateId": candidate.candidate_id,
            },
        )


def cut_candidate_duration_groups(candidates: list[SourceCutCandidate]) -> list[list[SourceCutCandidate]]:
    ordered = sorted(
        candidates,
        key=lambda candidate: (
            source_cut_candidate_duration(candidate),
            candidate.window.start_seconds,
            candidate.window.end_seconds,
            candidate.candidate_id,
        ),
    )
    groups: list[list[SourceCutCandidate]] = []
    current: list[SourceCutCandidate] = []
    current_duration: float | None = None
    for candidate in ordered:
        duration = source_cut_candidate_duration(candidate)
        if current and current_duration is not None and abs(duration - current_duration) > CUT_CANDIDATE_DURATION_BUCKET_SECONDS:
            groups.append(current)
            current = []
            current_duration = None
        if current_duration is None:
            current_duration = duration
        current.append(candidate)
    if current:
        groups.append(current)
    return groups


def cut_candidates_with_ids(candidates: list[SourceCutCandidate], candidate_ids: list[str]) -> list[SourceCutCandidate]:
    wanted = set(candidate_ids)
    return [candidate for candidate in candidates if candidate.candidate_id in wanted]


def cut_candidate_vlm_caption_kwargs(
    *,
    max_tokens: int = CUT_CANDIDATE_VLM_MAX_TOKENS,
    request_timeout_seconds: float | None = CUT_CANDIDATE_VLM_REQUEST_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    kwargs = {
        "max_tokens": max(1, int(max_tokens)),
        "disable_reasoning": CUT_CANDIDATE_VLM_DISABLE_REASONING,
        "temperature": CUT_CANDIDATE_VLM_TEMPERATURE,
        "top_p": CUT_CANDIDATE_VLM_TOP_P,
        "json_response": True,
    }
    if request_timeout_seconds is not None:
        requested_timeout = float(request_timeout_seconds)
        kwargs["request_timeout_seconds"] = (
            0.0 if requested_timeout <= 0.0 else max(1.0, requested_timeout)
        )
    return kwargs


def source_cut_vlm_caption_kwargs(
    request_timeout_seconds: float = DEFAULT_SOURCE_REVIEW_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    kwargs = cut_candidate_vlm_caption_kwargs(
        max_tokens=SOURCE_CUT_CANDIDATE_VLM_MAX_TOKENS,
        request_timeout_seconds=request_timeout_seconds,
    )
    kwargs["disable_reasoning"] = SOURCE_CUT_CANDIDATE_VLM_DISABLE_REASONING
    return kwargs


def collect_ranking_payload_rows(rankings: Iterable[LoopRanking], key: str) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    for ranking in rankings:
        payload = ranking.payload if isinstance(ranking.payload, dict) else {}
        value = payload.get(key)
        if not isinstance(value, list):
            continue
        for item in value:
            if not isinstance(item, dict):
                continue
            row_id = str(item.get("id") or item.get("candidateId") or "")
            if row_id and row_id in seen_ids:
                continue
            if row_id:
                seen_ids.add(row_id)
            rows.append(item)
    return rows




def combine_cut_candidate_review_results(results: Iterable[CutCandidateReviewResult]) -> CutCandidateReviewResult:
    rankings: list[LoopRanking] = []
    raw_responses: list[str] = []
    errors: list[dict[str, Any]] = []
    reviewed_candidate_ids: list[str] = []
    for result in results:
        rankings.extend(result.rankings)
        raw_responses.extend(result.raw_responses)
        errors.extend(result.errors)
        for candidate_id in result.reviewed_candidate_ids:
            if candidate_id not in reviewed_candidate_ids:
                reviewed_candidate_ids.append(candidate_id)
    return CutCandidateReviewResult(
        rankings=rankings,
        raw_responses=raw_responses,
        errors=errors,
        reviewed_candidate_ids=reviewed_candidate_ids,
    )


def rank_cut_candidates_with_caption_images(
    *,
    candidates: list[SourceCutCandidate],
    caption_images: Callable[..., str],
    prompt_builder: Callable[[SourceCutCandidate], str],
    parser: Callable[[str, SourceCutCandidate], LoopRanking | None],
    max_workers: int = 1,
    caption_image_kwargs: dict[str, Any] | None = None,
) -> CutCandidateReviewResult:
    if max(1, int(max_workers)) <= 1 or len(candidates) <= 1:
        return combine_cut_candidate_review_results(
            rank_cut_candidate_with_caption_images(
                candidate=candidate,
                caption_images=caption_images,
                prompt_builder=prompt_builder,
                parser=parser,
                caption_image_kwargs=caption_image_kwargs,
            )
            for candidate in candidates
        )

    results_by_index: list[CutCandidateReviewResult | None] = [None] * len(candidates)
    with ThreadPoolExecutor(max_workers=min(max(1, int(max_workers)), len(candidates))) as executor:
        futures = {
            executor.submit(
                rank_cut_candidate_with_caption_images,
                candidate=candidate,
                caption_images=caption_images,
                prompt_builder=prompt_builder,
                parser=parser,
                caption_image_kwargs=caption_image_kwargs,
            ): index
            for index, candidate in enumerate(candidates)
        }
        for future in as_completed(futures):
            index = futures[future]
            candidate = candidates[index]
            try:
                results_by_index[index] = future.result()
            except Exception as exc:
                if is_critical_vlm_interaction_error(exc):
                    add_vlm_context(
                        exc,
                        stage="cut_candidate_parallel_review",
                        candidateId=candidate.candidate_id,
                    )
                    raise
                results_by_index[index] = CutCandidateReviewResult(
                    rankings=[],
                    raw_responses=[],
                    errors=[
                        cut_candidate_error_payload(
                            [candidate.candidate_id],
                            exc,
                        )
                    ],
                    reviewed_candidate_ids=[candidate.candidate_id],
                )
    return combine_cut_candidate_review_results(
        result for result in results_by_index if result is not None
    )


def selected_candidate_id_from_cut_ranking(ranking: LoopRanking) -> str:
    payload = ranking.payload if isinstance(ranking.payload, dict) else {}
    return normalize_source_cut_candidate_id(
        payload.get("selectedCandidateId")
        or payload.get("selected_candidate_id")
        or payload.get("candidateId")
        or payload.get("id")
    )


def candidate_for_cut_ranking(
    ranking: LoopRanking,
    candidates_by_id: dict[str, SourceCutCandidate],
    candidates: list[SourceCutCandidate],
) -> SourceCutCandidate | None:
    candidate_id = selected_candidate_id_from_cut_ranking(ranking)
    if candidate_id:
        candidate = candidates_by_id.get(candidate_id)
        if candidate is not None:
            return candidate
    selected_window = selected_window_from_cut_ranking(ranking)
    if selected_window is None:
        return None
    for candidate in candidates:
        if (
            abs(candidate.window.start_seconds - selected_window.start_seconds) <= 0.02
            and abs(candidate.window.end_seconds - selected_window.end_seconds) <= 0.02
        ):
            return candidate
    return None


def source_cut_progressive_level_index(candidate: SourceCutCandidate) -> int:
    level_index = parse_optional_float(candidate.chunking.get("levelIndex")) if candidate.chunking else None
    if level_index is None:
        return 0
    return max(0, int(level_index))


def source_cut_stable_candidate_selection_key(
    ranking: LoopRanking,
    candidate: SourceCutCandidate,
) -> tuple[float, float, float]:
    duration = max(0.0, float(candidate.window.end_seconds - candidate.window.start_seconds))
    return (
        -ranking.score,
        duration,
        float(candidate.window.start_seconds),
    )


def source_cut_progressive_level_stable_candidate_ids(
    *,
    level_candidates: list[SourceCutCandidate],
    passing_candidates: list[SourceCutCandidate],
) -> set[str]:
    if not passing_candidates:
        return set()
    passing_ids = {candidate.candidate_id for candidate in passing_candidates}
    if len(level_candidates) <= 2:
        return passing_ids

    passing_sorted = sorted(passing_candidates, key=lambda candidate: candidate.window.start_seconds)
    clusters: list[list[SourceCutCandidate]] = []
    current: list[SourceCutCandidate] = []
    previous: SourceCutCandidate | None = None
    for candidate in passing_sorted:
        if previous is None:
            current = [candidate]
        else:
            overlap = max(
                0.0,
                min(previous.window.end_seconds, candidate.window.end_seconds)
                - max(previous.window.start_seconds, candidate.window.start_seconds),
            )
            min_duration = max(
                1e-6,
                min(source_cut_candidate_duration(previous), source_cut_candidate_duration(candidate)),
            )
            if overlap / min_duration >= SOURCE_CUT_PROGRESSIVE_MIN_CLUSTER_OVERLAP_RATIO:
                current.append(candidate)
            else:
                if current:
                    clusters.append(current)
                current = [candidate]
        previous = candidate
    if current:
        clusters.append(current)

    stable_clusters = [
        cluster
        for cluster in clusters
        if len(cluster) >= SOURCE_CUT_PROGRESSIVE_MIN_CLUSTER_SIZE
    ]
    if not stable_clusters:
        return set()
    best_cluster = max(
        stable_clusters,
        key=lambda cluster: (
            len(cluster),
            -min(candidate.window.start_seconds for candidate in cluster),
        ),
    )
    return {candidate.candidate_id for candidate in best_cluster}


def progressive_source_cut_stable_levels(
    rankings: list[LoopRanking],
    candidates: list[SourceCutCandidate],
    *,
    stop_at_first_unstable_after_stable: bool = True,
) -> tuple[list[dict[str, Any]], int | None]:
    candidates_by_id = {
        normalize_source_cut_candidate_id(candidate.candidate_id): candidate
        for candidate in candidates
    }
    ranking_by_candidate_id: dict[str, LoopRanking] = {}
    for ranking in rankings:
        candidate = candidate_for_cut_ranking(ranking, candidates_by_id, candidates)
        if (
            candidate is None
            or selected_window_from_cut_ranking(ranking) is None
            or ranking.score <= 0.0
        ):
            continue
        ranking_by_candidate_id[candidate.candidate_id] = ranking

    if not ranking_by_candidate_id:
        return [], None

    candidates_by_level: dict[int, list[SourceCutCandidate]] = {}
    for candidate in candidates:
        candidates_by_level.setdefault(source_cut_progressive_level_index(candidate), []).append(candidate)

    stable_levels: list[dict[str, Any]] = []
    stopped_at_unstable_level: int | None = None
    for level_index in sorted(candidates_by_level):
        level_candidates = sorted(
            candidates_by_level[level_index],
            key=lambda candidate: (candidate.window.start_seconds, candidate.window.end_seconds),
        )
        passing_candidates = [
            candidate
            for candidate in level_candidates
            if candidate.candidate_id in ranking_by_candidate_id
        ]
        stable_candidate_ids = source_cut_progressive_level_stable_candidate_ids(
            level_candidates=level_candidates,
            passing_candidates=passing_candidates,
        )
        if not stable_candidate_ids:
            if stable_levels:
                if stopped_at_unstable_level is None:
                    stopped_at_unstable_level = level_index
                if stop_at_first_unstable_after_stable:
                    break
            continue

        eligible_rankings = [
            (ranking_by_candidate_id[candidate.candidate_id], candidate)
            for candidate in passing_candidates
            if candidate.candidate_id in stable_candidate_ids
        ]
        if not eligible_rankings:
            continue
        best_ranking, best_candidate = min(
            eligible_rankings,
            key=lambda item: source_cut_stable_candidate_selection_key(item[0], item[1]),
        )
        stable_levels.append(
            {
                "levelIndex": level_index,
                "candidateCount": len(level_candidates),
                "passingCandidateCount": len(passing_candidates),
                "stablePassingCandidateCount": len(stable_candidate_ids),
                "selectedCandidateId": best_candidate.candidate_id,
                "selectedStartSeconds": best_candidate.window.start_seconds,
                "selectedEndSeconds": best_candidate.window.end_seconds,
                "selectedDurationSeconds": source_cut_candidate_duration(best_candidate),
                "levelStrategy": best_candidate.chunking.get("strategy") if best_candidate.chunking else None,
                "boundaryAnchor": best_candidate.chunking.get("boundaryAnchor") if best_candidate.chunking else None,
                "levelDurationSeconds": best_candidate.chunking.get("levelDurationSeconds")
                if best_candidate.chunking
                else source_cut_candidate_duration(best_candidate),
                "levelRatio": best_candidate.chunking.get("levelRatio") if best_candidate.chunking else None,
                "ranking": best_ranking,
            }
        )

    return stable_levels, stopped_at_unstable_level


def select_cross_level_supported_source_cut_ranking(
    rankings: list[LoopRanking],
    candidates: list[SourceCutCandidate],
) -> LoopRanking | None:
    candidates_by_id = {
        normalize_source_cut_candidate_id(candidate.candidate_id): candidate
        for candidate in candidates
    }
    ranking_by_candidate_id: dict[str, LoopRanking] = {}
    for ranking in rankings:
        candidate = candidate_for_cut_ranking(ranking, candidates_by_id, candidates)
        if candidate is None or selected_window_from_cut_ranking(ranking) is None or ranking.score <= 0.0:
            continue
        ranking_by_candidate_id[candidate.candidate_id] = ranking

    passing_candidates = [
        candidate
        for candidate in candidates
        if candidate.candidate_id in ranking_by_candidate_id
    ]
    passing_levels = {
        source_cut_progressive_level_index(candidate)
        for candidate in passing_candidates
    }
    if len(passing_levels) < 2:
        return None

    supported_ids: set[str] = set()
    support_pairs: list[dict[str, Any]] = []
    for index, candidate in enumerate(passing_candidates):
        candidate_level = source_cut_progressive_level_index(candidate)
        candidate_duration = source_cut_candidate_duration(candidate)
        for other in passing_candidates[index + 1 :]:
            other_level = source_cut_progressive_level_index(other)
            if other_level == candidate_level:
                continue
            other_duration = source_cut_candidate_duration(other)
            min_duration = max(1e-6, min(candidate_duration, other_duration))
            overlap = max(
                0.0,
                min(candidate.window.end_seconds, other.window.end_seconds)
                - max(candidate.window.start_seconds, other.window.start_seconds),
            )
            overlap_ratio = overlap / min_duration
            if overlap_ratio < SOURCE_CUT_PROGRESSIVE_MIN_CLUSTER_OVERLAP_RATIO:
                continue
            supported_ids.add(candidate.candidate_id)
            supported_ids.add(other.candidate_id)
            support_pairs.append(
                {
                    "candidateId": candidate.candidate_id,
                    "candidateLevelIndex": candidate_level,
                    "otherCandidateId": other.candidate_id,
                    "otherLevelIndex": other_level,
                    "overlapRatio": round(overlap_ratio, 3),
                }
            )

    supported_levels = {
        source_cut_progressive_level_index(candidate)
        for candidate in passing_candidates
        if candidate.candidate_id in supported_ids
    }
    if len(supported_levels) < 2:
        return None

    eligible_rankings = [
        (ranking_by_candidate_id[candidate.candidate_id], candidate)
        for candidate in passing_candidates
        if candidate.candidate_id in supported_ids
    ]
    if not eligible_rankings:
        return None
    best_ranking, best_candidate = min(
        eligible_rankings,
        key=lambda item: source_cut_stable_candidate_selection_key(item[0], item[1]),
    )
    payload = dict(best_ranking.payload) if isinstance(best_ranking.payload, dict) else {}
    payload["sourceCutProgressiveSelection"] = {
        "strategy": "progressive_multiscale_cross_level_support",
        "selectedCandidateId": best_candidate.candidate_id,
        "selectedLevelIndex": source_cut_progressive_level_index(best_candidate),
        "passingCandidateCount": len(passing_candidates),
        "supportedPassingCandidateCount": len(supported_ids),
        "supportedLevelIndices": sorted(supported_levels),
        "supportPairs": support_pairs,
    }
    payload["sourceCutSelectionPolicy"] = "progressive_multiscale_cross_level_support_then_score"
    return replace(
        best_ranking,
        payload=payload,
        reasons=dedupe_text([*best_ranking.reasons, "progressive_source_cut_cross_level_support"]),
    )


def source_cut_confirmation_padding_cannot_restore_trimmed_span(
    *,
    selected_start: float,
    selected_end: float,
    confirmation_start: float,
    confirmation_end: float,
    padding_seconds: float = SOURCE_CUT_STABLE_CONFIRMATION_PADDING_SECONDS,
) -> bool:
    trimmed_before = max(0.0, selected_start - confirmation_start)
    trimmed_after = max(0.0, confirmation_end - selected_end)
    return (
        trimmed_before > padding_seconds + 1e-6
        or trimmed_after > padding_seconds + 1e-6
    )


def select_progressive_source_cut_ranking(
    rankings: list[LoopRanking],
    candidates: list[SourceCutCandidate],
    *,
    pad_one_stable_level: bool = True,
    stop_at_first_unstable_after_stable: bool = True,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> LoopRanking | None:
    stable_levels, stopped_at_unstable_level = progressive_source_cut_stable_levels(
        rankings,
        candidates,
        stop_at_first_unstable_after_stable=stop_at_first_unstable_after_stable,
    )
    if not stable_levels:
        cross_level_ranking = select_cross_level_supported_source_cut_ranking(rankings, candidates)
        if cross_level_ranking is not None:
            return cross_level_ranking

        candidates_by_id = {
            normalize_source_cut_candidate_id(candidate.candidate_id): candidate
            for candidate in candidates
        }
        isolated_passing: list[tuple[LoopRanking, SourceCutCandidate]] = []
        for ranking in rankings:
            candidate = candidate_for_cut_ranking(ranking, candidates_by_id, candidates)
            if candidate is None or ranking.score <= 0.0 or selected_window_from_cut_ranking(ranking) is None:
                continue
            isolated_passing.append((ranking, candidate))
        if not isolated_passing:
            return None

        ranking, candidate = min(
            isolated_passing,
            key=lambda item: source_cut_stable_candidate_selection_key(item[0], item[1]),
        )
        payload = dict(ranking.payload) if isinstance(ranking.payload, dict) else {}
        payload["sourceCutProgressiveSelection"] = {
            "strategy": "progressive_multiscale_isolated_passing_fallback",
            "selectedCandidateId": candidate.candidate_id,
            "selectedLevelIndex": source_cut_progressive_level_index(candidate),
            "passingCandidateCount": len(isolated_passing),
            "crossLevelSupportPreferred": True,
            "crossLevelSupportAvailable": False,
        }
        payload["sourceCutSelectionPolicy"] = "progressive_multiscale_isolated_passing_fallback"
        return replace(
            ranking,
            payload=payload,
            reasons=dedupe_text([*ranking.reasons, "progressive_source_cut_isolated_passing_fallback"]),
        )

    all_stable_to_floor = stopped_at_unstable_level is None
    deepest_level = stable_levels[-1]
    deepest_level_is_boundary_sweep = (
        deepest_level.get("levelStrategy") == "progressive_start_anchored_end_boundary_sweep"
    )
    selected_level = deepest_level
    confirmation_level = stable_levels[-2] if len(stable_levels) >= 2 else None
    bounded_padding_applied = False
    kept_wider_for_return_cycle = False
    confirmation_overlap_ratio = None
    selected_start = float(deepest_level["selectedStartSeconds"])
    selected_end = float(deepest_level["selectedEndSeconds"])
    if pad_one_stable_level and not deepest_level_is_boundary_sweep and confirmation_level is not None:
        confirmation_start = float(confirmation_level["selectedStartSeconds"])
        confirmation_end = float(confirmation_level["selectedEndSeconds"])
        deepest_duration = max(1e-6, selected_end - selected_start)
        overlap = max(
            0.0,
            min(selected_end, confirmation_end) - max(selected_start, confirmation_start),
        )
        confirmation_overlap_ratio = overlap / deepest_duration
        if confirmation_overlap_ratio >= SOURCE_CUT_STABLE_CONFIRMATION_MIN_OVERLAP_RATIO:
            if (
                observable_motion_spec_requires_return(exercise_motion_contract)
                and source_cut_confirmation_padding_cannot_restore_trimmed_span(
                    selected_start=selected_start,
                    selected_end=selected_end,
                    confirmation_start=confirmation_start,
                    confirmation_end=confirmation_end,
                )
            ):
                # Nested shortest windows often drop the return phase. 0.35s of
                # confirmation padding cannot restore that missing motion.
                selected_level = confirmation_level
                selected_start = confirmation_start
                selected_end = confirmation_end
                kept_wider_for_return_cycle = True
            else:
                selected_start -= min(
                    SOURCE_CUT_STABLE_CONFIRMATION_PADDING_SECONDS,
                    max(0.0, selected_start - confirmation_start),
                )
                selected_end += min(
                    SOURCE_CUT_STABLE_CONFIRMATION_PADDING_SECONDS,
                    max(0.0, confirmation_end - selected_end),
                )
                bounded_padding_applied = True
        else:
            # Separate temporal regions can both contain valid repetitions. If
            # the shorter window is not confirmed by the adjacent wider scale,
            # retain the wider approved window instead of synthesizing a cut
            # between unrelated repetitions.
            selected_level = confirmation_level
            selected_start = float(selected_level["selectedStartSeconds"])
            selected_end = float(selected_level["selectedEndSeconds"])
    ranking = selected_level["ranking"]
    payload = dict(ranking.payload) if isinstance(ranking.payload, dict) else {}
    payload["selected_section_start_seconds"] = selected_start
    payload["selected_section_end_seconds"] = selected_end
    if kept_wider_for_return_cycle:
        selection_strategy = "progressive_multiscale_return_cycle_keep_wider_confirmed_window"
    elif bounded_padding_applied:
        selection_strategy = "progressive_multiscale_shortest_stable_with_bounded_padding"
    else:
        selection_strategy = "progressive_multiscale_sliding_stable_level"
    payload["sourceCutProgressiveSelection"] = {
        "strategy": selection_strategy,
        "selectedLevelIndex": selected_level["levelIndex"],
        "deepestStableLevelIndex": stable_levels[-1]["levelIndex"],
        "confirmationLevelIndex": confirmation_level["levelIndex"] if confirmation_level else None,
        "confirmationOverlapRatio": (
            round(confirmation_overlap_ratio, 4)
            if confirmation_overlap_ratio is not None
            else None
        ),
        "confirmationMinOverlapRatio": SOURCE_CUT_STABLE_CONFIRMATION_MIN_OVERLAP_RATIO,
        "boundedPaddingApplied": bounded_padding_applied,
        "boundedPaddingSeconds": (
            SOURCE_CUT_STABLE_CONFIRMATION_PADDING_SECONDS
            if bounded_padding_applied
            else 0.0
        ),
        "selectedStartSeconds": selected_start,
        "selectedEndSeconds": selected_end,
        "selectedDurationSeconds": selected_end - selected_start,
        "stoppedAtUnstableLevelIndex": stopped_at_unstable_level,
        "allStableToFloor": all_stable_to_floor,
        "boundarySweepSelectedWithoutPadding": deepest_level_is_boundary_sweep,
        "returnCycleKeptWiderConfirmation": kept_wider_for_return_cycle,
        "stableLevels": [
            {
                key: value
                for key, value in level.items()
                if key != "ranking"
            }
            for level in stable_levels
        ],
    }
    if kept_wider_for_return_cycle:
        selection_policy = "progressive_multiscale_return_cycle_keep_wider_confirmation"
    elif bounded_padding_applied:
        selection_policy = "progressive_multiscale_shortest_stable_with_bounded_confirmation_padding"
    else:
        selection_policy = "progressive_multiscale_stable_level_then_score"
    payload["sourceCutSelectionPolicy"] = selection_policy
    return replace(
        ranking,
        payload=payload,
        reasons=dedupe_text(
            [
                *ranking.reasons,
                "progressive_source_cut_stable_level_selection",
                *(
                    ["progressive_source_cut_return_cycle_kept_wider_confirmation"]
                    if kept_wider_for_return_cycle
                    else []
                ),
                *(
                    ["progressive_source_cut_bounded_confirmation_padding"]
                    if bounded_padding_applied
                    else []
                ),
            ]
        ),
    )


def cut_candidate_review_debug_path(candidate: SourceCutCandidate) -> Path | None:
    for paths in (
        candidate.frame_paths,
        candidate.boundary_audit_frame_paths,
        candidate.sample_frame_paths,
    ):
        if paths:
            return Path(paths[0]).parent / "vlm_review_debug.json"
    return None


def loop_ranking_debug_payload(ranking: LoopRanking | None) -> dict[str, Any] | None:
    if ranking is None:
        return None
    return {
        "score": ranking.score,
        "modelScore": ranking.model_score,
        "reasons": ranking.reasons,
        "rawResponse": ranking.raw_response,
        "payload": ranking.payload,
    }


def write_cut_candidate_vlm_review_debug(
    *,
    candidate: SourceCutCandidate,
    prompt: str,
    request_kwargs: dict[str, Any],
    raw_response: str | None = None,
    ranking: LoopRanking | None = None,
    error: BaseException | None = None,
) -> None:
    debug_path = cut_candidate_review_debug_path(candidate)
    if debug_path is None:
        return
    payload: dict[str, Any] = {
        "schemaVersion": 1,
        "candidateId": candidate.candidate_id,
        "window": {
            "startSeconds": candidate.window.start_seconds,
            "endSeconds": candidate.window.end_seconds,
        },
        "framePaths": [str(path) for path in candidate.frame_paths],
        "boundaryAuditFramePaths": [str(path) for path in candidate.boundary_audit_frame_paths],
        "sampleFramePaths": [str(path) for path in candidate.sample_frame_paths],
        "requestKwargs": request_kwargs,
        "prompt": prompt,
        "rawResponse": raw_response,
        "ranking": loop_ranking_debug_payload(ranking),
    }
    if error is not None:
        payload["error"] = {
            "type": type(error).__name__,
            "message": str(error),
        }
    try:
        debug_path.parent.mkdir(parents=True, exist_ok=True)
        debug_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    except Exception:
        pass


def rank_cut_candidate_with_caption_images(
    *,
    candidate: SourceCutCandidate,
    caption_images: Callable[..., str],
    prompt_builder: Callable[[SourceCutCandidate], str],
    parser: Callable[[str, SourceCutCandidate], LoopRanking | None],
    caption_image_kwargs: dict[str, Any] | None = None,
) -> CutCandidateReviewResult:
    candidate_ids = [candidate.candidate_id]
    request_kwargs = dict(caption_image_kwargs or {})
    prompt = prompt_builder(candidate)
    raw: str | None = None
    ranking: LoopRanking | None = None
    try:
        for request_attempt in range(2):
            attempt_prompt = prompt
            if request_attempt > 0:
                attempt_prompt += (
                    "\nYour previous response violated the JSON schema. Return the same requested JSON schema again. "
                    "Every confidence value must be a decimal number from 0.0 through 1.0 inclusive; values such as "
                    "5, 95, and strings such as 95% are invalid."
                )
            try:
                raw = caption_images(
                    frame_paths=list(candidate.frame_paths),
                    prompt=attempt_prompt,
                    **request_kwargs,
                )
            except TypeError as exc:
                # Some unit tests provide a caption_images stub that only accepts
                # `frame_paths` and `prompt`. In that case, retry without any
                # additional VLM tuning kwargs.
                if request_kwargs and "unexpected keyword argument" in str(exc):
                    raw = caption_images(
                        frame_paths=list(candidate.frame_paths),
                        prompt=attempt_prompt,
                    )
                else:
                    raise
            ranking = parser(raw, candidate)
            if ranking is not None:
                break
    except Exception as exc:
        write_cut_candidate_vlm_review_debug(
            candidate=candidate,
            prompt=prompt,
            request_kwargs=request_kwargs,
            error=exc,
        )
        if isinstance(exc, CandidateWallTimeBudgetExpired):
            return CutCandidateReviewResult(
                rankings=[],
                raw_responses=[],
                errors=[cut_candidate_error_payload(candidate_ids, exc)],
                reviewed_candidate_ids=candidate_ids,
            )
        critical = wrap_vlm_infrastructure_error(
            exc,
            interaction="cut_candidate_review",
            timeout_seconds=request_kwargs.get("request_timeout_seconds")
            if isinstance(request_kwargs.get("request_timeout_seconds"), (int, float))
            else None,
        )
        if critical is not None:
            critical.add_details(
                stage="cut_candidate_review",
                candidateIds=candidate_ids,
                candidateCount=1,
                frameCount=len(candidate.frame_paths),
            )
            write_cut_candidate_critical_vlm_error_reports(
                [candidate],
                critical,
                context={
                    "stage": "cut_candidate_review",
                    "candidateCount": 1,
                    "captionImageKwargs": request_kwargs,
                },
            )
            if critical is exc:
                raise
            raise critical from exc
        return CutCandidateReviewResult(
            rankings=[],
            raw_responses=[],
            errors=[cut_candidate_error_payload(candidate_ids, exc)],
            reviewed_candidate_ids=candidate_ids,
        )
    write_cut_candidate_vlm_review_debug(
        candidate=candidate,
        prompt=prompt,
        request_kwargs=request_kwargs,
        raw_response=raw,
        ranking=ranking,
    )
    return CutCandidateReviewResult(
        rankings=[ranking] if ranking is not None else [],
        raw_responses=[raw],
        errors=[],
        reviewed_candidate_ids=candidate_ids,
    )


def annotate_progressive_source_cut_review_payload(
    ranking: LoopRanking,
    *,
    all_level_indices: list[int],
    reviewed_level_indices: list[int],
    level_candidate_counts: dict[int, int],
    early_stopped: bool,
    pad_one_stable_level: bool,
    review_scheduling: str = "progressive_levels_sequential",
) -> LoopRanking:
    payload = dict(ranking.payload) if isinstance(ranking.payload, dict) else {}
    selection_payload = payload.get("sourceCutProgressiveSelection")
    selection = dict(selection_payload) if isinstance(selection_payload, dict) else {}
    reviewed_set = set(reviewed_level_indices)
    selection.update(
        {
            "reviewOrder": "smallest_windows_first",
            "stopRule": (
                "shortest_stable_level_confirmed_by_next_wider_stable_level"
                if not pad_one_stable_level
                else "shortest_stable_level_with_bounded_next_wider_confirmation_padding"
            ),
            "earlyStopped": bool(early_stopped),
            "reviewScheduling": review_scheduling,
            "reviewedLevelIndices": reviewed_level_indices,
            "unreviewedLevelIndices": [
                level_index
                for level_index in all_level_indices
                if level_index not in reviewed_set
            ],
            "levelCandidateCounts": {
                str(level_index): count
                for level_index, count in sorted(level_candidate_counts.items())
            },
        }
    )
    payload["sourceCutProgressiveSelection"] = selection
    reasons = [*ranking.reasons]
    reasons.append(
        "progressive_source_cut_early_stop"
        if early_stopped
        else "progressive_source_cut_exhausted_levels"
    )
    return replace(
        ranking,
        payload=payload,
        reasons=dedupe_text(reasons),
    )


def rank_progressive_source_cut_candidates_with_caption_images(
    *,
    candidates: list[SourceCutCandidate],
    caption_images: Callable[..., str],
    prompt_builder: Callable[[SourceCutCandidate], str],
    parser: Callable[[str, SourceCutCandidate], LoopRanking | None],
    max_workers: int = 1,
    early_stop_after_stable_levels: bool = True,
    pad_one_stable_level: bool = True,
    caption_image_kwargs: dict[str, Any] | None = None,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> CutCandidateReviewChoice:
    started = time.perf_counter()
    if not candidates:
        return CutCandidateReviewChoice(
            ranking=None,
            raw_responses=[],
            errors=[],
            reviewed_candidate_ids=[],
            reviewed_request_count=0,
            elapsed_seconds=elapsed_seconds(started),
            rankings=[],
        )

    candidates_by_level: dict[int, list[SourceCutCandidate]] = {}
    for candidate in candidates:
        candidates_by_level.setdefault(source_cut_progressive_level_index(candidate), []).append(candidate)
    all_level_indices = sorted(candidates_by_level)
    review_level_indices = sorted(candidates_by_level, reverse=True)
    level_candidate_counts = {
        level_index: len(level_candidates)
        for level_index, level_candidates in candidates_by_level.items()
    }

    reviewed_level_indices: list[int] = []
    partial_results: list[CutCandidateReviewResult] = []
    reviewed_request_count = 0

    # Source-cut requests are independent and the production shortlist is
    # intentionally smaller than the configured llama.cpp slot count. Review
    # every shortlisted scale in one wave when all requests fit. This preserves
    # the exact scorecards and cross-scale selection policy while avoiding a
    # full model-latency round trip per progressive level.
    if max(1, int(max_workers)) >= len(candidates):
        ordered_candidates = [
            candidate
            for level_index in review_level_indices
            for candidate in sorted(
                candidates_by_level[level_index],
                key=lambda item: (
                    item.window.start_seconds,
                    item.window.end_seconds,
                    item.candidate_id,
                ),
            )
        ]
        combined = rank_cut_candidates_with_caption_images(
            candidates=ordered_candidates,
            caption_images=caption_images,
            prompt_builder=prompt_builder,
            parser=parser,
            max_workers=max_workers,
            caption_image_kwargs=caption_image_kwargs,
        )
        best_ranking = select_progressive_source_cut_ranking(
            combined.rankings,
            candidates,
            pad_one_stable_level=pad_one_stable_level,
            stop_at_first_unstable_after_stable=False,
            exercise_motion_contract=exercise_motion_contract,
        )
        if best_ranking is not None:
            best_ranking = annotate_progressive_source_cut_review_payload(
                best_ranking,
                all_level_indices=all_level_indices,
                reviewed_level_indices=review_level_indices,
                level_candidate_counts=level_candidate_counts,
                early_stopped=False,
                pad_one_stable_level=pad_one_stable_level,
                review_scheduling="all_shortlisted_levels_parallel",
            )
        return CutCandidateReviewChoice(
            ranking=best_ranking,
            raw_responses=combined.raw_responses,
            errors=combined.errors,
            reviewed_candidate_ids=combined.reviewed_candidate_ids,
            reviewed_request_count=max(
                len(ordered_candidates),
                len(combined.raw_responses) + len(combined.errors),
            ),
            elapsed_seconds=elapsed_seconds(started),
            rankings=combined.rankings,
        )

    for level_index in review_level_indices:
        level_candidates = sorted(
            candidates_by_level[level_index],
            key=lambda candidate: (
                candidate.window.start_seconds,
                candidate.window.end_seconds,
                candidate.candidate_id,
            ),
        )
        result = rank_cut_candidates_with_caption_images(
            candidates=level_candidates,
            caption_images=caption_images,
            prompt_builder=prompt_builder,
            parser=parser,
            max_workers=max_workers,
            caption_image_kwargs=caption_image_kwargs,
        )
        partial_results.append(result)
        reviewed_request_count += len(level_candidates)
        reviewed_level_indices.append(level_index)
        combined = combine_cut_candidate_review_results(partial_results)
        stable_levels, _stopped_at_unstable_level = progressive_source_cut_stable_levels(
            combined.rankings,
            candidates,
            stop_at_first_unstable_after_stable=False,
        )
        if not early_stop_after_stable_levels or len(stable_levels) < 2:
            continue
        best_ranking = select_progressive_source_cut_ranking(
            combined.rankings,
            candidates,
            pad_one_stable_level=pad_one_stable_level,
            stop_at_first_unstable_after_stable=False,
            exercise_motion_contract=exercise_motion_contract,
        )
        if best_ranking is None:
            continue
        return CutCandidateReviewChoice(
            ranking=annotate_progressive_source_cut_review_payload(
                best_ranking,
                all_level_indices=all_level_indices,
                reviewed_level_indices=reviewed_level_indices,
                level_candidate_counts=level_candidate_counts,
                early_stopped=True,
                pad_one_stable_level=pad_one_stable_level,
            ),
            raw_responses=combined.raw_responses,
            errors=combined.errors,
            reviewed_candidate_ids=combined.reviewed_candidate_ids,
            reviewed_request_count=max(
                reviewed_request_count,
                len(combined.raw_responses) + len(combined.errors),
            ),
            elapsed_seconds=elapsed_seconds(started),
            rankings=combined.rankings,
        )

    combined = combine_cut_candidate_review_results(partial_results)
    best_ranking = select_progressive_source_cut_ranking(
        combined.rankings,
        candidates,
        pad_one_stable_level=pad_one_stable_level,
        stop_at_first_unstable_after_stable=False,
        exercise_motion_contract=exercise_motion_contract,
    )
    if best_ranking is not None:
        best_ranking = annotate_progressive_source_cut_review_payload(
            best_ranking,
            all_level_indices=all_level_indices,
            reviewed_level_indices=reviewed_level_indices,
            level_candidate_counts=level_candidate_counts,
            early_stopped=False,
            pad_one_stable_level=pad_one_stable_level,
        )
    return CutCandidateReviewChoice(
        ranking=best_ranking,
        raw_responses=combined.raw_responses,
        errors=combined.errors,
        reviewed_candidate_ids=combined.reviewed_candidate_ids,
        reviewed_request_count=max(
            reviewed_request_count,
            len(combined.raw_responses) + len(combined.errors),
        ),
        elapsed_seconds=elapsed_seconds(started),
        rankings=combined.rankings,
    )


def rank_cut_candidates_shortest_first_with_caption_images(
    *,
    candidates: list[SourceCutCandidate],
    caption_images: Callable[..., str],
    prompt_builder: Callable[[SourceCutCandidate], str],
    parser: Callable[[str, SourceCutCandidate], LoopRanking | None],
    max_workers: int = 1,
    prefer_later_equal_duration: bool = False,
    prefer_largest_padded_candidate: bool = False,
    progressive_source_selection: bool = False,
    progressive_source_early_stop: bool = True,
    progressive_pad_one_stable_level: bool = True,
    caption_image_kwargs: dict[str, Any] | None = None,
    exercise_motion_contract: dict[str, Any] | None = None,
) -> CutCandidateReviewChoice:
    started = time.perf_counter()
    if progressive_source_selection:
        return rank_progressive_source_cut_candidates_with_caption_images(
            candidates=candidates,
            caption_images=caption_images,
            prompt_builder=prompt_builder,
            parser=parser,
            max_workers=max_workers,
            early_stop_after_stable_levels=progressive_source_early_stop,
            pad_one_stable_level=progressive_pad_one_stable_level,
            caption_image_kwargs=caption_image_kwargs,
            exercise_motion_contract=exercise_motion_contract,
        )
    ordered_candidates = [
        candidate
        for duration_group in cut_candidate_duration_groups(candidates)
        for candidate in duration_group
    ]
    combined = rank_cut_candidates_with_caption_images(
        candidates=ordered_candidates,
        caption_images=caption_images,
        prompt_builder=prompt_builder,
        parser=parser,
        max_workers=max_workers,
        caption_image_kwargs=caption_image_kwargs,
    )
    def ranking_selection_key(ranking: LoopRanking) -> tuple[float, float, float]:
        selected_window = selected_window_from_cut_ranking(ranking)
        duration = (
            window_duration_seconds(selected_window)
            if selected_window is not None
            else 0.0
        )
        if prefer_largest_padded_candidate:
            return (
                -ranking.score,
                -duration if selected_window is not None else math.inf,
                -selected_window.end_seconds if selected_window is not None else 0.0,
            )
        return (
            duration if selected_window is not None else math.inf,
            -ranking.score,
            -selected_window.end_seconds
            if prefer_later_equal_duration and selected_window is not None
            else 0.0,
        )

    best_ranking = (
        min(
            combined.rankings,
            key=ranking_selection_key,
        )
        if combined.rankings
        else None
    )
    return CutCandidateReviewChoice(
        ranking=best_ranking,
        raw_responses=combined.raw_responses,
        errors=combined.errors,
        reviewed_candidate_ids=combined.reviewed_candidate_ids,
        reviewed_request_count=max(len(ordered_candidates), len(combined.raw_responses) + len(combined.errors)),
        elapsed_seconds=elapsed_seconds(started),
        rankings=combined.rankings,
    )


def run_source_cut_review_with_adaptive_recovery(
    review: Callable[[int, dict[str, Any]], CutCandidateReviewChoice],
    *,
    max_workers: int,
    caption_image_kwargs: dict[str, Any],
) -> tuple[CutCandidateReviewChoice, dict[str, Any] | None]:
    initial_workers = max(1, int(max_workers))
    try:
        return review(initial_workers, caption_image_kwargs), None
    except Exception as exc:
        critical = critical_vlm_interaction_error(exc)
        if critical is None or not critical.recoverable or initial_workers <= 1:
            raise

        initial_timeout = parse_optional_float(
            caption_image_kwargs.get("request_timeout_seconds")
        )
        recovery_timeout = max(
            SOURCE_CUT_RECOVERY_MIN_TIMEOUT_SECONDS,
            (initial_timeout or DEFAULT_SOURCE_REVIEW_TIMEOUT_SECONDS) * 2.0,
        )
        recovery_kwargs = dict(caption_image_kwargs)
        recovery_kwargs["request_timeout_seconds"] = recovery_timeout
        recovered = review(1, recovery_kwargs)
        return recovered, {
            "applied": True,
            "reason": "recoverable_parallel_vlm_failure",
            "initialWorkers": initial_workers,
            "initialTimeoutSeconds": initial_timeout,
            "recoveryWorkers": 1,
            "recoveryTimeoutSeconds": recovery_timeout,
            "initialError": vlm_error_payload(exc),
        }


def movement_cut_candidate_source_motion_coverage_ratio(candidate: SourceCutCandidate) -> float:
    if not candidate.motion_coverage:
        return 1.0
    value = parse_optional_float(candidate.motion_coverage.get("sourceMotionCoverageRatio"))
    return 1.0 if value is None else clamp_unit(value)


def movement_cut_candidate_has_complete_phase(candidate: SourceCutCandidate) -> bool:
    metrics = candidate.motion_coverage.get("candidateFullRepetitionPhaseCompletenessMetrics") if candidate.motion_coverage else None
    return (
        isinstance(metrics, dict)
        and bool(metrics.get("required"))
        and bool(metrics.get("passed"))
        and str(metrics.get("reason") or "")
        in {
            "full_repetition_phase_return_detected",
            "source_pose_full_repetition_phase_return_detected",
        }
    )


def movement_cut_candidate_target_motion_score(candidate: SourceCutCandidate) -> float:
    metrics = candidate.motion_coverage.get("targetMotionGate") if candidate.motion_coverage else None
    if not isinstance(metrics, dict):
        return 1.0
    value = parse_optional_float(metrics.get("targetMotionRangeRatio"))
    minimum = parse_optional_float(metrics.get("minTargetMotionRangeRatio"))
    if value is None or minimum is None or minimum <= 1e-6:
        return 1.0
    return clamp_unit(value / minimum)


def movement_cut_candidate_confidence_key(candidate: SourceCutCandidate) -> tuple[int, int, float, float, float]:
    duration = max(0.0, candidate.window.end_seconds - candidate.window.start_seconds)
    return (
        1 if not candidate.motion_coverage or bool(candidate.motion_coverage.get("passed")) else 0,
        1 if movement_cut_candidate_has_complete_phase(candidate) else 0,
        movement_cut_candidate_source_motion_coverage_ratio(candidate),
        movement_cut_candidate_target_motion_score(candidate),
        -duration,
    )


def shortlist_movement_cut_vlm_candidates(
    candidates: list[SourceCutCandidate],
    *,
    max_candidates: int = MOVEMENT_CUT_MAX_INITIAL_VLM_CANDIDATES,
) -> list[SourceCutCandidate]:
    if max_candidates <= 0 or len(candidates) <= max_candidates:
        return list(candidates)

    ranked = sorted(candidates, key=movement_cut_candidate_confidence_key, reverse=True)
    selected: list[SourceCutCandidate] = []
    selected_ids: set[str] = set()

    def add(candidate: SourceCutCandidate) -> None:
        if candidate.candidate_id in selected_ids or len(selected) >= max_candidates:
            return
        selected.append(candidate)
        selected_ids.add(candidate.candidate_id)

    broad_fallback = max(
        candidates,
        key=lambda candidate: (
            window_duration_seconds(candidate.window),
            movement_cut_candidate_source_motion_coverage_ratio(candidate),
            movement_cut_candidate_target_motion_score(candidate),
            candidate.window.end_seconds,
        ),
    )
    reserve_broad_fallback = broad_fallback.candidate_id != ranked[0].candidate_id
    primary_budget = max_candidates - 1 if reserve_broad_fallback else max_candidates
    for candidate in ranked:
        if len(selected) >= primary_budget:
            break
        add(candidate)
    add(broad_fallback)
    for candidate in ranked:
        if len(selected) >= max_candidates:
            break
        add(candidate)
    return selected


def shortlist_source_window_specs_by_pose(
    specs: list[SourceWindowCandidateSpec],
    *,
    pose_payload: dict[str, Any],
    exercise_name: str,
    chunk_estimate: Any,
    exercise_motion_contract: dict[str, Any] | None,
    source_offset_seconds: float,
    max_candidates: int = SOURCE_CUT_MAX_MATERIALIZED_CANDIDATES,
) -> list[SourceWindowCandidateSpec]:
    """Choose source windows from cached pose evidence before rendering images."""
    if max_candidates <= 0 or len(specs) <= max_candidates:
        return list(specs)
    provisional: list[tuple[SourceWindowCandidateSpec, SourceCutCandidate]] = []
    for index, spec in enumerate(specs):
        candidate = SourceCutCandidate(
            candidate_id=source_cut_candidate_id_for_index(index),
            window=spec.window,
            frame_paths=[],
            pose_prefilter=source_cut_candidate_pose_prefilter_metrics(
                candidate_window=spec.window,
                pose_payload=pose_payload,
                source_offset_seconds=source_offset_seconds,
            ),
            motion_coverage=source_cut_candidate_motion_coverage_metrics(
                candidate_window=spec.window,
                pose_payload=pose_payload,
                exercise_name=exercise_name,
                chunk_estimate=chunk_estimate,
                exercise_motion_contract=exercise_motion_contract,
                source_offset_seconds=source_offset_seconds,
            ),
            chunking=spec.chunking,
        )
        provisional.append((spec, candidate))
    ranked = sorted(provisional, key=lambda item: movement_cut_candidate_confidence_key(item[1]), reverse=True)
    broadest = max(
        provisional,
        key=lambda item: (
            window_duration_seconds(item[0].window),
            movement_cut_candidate_source_motion_coverage_ratio(item[1]),
        ),
    )
    selected: list[tuple[SourceWindowCandidateSpec, SourceCutCandidate]] = []
    primary_budget = max(0, max_candidates - 1)
    primary_pool = [item for item in ranked if item != broadest]

    def window_center(item: tuple[SourceWindowCandidateSpec, SourceCutCandidate]) -> float:
        return (item[0].window.start_seconds + item[0].window.end_seconds) * 0.5

    if primary_pool and primary_budget > 0:
        timeline_start = min(item[0].window.start_seconds for item in provisional)
        timeline_end = max(item[0].window.end_seconds for item in provisional)
        timeline_span = max(1e-6, timeline_end - timeline_start)
        estimated_min = parse_optional_float(getattr(chunk_estimate, "rep_duration_min_sec", None))
        estimated_max = parse_optional_float(getattr(chunk_estimate, "rep_duration_max_sec", None))
        for bin_index in range(3):
            bin_start = timeline_start + timeline_span * bin_index / 3.0
            bin_end = timeline_start + timeline_span * (bin_index + 1) / 3.0
            bin_center = (bin_start + bin_end) * 0.5
            bin_items = [
                item
                for item in primary_pool
                if bin_start <= window_center(item) <= bin_end + (1e-6 if bin_index == 2 else 0.0)
            ]
            if not bin_items or len(selected) >= primary_budget:
                continue
            available_durations = sorted(
                {
                    round(window_duration_seconds(item[0].window), 2)
                    for item in bin_items
                }
            )
            if estimated_min is not None and estimated_max is not None and estimated_max >= estimated_min:
                target_durations = [
                    estimated_min + (estimated_max - estimated_min) * index / 4.0
                    for index in range(5)
                ]
            else:
                target_durations = [
                    available_durations[
                        int(round((len(available_durations) - 1) * index / 4.0))
                    ]
                    for index in range(5)
                ]
            selected_duration_scales: list[float] = []
            for target_duration in target_durations:
                selected_duration = min(
                    available_durations,
                    key=lambda duration: abs(duration - target_duration),
                )
                if all(abs(selected_duration - existing) > 0.10 for existing in selected_duration_scales):
                    selected_duration_scales.append(selected_duration)
            for selected_duration in selected_duration_scales:
                if len(selected) >= primary_budget:
                    break
                same_scale = [
                    item
                    for item in bin_items
                    if abs(window_duration_seconds(item[0].window) - selected_duration) <= 0.10
                    and item in primary_pool
                ]
                if not same_scale:
                    continue
                duration_representative = max(
                    same_scale,
                    key=lambda item: (
                        -abs(window_center(item) - bin_center),
                        movement_cut_candidate_confidence_key(item[1]),
                    ),
                )
                selected.append(duration_representative)
                primary_pool.remove(duration_representative)

    # Pose phase scores are only a heuristic and can produce several confident
    # false positives in one part of a clip. The per-third shortest candidates
    # above cover position and duration; fill the remaining small review budget
    # by temporal coverage so one false positive cannot crowd out another area.
    while primary_pool and len(selected) < primary_budget:
        next_item = max(
            primary_pool,
            key=lambda item: (
                min(abs(window_center(item) - window_center(chosen)) for chosen in selected),
                movement_cut_candidate_confidence_key(item[1]),
            ),
        )
        selected.append(next_item)
        primary_pool.remove(next_item)

    selected.append(broadest)
    for item in ranked:
        if len(selected) >= max_candidates:
            break
        if item not in selected:
            selected.append(item)
    selected_specs = {id(item[0]) for item in selected}
    return [spec for spec in specs if id(spec) in selected_specs]






def selected_window_from_cut_ranking(ranking: LoopRanking) -> DetectionWindow | None:
    payload = ranking.payload if isinstance(ranking.payload, dict) else {}
    start = first_float(
        payload.get("selected_section_start_seconds"),
        payload.get("selectedSectionStartSeconds"),
        payload.get("startSeconds"),
    )
    end = first_float(
        payload.get("selected_section_end_seconds"),
        payload.get("selectedSectionEndSeconds"),
        payload.get("endSeconds"),
    )
    if start is None or end is None or end <= start:
        return None
    return DetectionWindow(index=0, start_seconds=float(start), end_seconds=float(end))


def window_duration_seconds(window: DetectionWindow) -> float:
    return max(0.0, float(window.end_seconds) - float(window.start_seconds))


def selected_window_is_materially_shorter(
    *,
    parent_window: DetectionWindow,
    child_window: DetectionWindow,
) -> bool:
    parent_duration = window_duration_seconds(parent_window)
    child_duration = window_duration_seconds(child_window)
    if child_duration < SOURCE_CUT_REFINEMENT_MIN_SECONDS:
        return False
    required_improvement = max(
        SOURCE_CUT_REFINEMENT_MIN_ABSOLUTE_IMPROVEMENT_SECONDS,
        parent_duration * SOURCE_CUT_REFINEMENT_MIN_RELATIVE_IMPROVEMENT,
    )
    return child_duration <= parent_duration - required_improvement


def shortest_passing_cut_ranking(rankings: Iterable[LoopRanking]) -> LoopRanking | None:
    passing: list[tuple[float, float, float, int, LoopRanking]] = []
    for index, ranking in enumerate(rankings):
        if ranking.score <= 0.0:
            continue
        selected_window = selected_window_from_cut_ranking(ranking)
        if selected_window is None:
            continue
        passing.append(
            (
                window_duration_seconds(selected_window),
                -ranking.score,
                -selected_window.end_seconds,
                index,
                ranking,
            )
        )
    if not passing:
        return None
    return min(passing)[4]


def movement_cut_row_reject_tags(row: dict[str, Any]) -> set[str]:
    value = row.get("reject")
    if isinstance(value, list):
        return {str(item) for item in value if str(item)}
    if isinstance(value, str):
        return {part.strip() for part in re.split(r"[,;\n]+", value) if part.strip()}
    return set()


def movement_cut_row_rejection_reasons(row: dict[str, Any]) -> set[str]:
    value = row.get("rejectionReasons")
    if isinstance(value, list):
        return {str(item) for item in value if str(item)}
    return set()


def movement_cut_row_is_targeted_refinement_candidate(row: dict[str, Any]) -> bool:
    reject_tags = movement_cut_row_reject_tags(row)
    rejection_reasons = movement_cut_row_rejection_reasons(row)
    blocking_wrong_tags = {
        "wrong_exercise",
        "wrong_variant",
        "mechanics_inconsistent",
        "contact_changed",
        "low_source_quality",
        "synthetic_subject",
        "unclear",
    }
    blocking_wrong_reasons = {
        "source_cut_wrong_exercise",
        "source_cut_mechanics_inconsistent",
        "source_cut_low_source_quality",
        "source_cut_scorecard_reject_wrong_exercise",
        "source_cut_scorecard_reject_wrong_variant",
        "source_cut_scorecard_reject_mechanics_inconsistent",
        "source_cut_scorecard_reject_contact_changed",
        "source_cut_scorecard_reject_low_source_quality",
        "source_cut_scorecard_reject_synthetic_subject",
        "source_cut_scorecard_reject_unclear",
    }
    if reject_tags & blocking_wrong_tags or rejection_reasons & blocking_wrong_reasons:
        return False
    confidence = parse_optional_float(row.get("confidence"))
    if confidence is not None and confidence < 0.50:
        return False
    boundary_or_filler_reasons = {
        "source_cut_start_boundary_bad",
        "source_cut_finish_boundary_bad",
        "source_cut_setup_or_filler",
        "source_cut_scorecard_reject_bad_boundary",
        "source_cut_scorecard_reject_setup_or_filler",
    }
    return (
        row.get("completeMovement") is True
        or row.get("startBoundaryClean") is False
        or row.get("finishBoundaryClean") is False
        or row.get("setupOrFiller") is True
        or bool(reject_tags & {"bad_boundary", "setup_or_filler"})
        or bool(rejection_reasons & boundary_or_filler_reasons)
    )


def movement_cut_row_dirty_start(row: dict[str, Any]) -> bool:
    reject_tags = movement_cut_row_reject_tags(row)
    rejection_reasons = movement_cut_row_rejection_reasons(row)
    return (
        row.get("startBoundaryClean") is False
        or "source_cut_start_boundary_bad" in rejection_reasons
    )


def movement_cut_row_dirty_finish(row: dict[str, Any]) -> bool:
    reject_tags = movement_cut_row_reject_tags(row)
    rejection_reasons = movement_cut_row_rejection_reasons(row)
    return (
        row.get("finishBoundaryClean") is False
        or "bad_boundary" in reject_tags
        or bool(
            rejection_reasons
            & {
                "source_cut_finish_boundary_bad",
                "source_cut_scorecard_reject_bad_boundary",
            }
        )
    )


def movement_cut_targeted_trim_offsets(duration: float) -> list[float]:
    offsets: list[float] = []
    for ratio in MOVEMENT_CUT_TARGETED_BOUNDARY_REFINEMENT_TRIM_RATIOS:
        offset = max(
            MOVEMENT_CUT_TARGETED_BOUNDARY_REFINEMENT_MIN_TRIM_SECONDS,
            duration * ratio,
        )
        if offset >= duration - SOURCE_CUT_REFINEMENT_MIN_SECONDS:
            continue
        rounded = round(offset, 2)
        if all(abs(rounded - existing) > 0.04 for existing in offsets):
            offsets.append(rounded)
    return offsets


def movement_cut_targeted_refinement_specs(
    *,
    rows: list[dict[str, Any]],
    candidates_by_id: dict[str, SourceCutCandidate],
    existing_windows: Iterable[DetectionWindow],
    min_duration_seconds: float | None = None,
    max_specs: int = MOVEMENT_CUT_TARGETED_BOUNDARY_REFINEMENT_MAX_CHILD_CANDIDATES,
) -> list[MovementCutTargetedRefinementSpec]:
    existing_keys = {
        (round(window.start_seconds, 2), round(window.end_seconds, 2))
        for window in existing_windows
    }
    specs: list[MovementCutTargetedRefinementSpec] = []
    seen_keys = set(existing_keys)
    parent_count = 0

    def append_spec(
        *,
        parent: SourceCutCandidate,
        start: float,
        end: float,
        reasons: list[str],
    ) -> None:
        if len(specs) >= max_specs:
            return
        start = max(parent.window.start_seconds, min(parent.window.end_seconds, start))
        end = max(start, min(parent.window.end_seconds, end))
        if end - start < SOURCE_CUT_REFINEMENT_MIN_SECONDS:
            return
        if min_duration_seconds is not None and end - start + 1e-6 < min_duration_seconds:
            return
        key = (round(start, 2), round(end, 2))
        if key in seen_keys:
            return
        seen_keys.add(key)
        child_index = len(specs) + 1
        specs.append(
            MovementCutTargetedRefinementSpec(
                candidate_id=f"{parent.candidate_id}_T{child_index:02d}",
                window=DetectionWindow(index=child_index - 1, start_seconds=key[0], end_seconds=key[1]),
                parent_candidate_id=parent.candidate_id,
                reasons=dedupe_text(reasons),
            )
        )

    for row in rows:
        if parent_count >= MOVEMENT_CUT_TARGETED_BOUNDARY_REFINEMENT_MAX_PARENT_CANDIDATES:
            break
        if not movement_cut_row_is_targeted_refinement_candidate(row):
            continue
        candidate_id = normalize_source_cut_candidate_id(row.get("id") or row.get("candidateId"))
        parent = candidates_by_id.get(candidate_id)
        if parent is None:
            continue
        parent_count += 1
        duration = window_duration_seconds(parent.window)
        offsets = movement_cut_targeted_trim_offsets(duration)
        if not offsets:
            continue
        dirty_start = movement_cut_row_dirty_start(row)
        dirty_finish = movement_cut_row_dirty_finish(row)
        setup_or_filler_inside = (
            row.get("setupOrFiller") is True
            or "setup_or_filler" in movement_cut_row_reject_tags(row)
            or "source_cut_setup_or_filler" in movement_cut_row_rejection_reasons(row)
            or "source_cut_scorecard_reject_setup_or_filler" in movement_cut_row_rejection_reasons(row)
        )
        if setup_or_filler_inside and not dirty_start and not dirty_finish:
            dirty_start = True
            dirty_finish = True
        if not dirty_start and not dirty_finish:
            dirty_finish = True
        row_reasons = sorted(movement_cut_row_rejection_reasons(row))
        for offset in offsets:
            if dirty_finish:
                append_spec(
                    parent=parent,
                    start=parent.window.start_seconds,
                    end=parent.window.end_seconds - offset,
                    reasons=["finish_boundary_sweep", *row_reasons],
                )
            if dirty_start:
                append_spec(
                    parent=parent,
                    start=parent.window.start_seconds + offset,
                    end=parent.window.end_seconds,
                    reasons=["start_boundary_sweep", *row_reasons],
                )
            if dirty_start and dirty_finish:
                append_spec(
                    parent=parent,
                    start=parent.window.start_seconds + offset,
                    end=parent.window.end_seconds - offset,
                    reasons=["both_boundary_sweep", *row_reasons],
                )
        if dirty_start and dirty_finish:
            for start_offset in offsets[:3]:
                for end_offset in offsets[:3]:
                    append_spec(
                        parent=parent,
                        start=parent.window.start_seconds + start_offset,
                        end=parent.window.end_seconds - end_offset,
                        reasons=["both_boundary_sweep", *row_reasons],
                    )
    return specs


def build_movement_cut_review_candidate(
    *,
    item: ReviewItem,
    candidate_id: str,
    candidate_window: DetectionWindow,
    output_dir: Path,
    frame_count: int,
    timeline_window: DetectionWindow,
    chunk_estimate: Any,
    exercise_motion_contract: dict[str, Any] | None,
    chunking: dict[str, Any] | None = None,
) -> SourceCutCandidate | None:
    frame_paths = render_source_review_window_contact_sheet(
        item=item,
        window=candidate_window,
        output_dir=output_dir,
        frame_count=cut_candidate_contact_sheet_frame_count(frame_count),
    )
    candidate = build_source_cut_candidate(
        candidate_id=candidate_id,
        candidate_window=candidate_window,
        contact_sheet_paths=frame_paths,
        output_dir=output_dir,
        chunking=chunking,
        include_boundary_audit=True,
    )
    if candidate is None:
        return None
    return replace(
        candidate,
        motion_coverage=movement_cut_candidate_motion_coverage_metrics(
            item=item,
            parent_window=timeline_window,
            candidate_window=candidate_window,
            chunk_estimate=chunk_estimate,
            exercise_motion_contract=exercise_motion_contract,
        ),
    )


def cut_refinement_stage_payload(
    *,
    ranking: LoopRanking,
    parent_window: DetectionWindow,
    selected_window: DetectionWindow,
    stage_index: int,
    candidates_key: str,
    vlm_candidates_key: str,
) -> dict[str, Any]:
    payload = ranking.payload if isinstance(ranking.payload, dict) else {}
    stage: dict[str, Any] = {
        "stageIndex": stage_index,
        "parentStartSeconds": parent_window.start_seconds,
        "parentEndSeconds": parent_window.end_seconds,
        "parentDurationSeconds": window_duration_seconds(parent_window),
        "selectedStartSeconds": selected_window.start_seconds,
        "selectedEndSeconds": selected_window.end_seconds,
        "selectedDurationSeconds": window_duration_seconds(selected_window),
        "selectedCandidateId": payload.get("selectedCandidateId"),
        "score": ranking.score,
        "selectionPolicy": payload.get("sourceCutSelectionPolicy")
        or payload.get("movementCutSelectionPolicy"),
    }
    if isinstance(payload.get(candidates_key), list):
        stage[candidates_key] = payload.get(candidates_key)
    if isinstance(payload.get(vlm_candidates_key), list):
        stage[vlm_candidates_key] = payload.get(vlm_candidates_key)
    return stage


def prepend_cut_refinement_stage(
    ranking: LoopRanking,
    *,
    stages_key: str,
    stage: dict[str, Any],
) -> LoopRanking:
    payload = dict(ranking.payload) if isinstance(ranking.payload, dict) else {}
    existing = payload.get(stages_key)
    stages = [item for item in existing if isinstance(item, dict)] if isinstance(existing, list) else []
    stages = [stage, *stages]
    payload[stages_key] = stages
    payload["cutRefinementApplied"] = True
    payload["cutRefinementStageCount"] = len(stages)
    return replace(
        ranking,
        payload=payload,
        reasons=dedupe_text([*ranking.reasons, "recursive_shortest_complete_movement_refinement"]),
    )


def rank_movement_cut_candidates_with_caption_images(
    *,
    item: ReviewItem,
    timeline_window: DetectionWindow,
    chunk_estimate: Any,
    output_dir: Path,
    frame_count: int,
    caption_images: Callable[..., str],
    use_exercise_motion_contract: bool = True,
    max_vlm_workers: int = 1,
    _refinement_depth: int = 0,
) -> tuple[LoopRanking, float, float] | None:
    candidate_windows = build_source_cut_candidate_windows(
        window=timeline_window,
        chunk_estimate=chunk_estimate,
        min_estimated_duration_ratio=MOVEMENT_CUT_MIN_ESTIMATED_DURATION_RATIO,
    )
    if not candidate_windows:
        return None
    estimated_min_duration = parse_optional_float(getattr(chunk_estimate, "rep_duration_min_sec", None))
    min_selected_duration_seconds = None
    if estimated_min_duration is not None and estimated_min_duration > 0.0:
        min_selected_duration_seconds = min(
            window_duration_seconds(timeline_window),
            estimated_min_duration * MOVEMENT_CUT_MIN_SELECTED_ESTIMATED_DURATION_RATIO,
        )
    exercise_motion_contract = (
        exercise_motion_contract_for_review_item(item, None)
        if use_exercise_motion_contract
        else None
    )
    render_started = time.perf_counter()
    candidates: list[SourceCutCandidate] = []
    all_candidates: list[SourceCutCandidate] = []
    for index, candidate_window in enumerate(candidate_windows):
        candidate_id = source_cut_candidate_id_for_index(index)
        candidate_output_dir = output_dir / f"movement_cut_candidate_{candidate_id}"
        candidate = build_movement_cut_review_candidate(
            item=item,
            candidate_id=candidate_id,
            candidate_window=candidate_window,
            output_dir=candidate_output_dir,
            frame_count=frame_count,
            timeline_window=timeline_window,
            chunk_estimate=chunk_estimate,
            exercise_motion_contract=exercise_motion_contract,
        )
        if candidate is not None:
            all_candidates.append(candidate)
            if source_cut_candidate_passes_visual_integrity(candidate):
                candidates.append(candidate)
    render_seconds = elapsed_seconds(render_started)
    visual_integrity_fallback = not candidates and bool(all_candidates)
    if visual_integrity_fallback:
        candidates = list(all_candidates)
    if not candidates:
        return (
            LoopRanking(
                score=0.0,
                reasons=["movement_cut_candidate_window_choice_failed", "movement_cut_deterministic_visual_integrity_failed"],
                payload={
                    "score": 0.0,
                    "modelScore": 0.0,
                    "movementCutCandidates": source_cut_candidates_payload(all_candidates),
                    **movement_cut_manual_trim_payload(
                        reason="movement_cut_deterministic_visual_integrity_failed",
                        candidates=all_candidates,
                    ),
                    "movementCutDeterministicVisualIntegrityFailed": True,
                    "finalCutResponsibility": "movement_window_selection_only",
                },
                model_score=0.0,
            ),
            render_seconds,
            0.0,
        )
    hard_motion_rejected_count = sum(
        1
        for candidate in candidates
        if movement_cut_candidate_has_hard_motion_rejection(candidate)
    )
    hard_motion_rejection_reasons = dedupe_text(
        reason
        for candidate in candidates
        for reason in movement_cut_candidate_hard_motion_rejection_reasons(candidate)
    )
    target_motion_gate_failed = "movement_cut_low_target_region_motion" in hard_motion_rejection_reasons
    eligible_vlm_candidates = [
        candidate
        for candidate in candidates
        if not movement_cut_candidate_has_hard_motion_rejection(candidate)
    ]
    duration_eligible_vlm_candidates = [
        candidate
        for candidate in eligible_vlm_candidates
        if cut_candidate_meets_duration_floor(candidate, min_selected_duration_seconds)
    ]
    duration_floor_filtered_count = len(eligible_vlm_candidates) - len(duration_eligible_vlm_candidates)
    vlm_candidates = shortlist_movement_cut_vlm_candidates(duration_eligible_vlm_candidates)
    motion_coverage_fallback = any(
        not movement_cut_candidate_passes_motion_coverage(candidate)
        and not movement_cut_candidate_has_hard_motion_rejection(candidate)
        for candidate in candidates
    )
    if not vlm_candidates:
        return (
            LoopRanking(
                score=0.0,
                reasons=dedupe_text(
                    [
                        "movement_cut_candidate_window_choice_failed",
                        "movement_cut_deterministic_motion_gate_failed",
                        *(["movement_cut_target_motion_gate_failed"] if target_motion_gate_failed else []),
                        *hard_motion_rejection_reasons,
                    ]
                ),
                payload={
                    "score": 0.0,
                    "modelScore": 0.0,
                    "movementCutCandidates": source_cut_candidates_payload(all_candidates),
                    "movementCutVlmInputCandidates": [],
                    **movement_cut_manual_trim_payload(
                        reason="movement_cut_deterministic_motion_gate_failed",
                        candidates=all_candidates,
                    ),
                    "movementCutVisualIntegrityFilteredCount": len(all_candidates) - len(candidates),
                    "movementCutVisualIntegrityFallback": visual_integrity_fallback,
                    "movementCutMotionCoverageFilteredCount": len(candidates),
                    "movementCutMotionCoverageFallback": motion_coverage_fallback,
                    "movementCutHardMotionRejectedCount": hard_motion_rejected_count,
                    "movementCutHardMotionRejectionReasons": hard_motion_rejection_reasons,
                    "movementCutTargetMotionGateFailed": target_motion_gate_failed,
                    "movementCutVlmEligibleCandidateCount": len(eligible_vlm_candidates),
                    "movementCutDurationFloorFilteredCount": duration_floor_filtered_count,
                    "movementCutMinSelectedDurationSeconds": min_selected_duration_seconds,
                    "movementCutVlmShortlistedCandidateCount": 0,
                    "movementCutVlmShortlistMaxCandidateCount": MOVEMENT_CUT_MAX_INITIAL_VLM_CANDIDATES,
                    "movementCutVlmShortlistFilteredCount": 0,
                    "movementCutDeterministicMotionGateFailed": True,
                    "finalCutResponsibility": "movement_window_selection_only",
                },
                model_score=0.0,
            ),
            render_seconds,
            0.0,
        )
    movement_scorecard_has_contract = exercise_motion_contract_for_prompt(exercise_motion_contract) is not None
    review_choice = rank_cut_candidates_shortest_first_with_caption_images(
        candidates=vlm_candidates,
        caption_images=caption_images,
        prompt_builder=lambda candidate: build_movement_cut_candidate_choice_prompt(
            exercise_name=item.exercise_name,
            candidate_title=item.candidate_title,
            candidate=candidate,
            exercise_motion_contract=exercise_motion_contract,
            minimum_complete_duration_seconds=min_selected_duration_seconds,
        ),
        parser=lambda raw, candidate: parse_movement_cut_candidate_choice(
            raw,
            [candidate],
            min_duration_seconds=min_selected_duration_seconds,
            has_contract=movement_scorecard_has_contract,
            exercise_motion_contract=exercise_motion_contract,
        ),
        max_workers=max_vlm_workers,
        caption_image_kwargs=cut_candidate_vlm_caption_kwargs(),
    )
    vlm_seconds = review_choice.elapsed_seconds
    all_review_rankings = list(review_choice.rankings)
    all_raw_responses = list(review_choice.raw_responses)
    all_errors = list(review_choice.errors)
    all_reviewed_candidate_ids: list[str] = []
    seen_reviewed_candidate_ids: set[str] = set()
    for reviewed_candidate_id in review_choice.reviewed_candidate_ids:
        if reviewed_candidate_id in seen_reviewed_candidate_ids:
            continue
        seen_reviewed_candidate_ids.add(reviewed_candidate_id)
        all_reviewed_candidate_ids.append(reviewed_candidate_id)
    ranking = review_choice.ranking
    initial_movement_cut_scorecard_rows = collect_ranking_payload_rows(
        all_review_rankings,
        "movementCutScorecardCandidates",
    )
    targeted_refinement_allowed = shortest_passing_cut_ranking(all_review_rankings) is None
    targeted_refinement_specs = (
        movement_cut_targeted_refinement_specs(
            rows=initial_movement_cut_scorecard_rows,
            candidates_by_id={
                normalize_source_cut_candidate_id(candidate.candidate_id): candidate
                for candidate in vlm_candidates
            },
            existing_windows=[candidate.window for candidate in all_candidates],
            min_duration_seconds=min_selected_duration_seconds,
        )
        if targeted_refinement_allowed
        else []
    )
    targeted_all_candidates: list[SourceCutCandidate] = []
    targeted_candidates: list[SourceCutCandidate] = []
    targeted_review_choice: CutCandidateReviewChoice | None = None
    for spec in targeted_refinement_specs:
        targeted_candidate = build_movement_cut_review_candidate(
            item=item,
            candidate_id=spec.candidate_id,
            candidate_window=spec.window,
            output_dir=(
                output_dir
                / "targeted_boundary_refinement"
                / f"movement_cut_candidate_{spec.candidate_id}"
            ),
            frame_count=frame_count,
            timeline_window=timeline_window,
            chunk_estimate=chunk_estimate,
            exercise_motion_contract=exercise_motion_contract,
            chunking={
                "strategy": "targeted_boundary_refinement",
                "parentCandidateId": spec.parent_candidate_id,
                "reasons": spec.reasons,
            },
        )
        if targeted_candidate is None:
            continue
        targeted_all_candidates.append(targeted_candidate)
        if source_cut_candidate_passes_visual_integrity(targeted_candidate):
            targeted_candidates.append(targeted_candidate)
    if targeted_candidates:
        targeted_review_choice = rank_cut_candidates_shortest_first_with_caption_images(
            candidates=targeted_candidates,
            caption_images=caption_images,
            prompt_builder=lambda candidate: build_movement_cut_candidate_choice_prompt(
                exercise_name=item.exercise_name,
                candidate_title=item.candidate_title,
                candidate=candidate,
                exercise_motion_contract=exercise_motion_contract,
                minimum_complete_duration_seconds=min_selected_duration_seconds,
            ),
            parser=lambda raw, candidate: parse_movement_cut_candidate_choice(
                raw,
                [candidate],
                min_duration_seconds=min_selected_duration_seconds,
                has_contract=movement_scorecard_has_contract,
                exercise_motion_contract=exercise_motion_contract,
            ),
            max_workers=max_vlm_workers,
            caption_image_kwargs=cut_candidate_vlm_caption_kwargs(),
        )
        vlm_seconds += targeted_review_choice.elapsed_seconds
        all_review_rankings.extend(targeted_review_choice.rankings)
        all_raw_responses.extend(targeted_review_choice.raw_responses)
        all_errors.extend(targeted_review_choice.errors)
        for reviewed_candidate_id in targeted_review_choice.reviewed_candidate_ids:
            if reviewed_candidate_id in seen_reviewed_candidate_ids:
                continue
            seen_reviewed_candidate_ids.add(reviewed_candidate_id)
            all_reviewed_candidate_ids.append(reviewed_candidate_id)
        best_combined_ranking = shortest_passing_cut_ranking(all_review_rankings)
        if best_combined_ranking is not None:
            ranking = best_combined_ranking
        elif ranking is None:
            ranking = targeted_review_choice.ranking

    all_candidates_for_payload = [*all_candidates, *targeted_all_candidates]
    all_filter_candidates = [*candidates, *targeted_candidates]
    all_vlm_candidates = [*vlm_candidates, *targeted_candidates]
    reviewed_vlm_candidates = cut_candidates_with_ids(all_vlm_candidates, all_reviewed_candidate_ids)
    movement_cut_motion_coverage_filtered_count = len(candidates) - len(eligible_vlm_candidates)
    movement_cut_vlm_shortlist_filtered_count = len(duration_eligible_vlm_candidates) - len(vlm_candidates)
    movement_cut_scorecard_rows = collect_ranking_payload_rows(
        all_review_rankings,
        "movementCutScorecardCandidates",
    )
    targeted_refinement_reviewed_request_count = (
        targeted_review_choice.reviewed_request_count
        if targeted_review_choice is not None
        else 0
    )
    if ranking is None:
        manual_trim_reason = (
            "movement_cut_scorecard_no_passing_candidate"
            if movement_cut_scorecard_rows
            else "movement_cut_candidate_choice_invalid_response"
        )
        return (
            LoopRanking(
                score=0.0,
                reasons=dedupe_text(["movement_cut_candidate_window_choice_failed", manual_trim_reason]),
                raw_response=all_raw_responses[-1] if all_raw_responses else None,
                payload={
                    "score": 0.0,
                    "modelScore": 0.0,
                    "movementCutCandidates": source_cut_candidates_payload(all_candidates_for_payload),
                    "movementCutVlmInputCandidates": source_cut_candidates_payload(reviewed_vlm_candidates),
                    **movement_cut_manual_trim_payload(
                        reason=manual_trim_reason,
                        candidates=all_candidates_for_payload,
                        scorecard_rows=movement_cut_scorecard_rows,
                    ),
                    "movementCutMotionCoverageFilteredCount": movement_cut_motion_coverage_filtered_count,
                    "movementCutMotionCoverageFallback": motion_coverage_fallback,
                    "movementCutHardMotionRejectedCount": hard_motion_rejected_count,
                    "movementCutHardMotionRejectionReasons": hard_motion_rejection_reasons,
                    "movementCutTargetMotionGateFailed": target_motion_gate_failed,
                    "movementCutChoiceInvalidResponse": True,
                    "movementCutVlmReviewedCandidateCount": len(reviewed_vlm_candidates),
                    "movementCutVlmReviewedRequestCount": (
                        review_choice.reviewed_request_count
                        + targeted_refinement_reviewed_request_count
                    ),
                    "movementCutVlmRequestPolicy": "one_candidate_per_request",
                    "movementCutVlmEligibleCandidateCount": len(eligible_vlm_candidates),
                    "movementCutDurationFloorFilteredCount": duration_floor_filtered_count,
                    "movementCutVlmShortlistedCandidateCount": len(vlm_candidates),
                    "movementCutVlmShortlistMaxCandidateCount": MOVEMENT_CUT_MAX_INITIAL_VLM_CANDIDATES,
                    "movementCutVlmShortlistFilteredCount": movement_cut_vlm_shortlist_filtered_count,
                    "movementCutVlmShortlistCandidateIds": [candidate.candidate_id for candidate in vlm_candidates],
                    "movementCutVlmRequestTimeoutSeconds": CUT_CANDIDATE_VLM_REQUEST_TIMEOUT_SECONDS,
                    "movementCutMinSelectedDurationSeconds": min_selected_duration_seconds,
                    "movementCutVlmRequestErrors": all_errors,
                    "movementCutScorecardCandidates": movement_cut_scorecard_rows,
                    "movementCutScorecardContractPresent": movement_scorecard_has_contract,
                    "movementCutScorecardThresholds": source_cut_scorecard_thresholds(
                        has_contract=movement_scorecard_has_contract,
                    ),
                    "movementCutTargetedBoundaryRefinementEnabled": True,
                    "movementCutTargetedBoundaryRefinementAllowed": targeted_refinement_allowed,
                    "movementCutTargetedBoundaryRefinementTriggered": bool(targeted_refinement_specs),
                    "movementCutTargetedBoundaryRefinementSpecCount": len(targeted_refinement_specs),
                    "movementCutTargetedBoundaryRefinementCandidateCount": len(targeted_all_candidates),
                    "movementCutTargetedBoundaryRefinementVlmCandidateCount": len(targeted_candidates),
                    "movementCutTargetedBoundaryRefinementVisualIntegrityFilteredCount": (
                        len(targeted_all_candidates) - len(targeted_candidates)
                    ),
                    "movementCutTargetedBoundaryRefinementReviewedRequestCount": (
                        targeted_refinement_reviewed_request_count
                    ),
                    "movementCutTargetedBoundaryRefinementCandidates": (
                        source_cut_candidates_payload(targeted_all_candidates)
                    ),
                    "exerciseMotionContractEnabled": use_exercise_motion_contract,
                    **(
                        {"exerciseMotionContract": exercise_motion_contract}
                        if exercise_motion_contract is not None
                        else {}
                    ),
                    "finalCutResponsibility": "movement_window_selection_only",
                },
                model_score=0.0,
            ),
            render_seconds,
            vlm_seconds,
        )
    ranking_payload = dict(ranking.payload) if isinstance(ranking.payload, dict) else {}
    ranking_payload["movementCutCandidates"] = source_cut_candidates_payload(all_candidates_for_payload)
    ranking_payload["movementCutVlmInputCandidates"] = source_cut_candidates_payload(reviewed_vlm_candidates)
    ranking_payload["movementCutVisualIntegrityFilteredCount"] = len(all_candidates_for_payload) - len(all_filter_candidates)
    ranking_payload["movementCutVisualIntegrityFallback"] = visual_integrity_fallback
    ranking_payload["movementCutMotionCoverageFilteredCount"] = movement_cut_motion_coverage_filtered_count
    ranking_payload["movementCutMotionCoverageFallback"] = motion_coverage_fallback
    ranking_payload["movementCutHardMotionRejectedCount"] = hard_motion_rejected_count
    ranking_payload["movementCutHardMotionRejectionReasons"] = hard_motion_rejection_reasons
    ranking_payload["movementCutTargetMotionGateFailed"] = target_motion_gate_failed
    ranking_payload["movementCutVlmReviewedCandidateCount"] = len(reviewed_vlm_candidates)
    ranking_payload["movementCutVlmReviewedRequestCount"] = (
        review_choice.reviewed_request_count
        + targeted_refinement_reviewed_request_count
    )
    ranking_payload["movementCutVlmRequestPolicy"] = "one_candidate_per_request"
    ranking_payload["movementCutVlmEligibleCandidateCount"] = len(eligible_vlm_candidates)
    ranking_payload["movementCutDurationFloorFilteredCount"] = duration_floor_filtered_count
    ranking_payload["movementCutVlmShortlistedCandidateCount"] = len(vlm_candidates)
    ranking_payload["movementCutVlmShortlistMaxCandidateCount"] = MOVEMENT_CUT_MAX_INITIAL_VLM_CANDIDATES
    ranking_payload["movementCutVlmShortlistFilteredCount"] = movement_cut_vlm_shortlist_filtered_count
    ranking_payload["movementCutVlmShortlistCandidateIds"] = [candidate.candidate_id for candidate in vlm_candidates]
    ranking_payload["movementCutVlmRequestTimeoutSeconds"] = CUT_CANDIDATE_VLM_REQUEST_TIMEOUT_SECONDS
    ranking_payload["movementCutMinSelectedDurationSeconds"] = min_selected_duration_seconds
    ranking_payload["movementCutVlmRequestErrors"] = all_errors
    ranking_payload["movementCutUnreviewedCandidateCount"] = max(
        0,
        len(eligible_vlm_candidates) + len(targeted_candidates) - len(reviewed_vlm_candidates),
    )
    ranking_payload["movementCutScorecardCandidates"] = movement_cut_scorecard_rows
    ranking_payload["movementCutScorecardContractPresent"] = movement_scorecard_has_contract
    ranking_payload["movementCutScorecardThresholds"] = source_cut_scorecard_thresholds(
        has_contract=movement_scorecard_has_contract,
    )
    ranking_payload["movementCutTargetedBoundaryRefinementEnabled"] = True
    ranking_payload["movementCutTargetedBoundaryRefinementAllowed"] = targeted_refinement_allowed
    ranking_payload["movementCutTargetedBoundaryRefinementTriggered"] = bool(targeted_refinement_specs)
    ranking_payload["movementCutTargetedBoundaryRefinementSpecCount"] = len(targeted_refinement_specs)
    ranking_payload["movementCutTargetedBoundaryRefinementCandidateCount"] = len(targeted_all_candidates)
    ranking_payload["movementCutTargetedBoundaryRefinementVlmCandidateCount"] = len(targeted_candidates)
    ranking_payload["movementCutTargetedBoundaryRefinementVisualIntegrityFilteredCount"] = (
        len(targeted_all_candidates) - len(targeted_candidates)
    )
    ranking_payload["movementCutTargetedBoundaryRefinementReviewedRequestCount"] = (
        targeted_refinement_reviewed_request_count
    )
    ranking_payload["movementCutTargetedBoundaryRefinementCandidates"] = (
        source_cut_candidates_payload(targeted_all_candidates)
    )
    ranking_payload["exerciseMotionContractEnabled"] = use_exercise_motion_contract
    if exercise_motion_contract is not None:
        ranking_payload["exerciseMotionContract"] = exercise_motion_contract
    ranking_payload["finalCutResponsibility"] = "movement_window_selection_only"
    if ranking.score <= 0.0:
        ranking_payload.update(
            movement_cut_manual_trim_payload(
                reason=(
                    "movement_cut_scorecard_no_passing_candidate"
                    if movement_cut_scorecard_rows
                    else "movement_cut_zero_score_no_clean_candidate"
                ),
                candidates=all_candidates_for_payload,
                scorecard_rows=movement_cut_scorecard_rows,
            )
        )
    ranking = replace(
        ranking,
        payload=ranking_payload,
    )
    selected_window = selected_window_from_cut_ranking(ranking)
    if selected_window is not None and selected_window_is_materially_shorter(
        parent_window=timeline_window,
        child_window=selected_window,
    ):
        refined = rank_movement_cut_candidates_with_caption_images(
            item=item,
            timeline_window=selected_window,
            chunk_estimate=chunk_estimate,
            output_dir=output_dir / f"refine_{_refinement_depth + 1:02d}",
            frame_count=frame_count,
            caption_images=caption_images,
            use_exercise_motion_contract=use_exercise_motion_contract,
            max_vlm_workers=max_vlm_workers,
            _refinement_depth=_refinement_depth + 1,
        )
        if refined is not None:
            refined_ranking, refined_render_seconds, refined_vlm_seconds = refined
            refined_selected_window = selected_window_from_cut_ranking(refined_ranking)
            if refined_selected_window is not None and selected_window_is_materially_shorter(
                parent_window=selected_window,
                child_window=refined_selected_window,
            ):
                stage = cut_refinement_stage_payload(
                    ranking=ranking,
                    parent_window=timeline_window,
                    selected_window=selected_window,
                    stage_index=_refinement_depth,
                    candidates_key="movementCutCandidates",
                    vlm_candidates_key="movementCutVlmInputCandidates",
                )
                return (
                    prepend_cut_refinement_stage(
                        refined_ranking,
                        stages_key="movementCutRefinementStages",
                        stage=stage,
                    ),
                    render_seconds + refined_render_seconds,
                    vlm_seconds + refined_vlm_seconds,
                )
    return ranking, render_seconds, vlm_seconds


def _video_duration_seconds_or_none(video_path: Path) -> float | None:
    try:
        duration = float(read_basic_video_metadata(video_path).duration_seconds)
    except Exception:
        return None
    if duration <= 0.0:
        return None
    return duration


def source_cut_candidate_is_kinematic(candidate: SourceCutCandidate) -> bool:
    chunking = candidate.chunking if isinstance(candidate.chunking, dict) else {}
    return str(chunking.get("strategy") or "") == KINEMATIC_CUT_STRATEGY


def source_window_spec_is_kinematic(spec: SourceWindowCandidateSpec) -> bool:
    chunking = spec.chunking if isinstance(spec.chunking, dict) else {}
    return str(chunking.get("strategy") or "") == KINEMATIC_CUT_STRATEGY


def kinematic_cut_debug_payload(
    plan: KinematicSourceCutPlan,
    *,
    used: bool = False,
) -> dict[str, Any]:
    return {
        "kinematicCutProposed": bool(plan.specs),
        "kinematicCutCandidateCount": len(plan.specs),
        "kinematicCutPolicy": plan.policy,
        "kinematicCutUsed": bool(used),
        "kinematicCutExpandedParentWindow": bool(plan.expanded_parent),
    }


def build_kinematic_source_cut_plan(
    *,
    pose_payload: dict[str, Any] | None,
    contract: dict[str, Any] | None,
    timeline_window: DetectionWindow,
    source_offset_seconds: float,
    video_duration_seconds: float | None = None,
    max_proposals: int = KINEMATIC_CUT_MAX_PROPOSALS,
) -> KinematicSourceCutPlan:
    """Map pose-cycle proposals onto the detection-video timeline."""
    samples = pose_payload.get("dominantPoseSamples") if isinstance(pose_payload, dict) else None
    if not kinematic_contract_completion_mode(contract):
        return KinematicSourceCutPlan(
            specs=(),
            timeline_window=timeline_window,
            expanded_parent=False,
        )
    original_start = float(source_offset_seconds) + float(timeline_window.start_seconds)
    original_end = float(source_offset_seconds) + float(timeline_window.end_seconds)
    proposals = propose_source_cut(
        contract=contract,
        dominant_pose_samples=samples if isinstance(samples, list) else None,
        max_proposals=max_proposals,
        span_start_seconds=original_start,
        span_end_seconds=original_end,
        span_pad_seconds=DEFAULT_SPAN_PAD_SECONDS,
    )
    specs: list[SourceWindowCandidateSpec] = []
    for proposal in proposals:
        start_seconds = proposal.start_seconds - float(source_offset_seconds)
        end_seconds = proposal.end_seconds - float(source_offset_seconds)
        start_seconds = max(0.0, start_seconds)
        if video_duration_seconds is not None:
            end_seconds = min(video_duration_seconds, end_seconds)
        if end_seconds - start_seconds < SOURCE_CUT_REFINEMENT_MIN_SECONDS:
            continue
        specs.append(
            SourceWindowCandidateSpec(
                window=DetectionWindow(
                    index=len(specs),
                    start_seconds=round(start_seconds, 3),
                    end_seconds=round(end_seconds, 3),
                ),
                chunking={
                    "strategy": KINEMATIC_CUT_STRATEGY,
                    "policy": proposal.policy,
                    "confidence": round(proposal.confidence, 4),
                    "parentStartSeconds": round(timeline_window.start_seconds, 3),
                    "parentEndSeconds": round(timeline_window.end_seconds, 3),
                    "originalStartSeconds": round(proposal.start_seconds, 3),
                    "originalEndSeconds": round(proposal.end_seconds, 3),
                    **{
                        key: round(value, 4) if isinstance(value, float) else value
                        for key, value in proposal.stats.items()
                    },
                },
            )
        )
    if not specs:
        return KinematicSourceCutPlan(
            specs=(),
            timeline_window=timeline_window,
            expanded_parent=False,
        )
    expanded_start = min(timeline_window.start_seconds, *(spec.window.start_seconds for spec in specs))
    expanded_end = max(timeline_window.end_seconds, *(spec.window.end_seconds for spec in specs))
    if video_duration_seconds is not None:
        expanded_start = max(0.0, min(expanded_start, video_duration_seconds))
        expanded_end = max(expanded_start, min(expanded_end, video_duration_seconds))
    else:
        expanded_start = max(0.0, expanded_start)
    expanded = (
        expanded_start < timeline_window.start_seconds - 1e-3
        or expanded_end > timeline_window.end_seconds + 1e-3
    )
    expanded_window = (
        DetectionWindow(
            index=timeline_window.index,
            start_seconds=round(expanded_start, 3),
            end_seconds=round(expanded_end, 3),
        )
        if expanded
        else timeline_window
    )
    return KinematicSourceCutPlan(
        specs=tuple(
            SourceWindowCandidateSpec(
                window=DetectionWindow(
                    index=index,
                    start_seconds=spec.window.start_seconds,
                    end_seconds=spec.window.end_seconds,
                ),
                chunking=spec.chunking,
            )
            for index, spec in enumerate(specs)
        ),
        timeline_window=expanded_window,
        expanded_parent=expanded,
        policy=str(specs[0].chunking.get("policy") or "") or None,
    )


def kinematic_original_source_span(
    *,
    pose_payload: dict[str, Any] | None,
    contract: dict[str, Any] | None,
    original_start_seconds: float,
    original_end_seconds: float,
    original_duration_seconds: float | None = None,
) -> tuple[float, float] | None:
    """Union the current original-source window with overlapping kinematic cycles."""
    samples = pose_payload.get("dominantPoseSamples") if isinstance(pose_payload, dict) else None
    if not kinematic_contract_completion_mode(contract):
        return None
    proposals = propose_source_cut(
        contract=contract,
        dominant_pose_samples=samples if isinstance(samples, list) else None,
        max_proposals=KINEMATIC_CUT_MAX_PROPOSALS,
        span_start_seconds=original_start_seconds,
        span_end_seconds=original_end_seconds,
        span_pad_seconds=DEFAULT_SPAN_PAD_SECONDS,
    )
    if not proposals:
        return None
    start_seconds = min(original_start_seconds, *(proposal.start_seconds for proposal in proposals))
    end_seconds = max(original_end_seconds, *(proposal.end_seconds for proposal in proposals))
    start_seconds = max(0.0, start_seconds)
    if original_duration_seconds is not None:
        end_seconds = min(original_duration_seconds, end_seconds)
    if end_seconds - start_seconds < SOURCE_CUT_REFINEMENT_MIN_SECONDS:
        return None
    if (
        start_seconds >= original_start_seconds - 1e-3
        and end_seconds <= original_end_seconds + 1e-3
    ):
        return None
    return (round(start_seconds, 3), round(end_seconds, 3))


def expand_detection_source_for_kinematic_cut(
    *,
    source_video_path: Path,
    detection_source_video_path: Path,
    source_window: DetectionWindow,
    detection_source_offset_seconds: float,
    pose_payload: dict[str, Any] | None,
    contract: dict[str, Any] | None,
    output_dir: Path,
) -> tuple[Path, DetectionWindow, float] | None:
    """Re-trim from the original source when a cycle extends past a clipped detection file."""
    original_start = float(detection_source_offset_seconds) + float(source_window.start_seconds)
    original_end = float(detection_source_offset_seconds) + float(source_window.end_seconds)
    original_duration = _video_duration_seconds_or_none(source_video_path)
    expanded_span = kinematic_original_source_span(
        pose_payload=pose_payload,
        contract=contract,
        original_start_seconds=original_start,
        original_end_seconds=original_end,
        original_duration_seconds=original_duration,
    )
    if expanded_span is None:
        return None
    new_start, new_end = expanded_span
    detection_duration = _video_duration_seconds_or_none(detection_source_video_path)
    file_original_start = float(detection_source_offset_seconds)
    file_original_end = (
        file_original_start + detection_duration
        if detection_duration is not None
        else original_end
    )
    if new_start + 1e-3 >= file_original_start and new_end - 1e-3 <= file_original_end:
        return (
            detection_source_video_path,
            DetectionWindow(
                index=0,
                start_seconds=max(0.0, new_start - detection_source_offset_seconds),
                end_seconds=max(
                    SOURCE_CUT_REFINEMENT_MIN_SECONDS,
                    new_end - detection_source_offset_seconds,
                ),
            ),
            detection_source_offset_seconds,
        )
    expanded_path = output_dir / "source_kinematic_expanded_chunk.mp4"
    expanded_path.parent.mkdir(parents=True, exist_ok=True)
    trim_video(
        source_path=source_video_path,
        output_path=expanded_path,
        start_seconds=new_start,
        end_seconds=new_end,
    )
    return (
        expanded_path,
        DetectionWindow(index=0, start_seconds=0.0, end_seconds=max(0.0, new_end - new_start)),
        new_start,
    )


def rank_source_video_cut_candidates_with_caption_images(
    *,
    video_path: Path,
    exercise_name: str,
    candidate_title: str,
    timeline_window: DetectionWindow,
    chunk_estimate: Any,
    output_dir: Path,
    frame_count: int,
    caption_images: Callable[..., str],
    exercise_motion_contract: dict[str, Any] | None = None,
    source_pose_prefilter_payload: dict[str, Any] | None = None,
    source_pose_offset_seconds: float = 0.0,
    max_vlm_workers: int = 1,
    request_timeout_seconds: float = DEFAULT_SOURCE_REVIEW_TIMEOUT_SECONDS,
    allow_progressive_without_pose: bool = False,
    include_boundary_audit: bool = True,
    progressive_source_selection: bool = True,
    prefer_largest_padded_candidate: bool = False,
    _refinement_depth: int = 0,
) -> tuple[LoopRanking, float, float] | None:
    render_started = time.perf_counter()
    incoming_timeline_window = timeline_window
    kinematic_plan = build_kinematic_source_cut_plan(
        pose_payload=source_pose_prefilter_payload,
        contract=exercise_motion_contract,
        timeline_window=timeline_window,
        source_offset_seconds=source_pose_offset_seconds,
        video_duration_seconds=_video_duration_seconds_or_none(video_path),
    )
    # Pyramid/scene search stays on the detection window. Expand only when a
    # kinematic cut needs footage outside it; never replace the parent with a
    # kinematic-only span.
    timeline_window = DetectionWindow(
        index=incoming_timeline_window.index,
        start_seconds=min(
            incoming_timeline_window.start_seconds,
            kinematic_plan.timeline_window.start_seconds,
        ),
        end_seconds=max(
            incoming_timeline_window.end_seconds,
            kinematic_plan.timeline_window.end_seconds,
        ),
    )
    scene_detection = detect_source_scene_boundaries(
        video_path,
        timeline_window=timeline_window,
        cache_path=output_dir / "source_scene_analysis.json",
    )
    scene_detection = add_source_scene_camera_stability(
        video_path,
        timeline_window=timeline_window,
        scene_detection=scene_detection,
        pose_payload=source_pose_prefilter_payload,
        source_offset_seconds=source_pose_offset_seconds,
        cache_path=output_dir / "source_scene_analysis.json",
    )
    all_scene_windows = cut_free_source_scene_windows(
        scene_detection,
        timeline_window=timeline_window,
    )
    scene_windows = candidate_source_scene_windows(
        scene_detection,
        timeline_window=timeline_window,
    )
    min_duration_floor_seconds = source_cut_min_candidate_duration_seconds(
        chunk_estimate=chunk_estimate,
        exercise_motion_contract=exercise_motion_contract,
    )
    source_pose_sample_count = source_pose_prefilter_sample_count(source_pose_prefilter_payload)
    has_source_window_pose_evidence = (
        source_pose_sample_count > 0
        or bool(source_cut_pose_valid_chunks(source_pose_prefilter_payload))
    )
    # Only enter the "progressive without pose" mode when explicitly allowed.
    # Otherwise, fall back to normal scene/pyramid candidate generation.
    progressive_without_pose = (
        not has_source_window_pose_evidence
        and bool(allow_progressive_without_pose)
    )
    if progressive_without_pose:
        pyramid_specs = build_source_video_pyramid_candidate_windows(
            window=timeline_window,
            chunk_estimate=chunk_estimate,
            min_duration_floor_seconds=min_duration_floor_seconds,
            use_estimated_duration_floor=not contract_accepts_ongoing_action_interval(
                exercise_motion_contract
            ),
        )
        candidate_window_specs = []
        for index, spec in enumerate(pyramid_specs):
            if isinstance(spec, DetectionWindow):
                window = spec
                base_chunking: dict[str, Any] = {}
            else:
                window = spec.window
                base_chunking = dict(spec.chunking)
            candidate_window_specs.append(
                SourceWindowCandidateSpec(
                    window=DetectionWindow(
                        index=index,
                        start_seconds=window.start_seconds,
                        end_seconds=window.end_seconds,
                    ),
                    chunking={
                        **base_chunking,
                        "strategy": "duration_pyramid_no_pose_progressive",
                        "parentStartSeconds": timeline_window.start_seconds,
                        "parentEndSeconds": timeline_window.end_seconds,
                        "parentDurationSeconds": round(
                            timeline_window.end_seconds - timeline_window.start_seconds,
                            3,
                        ),
                        "minDurationFloorSeconds": round(min_duration_floor_seconds, 3),
                    },
                )
            )
    else:
        candidate_window_specs = build_scene_aware_source_video_candidate_windows(
            timeline_window=timeline_window,
            scene_detection=scene_detection,
            chunk_estimate=chunk_estimate,
            min_duration_floor_seconds=min_duration_floor_seconds,
            use_estimated_duration_floor=not contract_accepts_ongoing_action_interval(
                exercise_motion_contract
            ),
        )
    if kinematic_plan.specs:
        candidate_window_specs = [
            *kinematic_plan.specs,
            *[spec for spec in candidate_window_specs if not source_window_spec_is_kinematic(spec)],
        ]
    if not candidate_window_specs:
        return None
    original_candidate_window_spec_count = len(candidate_window_specs)
    if source_pose_prefilter_has_samples(source_pose_prefilter_payload):
        kinematic_specs = [spec for spec in candidate_window_specs if source_window_spec_is_kinematic(spec)]
        grid_specs = [spec for spec in candidate_window_specs if not source_window_spec_is_kinematic(spec)]
        grid_budget = max(0, SOURCE_CUT_MAX_MATERIALIZED_CANDIDATES - len(kinematic_specs))
        shortlisted_grid = (
            []
            if grid_budget <= 0
            else shortlist_source_window_specs_by_pose(
                grid_specs,
                pose_payload=source_pose_prefilter_payload or {},
                exercise_name=exercise_name,
                chunk_estimate=chunk_estimate,
                exercise_motion_contract=exercise_motion_contract,
                source_offset_seconds=source_pose_offset_seconds,
                max_candidates=grid_budget,
            )
        )
        candidate_window_specs = [
            *kinematic_specs,
            *shortlisted_grid,
        ]
    candidate_window_specs = [
        SourceWindowCandidateSpec(
            window=DetectionWindow(
                index=index,
                start_seconds=spec.window.start_seconds,
                end_seconds=spec.window.end_seconds,
            ),
            chunking=spec.chunking,
        )
        for index, spec in enumerate(candidate_window_specs)
    ]
    candidates: list[SourceCutCandidate] = []
    all_candidates: list[SourceCutCandidate] = []

    def materialize_source_candidate(
        index: int,
        candidate_spec: SourceWindowCandidateSpec | DetectionWindow,
    ) -> SourceCutCandidate | None:
        if isinstance(candidate_spec, DetectionWindow):
            candidate_window = candidate_spec
            candidate_chunking: dict[str, Any] = {}
        else:
            candidate_window = candidate_spec.window
            candidate_chunking = candidate_spec.chunking
        candidate_id = source_cut_candidate_id_for_index(index)
        candidate_output_dir = output_dir / f"source_candidate_{candidate_id}"
        frame_paths = render_video_window_contact_sheet(
            video_path=video_path,
            window=candidate_window,
            output_dir=candidate_output_dir,
            frame_count=cut_candidate_contact_sheet_frame_count(frame_count),
            contact_sheet_tile_width=SOURCE_CUT_CONTACT_SHEET_CELL_WIDTH,
            contact_sheet_frames_per_sheet_override=SOURCE_CUT_CONTACT_SHEET_FRAMES_PER_SHEET,
            contact_sheet_jpeg_quality=SOURCE_CUT_CONTACT_SHEET_JPEG_QUALITY,
        )
        candidate = build_source_cut_candidate(
            candidate_id=candidate_id,
            candidate_window=candidate_window,
            contact_sheet_paths=frame_paths,
            output_dir=candidate_output_dir,
            pose_prefilter=source_cut_candidate_pose_prefilter_metrics(
                candidate_window=candidate_window,
                pose_payload=source_pose_prefilter_payload,
                source_offset_seconds=source_pose_offset_seconds,
            ),
            chunking=candidate_chunking,
            scene_integrity=source_cut_scene_integrity_metrics(
                scene_detection,
                candidate_window=candidate_window,
            ),
            camera_stability=(
                candidate_chunking.get("backgroundCameraStability")
                if isinstance(candidate_chunking, dict)
                else None
            ),
            include_boundary_audit=include_boundary_audit,
        )
        if candidate is not None and source_pose_prefilter_has_samples(source_pose_prefilter_payload):
            candidate = replace(
                candidate,
                motion_coverage=source_cut_candidate_motion_coverage_metrics(
                    candidate_window=candidate_window,
                    pose_payload=source_pose_prefilter_payload or {},
                    exercise_name=exercise_name,
                    chunk_estimate=chunk_estimate,
                    exercise_motion_contract=exercise_motion_contract,
                    source_offset_seconds=source_pose_offset_seconds,
                ),
            )
        return candidate

    indexed_specs = list(enumerate(candidate_window_specs))
    render_worker_count = min(SOURCE_CUT_MAX_RENDER_WORKERS, len(indexed_specs))
    if render_worker_count <= 1:
        materialized_candidates = [
            materialize_source_candidate(index, candidate_spec)
            for index, candidate_spec in indexed_specs
        ]
    else:
        with ThreadPoolExecutor(max_workers=render_worker_count) as executor:
            materialized_candidates = list(
                executor.map(
                    lambda indexed_spec: materialize_source_candidate(*indexed_spec),
                    indexed_specs,
                )
            )

    for candidate in materialized_candidates:
        if candidate is not None:
            all_candidates.append(candidate)
            if source_cut_candidate_eligible_for_vlm(candidate):
                candidates.append(candidate)
    render_seconds = elapsed_seconds(render_started)
    if not candidates:
        visual_filtered_count = sum(
            1
            for candidate in all_candidates
            if not source_cut_candidate_passes_visual_integrity(candidate)
        )
        pose_filtered_count = sum(
            1
            for candidate in all_candidates
            if source_cut_candidate_passes_visual_integrity(candidate)
            and source_cut_candidate_passes_frame_motion(candidate)
            and not source_cut_candidate_passes_pose_prefilter(candidate)
        )
        frame_motion_filtered_count = sum(
            1
            for candidate in all_candidates
            if source_cut_candidate_passes_visual_integrity(candidate)
            and not source_cut_candidate_passes_frame_motion(candidate)
        )
        return (
            LoopRanking(
                score=0.0,
                reasons=[
                    "source_candidate_window_choice_failed",
                    "source_cut_deterministic_candidate_filter_failed",
                ],
                payload={
                    "score": 0.0,
                    "modelScore": 0.0,
                    "sourceCutCandidates": source_cut_candidates_payload(all_candidates),
                    "sourceCutDeterministicCandidateFilterFailed": True,
                    "sourceCutVisualIntegrityFilteredCount": visual_filtered_count,
                    "sourceCutFrameMotionFilteredCount": frame_motion_filtered_count,
                    "sourceCutMotionCoverageFilteredCount": sum(
                        1
                        for candidate in all_candidates
                        if not source_cut_candidate_passes_motion_coverage(candidate)
                    ),
                    "sourceCutMotionCoverageDiagnosticFailedCount": sum(
                        1
                        for candidate in all_candidates
                        if candidate.motion_coverage and not bool(candidate.motion_coverage.get("passed", True))
                    ),
                    "sourceCutPosePrefilterFilteredCount": pose_filtered_count,
                    "sourceCutSourcePoseSampleCount": source_pose_sample_count,
                    "sourceCutProgressiveDisabledReason": (
                        "source_pose_samples_unavailable" if progressive_without_pose else None
                    ),
                    "sourceCutProgressiveWithoutPoseAllowed": bool(allow_progressive_without_pose),
                    "sourceCutBoundaryAuditEnabled": bool(include_boundary_audit),
                    "sourceCutProposedCandidateCount": original_candidate_window_spec_count,
                    "sourceCutMaterializedCandidateCount": len(candidate_window_specs),
                    "sourceCutMaterializedCandidateLimit": SOURCE_CUT_MAX_MATERIALIZED_CANDIDATES,
                    "exerciseMotionContract": exercise_motion_contract,
                    **kinematic_cut_debug_payload(kinematic_plan),
                },
                model_score=0.0,
            ),
            render_seconds,
            0.0,
        )
    source_scorecard_has_contract = exercise_motion_contract_for_prompt(exercise_motion_contract) is not None
    effective_source_cut_vlm_workers = min(max(1, int(max_vlm_workers)), SOURCE_CUT_MAX_VLM_WORKERS)
    source_cut_caption_kwargs = source_cut_vlm_caption_kwargs(request_timeout_seconds)

    def parse_source_candidate_with_boundary_validation(
        raw: str,
        candidate: SourceCutCandidate,
    ) -> LoopRanking | None:
        return parse_source_cut_candidate_choice(
            raw,
            [candidate],
            has_contract=source_scorecard_has_contract,
            exercise_motion_contract=exercise_motion_contract,
            required_equipment=two_scale_named_equipment(exercise_name),
        )

    remaining_vlm_candidates = list(candidates)
    review_rankings: list[LoopRanking] = []
    review_raw_responses: list[str] = []
    review_errors: list[dict[str, Any]] = []
    reviewed_candidate_ids: list[str] = []
    reviewed_request_count = 0
    review_elapsed_seconds = 0.0
    review_recoveries: list[dict[str, Any]] = []
    selected_ranking: LoopRanking | None = None
    kinematic_first_pass_done = False
    while remaining_vlm_candidates and selected_ranking is None:
        kinematic_batch = [
            candidate
            for candidate in remaining_vlm_candidates
            if source_cut_candidate_is_kinematic(candidate)
        ]
        if kinematic_batch and not kinematic_first_pass_done:
            vlm_shortlist = kinematic_batch[:KINEMATIC_CUT_MAX_PROPOSALS]
            kinematic_first_pass_done = True
        else:
            vlm_shortlist = shortlist_movement_cut_vlm_candidates(
                remaining_vlm_candidates,
                max_candidates=SOURCE_CUT_MAX_VLM_CANDIDATES,
            )
        batch_choice, recovery = run_source_cut_review_with_adaptive_recovery(
            lambda workers, caption_kwargs: rank_cut_candidates_shortest_first_with_caption_images(
                candidates=vlm_shortlist,
                caption_images=caption_images,
                prompt_builder=lambda candidate: build_source_cut_candidate_choice_prompt(
                    exercise_name=exercise_name,
                    candidate_title=candidate_title,
                    candidate=candidate,
                    exercise_motion_contract=exercise_motion_contract,
                ),
                parser=parse_source_candidate_with_boundary_validation,
                max_workers=workers,
                prefer_largest_padded_candidate=prefer_largest_padded_candidate,
                progressive_source_selection=progressive_source_selection,
                progressive_source_early_stop=False,
                progressive_pad_one_stable_level=not contract_accepts_ongoing_action_interval(
                    exercise_motion_contract
                ),
                caption_image_kwargs=caption_kwargs,
                exercise_motion_contract=exercise_motion_contract,
            ),
            max_workers=effective_source_cut_vlm_workers,
            caption_image_kwargs=source_cut_caption_kwargs,
        )
        if recovery is not None:
            review_recoveries.append(recovery)
        review_rankings.extend(batch_choice.rankings)
        review_raw_responses.extend(batch_choice.raw_responses)
        review_errors.extend(batch_choice.errors)
        reviewed_candidate_ids.extend(batch_choice.reviewed_candidate_ids)
        reviewed_request_count += batch_choice.reviewed_request_count
        review_elapsed_seconds += batch_choice.elapsed_seconds
        selected_ranking = batch_choice.ranking
        batch_ids = {candidate.candidate_id for candidate in vlm_shortlist}
        remaining_vlm_candidates = [
            candidate
            for candidate in remaining_vlm_candidates
            if candidate.candidate_id not in batch_ids
        ]
    review_choice = CutCandidateReviewChoice(
        ranking=selected_ranking,
        raw_responses=review_raw_responses,
        errors=review_errors,
        reviewed_candidate_ids=dedupe_text(reviewed_candidate_ids),
        reviewed_request_count=reviewed_request_count,
        elapsed_seconds=review_elapsed_seconds,
        rankings=review_rankings,
    )
    vlm_seconds = review_choice.elapsed_seconds
    ranking = review_choice.ranking
    reviewed_vlm_candidates = cut_candidates_with_ids(candidates, review_choice.reviewed_candidate_ids)
    source_cut_scorecard_rows = collect_ranking_payload_rows(review_choice.rankings, "sourceCutScorecardCandidates")
    if ranking is None:
        no_selection_reasons = ["source_candidate_window_choice_failed"]
        if source_cut_scorecard_rows:
            no_selection_reasons.append("source_candidate_scorecard_no_passing_candidate")
        else:
            no_selection_reasons.append("source_candidate_choice_invalid_response")
        return (
            LoopRanking(
                score=0.0,
                reasons=dedupe_text(no_selection_reasons),
                raw_response=review_choice.raw_responses[-1] if review_choice.raw_responses else None,
                payload={
                    "score": 0.0,
                    "modelScore": 0.0,
                    "sourceCutCandidates": source_cut_candidates_payload(all_candidates),
                    "sourceCutVlmInputCandidates": source_cut_candidates_payload(reviewed_vlm_candidates),
                    "sourceCutVisualIntegrityFilteredCount": sum(
                        1
                        for candidate in all_candidates
                        if not source_cut_candidate_passes_visual_integrity(candidate)
                    ),
                    "sourceCutPosePrefilterFilteredCount": sum(
                        1
                        for candidate in all_candidates
                        if source_cut_candidate_passes_visual_integrity(candidate)
                        and source_cut_candidate_passes_frame_motion(candidate)
                        and not source_cut_candidate_passes_pose_prefilter(candidate)
                    ),
                    "sourceCutFrameMotionFilteredCount": sum(
                        1
                        for candidate in all_candidates
                        if source_cut_candidate_passes_visual_integrity(candidate)
                        and not source_cut_candidate_passes_frame_motion(candidate)
                    ),
                    "sourceCutMotionCoverageFilteredCount": sum(
                        1
                        for candidate in all_candidates
                        if not source_cut_candidate_passes_motion_coverage(candidate)
                    ),
                    "sourceCutMotionCoverageDiagnosticFailedCount": sum(
                        1
                        for candidate in all_candidates
                        if candidate.motion_coverage and not bool(candidate.motion_coverage.get("passed", True))
                    ),
                    "sourceChoiceInvalidResponse": not bool(source_cut_scorecard_rows),
                    "sourceCutVlmReviewedCandidateCount": len(reviewed_vlm_candidates),
                    "sourceCutVlmReviewedRequestCount": review_choice.reviewed_request_count,
                    "sourceCutVlmRequestPolicy": "one_candidate_per_request",
                    "sourceCutVlmRequestTimeoutSeconds": request_timeout_seconds,
                    "sourceCutMaxVlmWorkers": SOURCE_CUT_MAX_VLM_WORKERS,
                    "sourceCutEffectiveVlmWorkers": effective_source_cut_vlm_workers,
                    "sourceCutVlmRecoveries": review_recoveries,
                    "sourceCutVlmRequestErrors": review_choice.errors,
                    "sourceCutScorecardCandidates": source_cut_scorecard_rows,
                    "sourceCutScorecardContractPresent": source_scorecard_has_contract,
                    "sourceCutSourcePoseSampleCount": source_pose_sample_count,
                    "sourceCutProgressiveDisabledReason": (
                        "source_pose_samples_unavailable" if progressive_without_pose else None
                    ),
                    "sourceCutProgressiveWithoutPoseAllowed": bool(allow_progressive_without_pose),
                    "sourceCutBoundaryAuditEnabled": bool(include_boundary_audit),
                    "sourceCutProposedCandidateCount": original_candidate_window_spec_count,
                    "sourceCutMaterializedCandidateCount": len(candidate_window_specs),
                    "sourceCutMaterializedCandidateLimit": SOURCE_CUT_MAX_MATERIALIZED_CANDIDATES,
                    "sourceCutScorecardThresholds": source_cut_scorecard_thresholds(
                        has_contract=source_scorecard_has_contract,
                    ),
                    "exerciseMotionContract": exercise_motion_contract,
                    **kinematic_cut_debug_payload(kinematic_plan),
                },
                model_score=0.0,
            ),
            render_seconds,
            vlm_seconds,
        )
    ranking_payload = dict(ranking.payload) if isinstance(ranking.payload, dict) else {}
    ranking_payload["sourceCutCandidates"] = source_cut_candidates_payload(all_candidates)
    ranking_payload["sourceCutVlmInputCandidates"] = source_cut_candidates_payload(reviewed_vlm_candidates)
    ranking_payload["sourceCutDeterministicDirectSelection"] = False
    ranking_payload["sourceCutVisualIntegrityFilteredCount"] = sum(
        1
        for candidate in all_candidates
        if not source_cut_candidate_passes_visual_integrity(candidate)
    )
    ranking_payload["sourceCutPosePrefilterFilteredCount"] = sum(
        1
        for candidate in all_candidates
        if source_cut_candidate_passes_visual_integrity(candidate)
        and source_cut_candidate_passes_frame_motion(candidate)
        and not source_cut_candidate_passes_pose_prefilter(candidate)
    )
    ranking_payload["sourceCutFrameMotionFilteredCount"] = sum(
        1
        for candidate in all_candidates
        if source_cut_candidate_passes_visual_integrity(candidate)
        and not source_cut_candidate_passes_frame_motion(candidate)
    )
    ranking_payload["sourceCutMotionCoverageFilteredCount"] = sum(
        1
        for candidate in all_candidates
        if not source_cut_candidate_passes_motion_coverage(candidate)
    )
    ranking_payload["sourceCutMotionCoverageDiagnosticFailedCount"] = sum(
        1
        for candidate in all_candidates
        if candidate.motion_coverage and not bool(candidate.motion_coverage.get("passed", True))
    )
    ranking_payload["sourceCutVlmReviewedCandidateCount"] = len(reviewed_vlm_candidates)
    ranking_payload["sourceCutVlmReviewedRequestCount"] = review_choice.reviewed_request_count
    ranking_payload["sourceCutVlmRequestPolicy"] = "one_candidate_per_request"
    ranking_payload["sourceCutVlmRequestTimeoutSeconds"] = request_timeout_seconds
    ranking_payload["sourceCutMaxVlmWorkers"] = SOURCE_CUT_MAX_VLM_WORKERS
    ranking_payload["sourceCutEffectiveVlmWorkers"] = effective_source_cut_vlm_workers
    ranking_payload["sourceCutVlmRecoveries"] = review_recoveries
    ranking_payload["sourceCutVlmRequestErrors"] = review_choice.errors
    ranking_payload["sourceCutUnreviewedCandidateCount"] = max(0, len(candidates) - len(reviewed_vlm_candidates))
    ranking_payload["sourceCutScorecardCandidates"] = source_cut_scorecard_rows
    ranking_payload["sourceCutScorecardContractPresent"] = source_scorecard_has_contract
    ranking_payload["sourceCutSourcePoseSampleCount"] = source_pose_sample_count
    ranking_payload["sourceCutProgressiveDisabledReason"] = (
        "source_pose_samples_unavailable" if progressive_without_pose else None
    )
    ranking_payload["sourceCutProgressiveWithoutPoseAllowed"] = bool(allow_progressive_without_pose)
    ranking_payload["sourceCutBoundaryAuditEnabled"] = bool(include_boundary_audit)
    ranking_payload["sourceCutProposedCandidateCount"] = original_candidate_window_spec_count
    ranking_payload["sourceCutMaterializedCandidateCount"] = len(candidate_window_specs)
    ranking_payload["sourceCutMaterializedCandidateLimit"] = SOURCE_CUT_MAX_MATERIALIZED_CANDIDATES
    ranking_payload["sourceCutScorecardThresholds"] = source_cut_scorecard_thresholds(
        has_contract=source_scorecard_has_contract,
    )
    ranking_payload["exerciseMotionContract"] = exercise_motion_contract
    selected_id = normalize_source_cut_candidate_id(ranking_payload.get("selectedCandidateId"))
    kinematic_used = any(
        source_cut_candidate_is_kinematic(candidate)
        and normalize_source_cut_candidate_id(candidate.candidate_id) == selected_id
        for candidate in all_candidates
    )
    ranking_payload.update(kinematic_cut_debug_payload(kinematic_plan, used=kinematic_used))
    ranking = replace(
        ranking,
        payload=ranking_payload,
    )
    return ranking, render_seconds, vlm_seconds


def rank_review_items_with_llama_cpp(
    items: list[ReviewItem],
    request: BakeAndRankRequest,
    *,
    caption_images: Callable[..., str] | None = None,
) -> list[LoopRanking]:
    ranker = None if caption_images is not None else LlamaCppVisionRanker(build_llama_cpp_vision_settings(request))
    active_caption_images = caption_images if caption_images is not None else ranker.client.caption_images
    try:
        llm_indices = select_llm_review_item_indices(items, request)
        rankings: list[LoopRanking | None] = [
            None if index in llm_indices else build_prefilter_skipped_ranking(item, request)
            for index, item in enumerate(items)
        ]
        if not llm_indices:
            return [
                ranking if ranking is not None else LoopRanking(score=0.0, reasons=["review_item_ranking_missing"])
                for ranking in rankings
            ]
        workers = max(1, min(request.review_llm_workers, len(llm_indices)))
        if workers == 1:
            for index in llm_indices:
                item = items[index]
                rankings[index] = (
                    apply_loop_continuity_adjustment(
                        item,
                        rank_review_item_with_caption_images(item, request, active_caption_images),
                    )
                )
            return [
                ranking if ranking is not None else LoopRanking(score=0.0, reasons=["review_item_ranking_missing"])
                for ranking in rankings
            ]
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {
                executor.submit(rank_review_item_with_caption_images, item, request, active_caption_images): index
                for index, item in enumerate(items)
                if index in llm_indices
            }
            for future in as_completed(futures):
                index = futures[future]
                item = items[index]
                try:
                    ranking = future.result()
                except Exception as exc:
                    if is_critical_vlm_interaction_error(exc):
                        add_vlm_context(
                            exc,
                            stage="review_item_parallel_ranking",
                            itemIndex=index,
                            exerciseName=item.exercise_name,
                            candidateRank=item.candidate_rank,
                            candidateTitle=item.candidate_title,
                        )
                        raise
                    ranking = LoopRanking(
                        score=0.0,
                        reasons=["review_item_ranking_failed", str(exc)],
                    )
                rankings[index] = apply_loop_continuity_adjustment(item, ranking)
        return [
            ranking if ranking is not None else LoopRanking(score=0.0, reasons=["review_item_ranking_missing"])
            for ranking in rankings
        ]
    finally:
        if ranker is not None:
            ranker.close()


def select_llm_review_item_indices(items: list[ReviewItem], request: BakeAndRankRequest) -> set[int]:
    max_items = int(request.max_llm_review_items or 0)
    if max_items <= 0 or len(items) <= max_items:
        return set(range(len(items)))
    scored = [
        (review_item_prefilter_score(item, request), index)
        for index, item in enumerate(items)
    ]
    scored.sort(key=lambda item: (item[0], -items[item[1]].exercise_index, -items[item[1]].candidate_rank), reverse=True)
    selected: set[int] = set()
    seen_candidates: set[tuple[int, int]] = set()
    for _score, index in scored:
        candidate_key = (items[index].exercise_index, items[index].candidate_rank)
        if candidate_key in seen_candidates:
            continue
        selected.add(index)
        seen_candidates.add(candidate_key)
        if len(selected) >= max_items:
            return selected
    for _score, index in scored:
        selected.add(index)
        if len(selected) >= max_items:
            break
    return selected


def review_item_prefilter_score(item: ReviewItem, request: BakeAndRankRequest) -> float:
    duration_seconds = max(0.1, item.duration_sec)
    chunk_estimate = estimate_chunking(
        exercise_name=item.exercise_name,
        use_llm=False,
    )
    chunk_seconds = min(max(0.5, chunk_estimate.chunk_seconds), duration_seconds)
    chunk_overlap_seconds = min(max(0.0, chunk_estimate.chunk_overlap_seconds), max(0.0, chunk_seconds - 0.25))
    windows = iter_detection_windows(
        duration_seconds=duration_seconds,
        window_seconds=chunk_seconds,
        overlap_seconds=chunk_overlap_seconds,
    )
    candidates = select_review_windows_by_skeleton_motion(
        item,
        windows,
        max_windows=1,
    )
    if not candidates:
        return 0.0
    return float(candidates[0].score)


def build_prefilter_skipped_ranking(item: ReviewItem, request: BakeAndRankRequest) -> LoopRanking:
    score = min(LOOP_DETERMINISTIC_FALLBACK_SCORE_CAP, review_item_prefilter_score(item, request))
    return LoopRanking(
        score=score,
        reasons=["llm_review_skipped_by_prefilter"],
        payload={
            "score": score,
            "modelScore": score,
            "prefilterScore": score,
            "maxLlmReviewItems": request.max_llm_review_items,
        },
        model_score=score,
    )


